  ('cpiuris2025::e6cb7f883ffe854ff5a09e34fa493d1f', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Iniciativa Popular e Consultas Populares', '## Iniciativa Popular e Consultas Populares

A iniciativa popular é apresentada por um mínimo de 1% do eleitorado nacional, distribuído por 5 Estados, com pelo menos 3% dos eleitores de cada um. O projeto deve abordar um único assunto e não pode ser rejeitado por vício de forma.

### Conceitos
- **Iniciativa Popular**: Apresentação de projeto de lei à Câmara dos Deputados
- **Consultas Populares**: Processo em que o povo decide sobre questões políticas
- **Lei n.º 9.709/98**: Legislação que regula a iniciativa popular

### Referências legais
- Art. 13 da Lei n.º 9.709/98

### Dicas de prova
- Entenda a diferença entre iniciativa popular e consultas populares
- Conheça o mínimo de assinaturas necessárias para apresentar uma iniciativa popular', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.12 (2)", "page_number": 12, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 13 da Lei n.º 9.709/98"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:32:01.002852+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=12", "doc_key": "e6cb7f883ffe854ff5a09e34fa493d1f"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '47887f98d51d998bbfc2122e8a37e4cb3515333a51178d1271b091d7790ae0df'),
  ('cpiuris2025::6faa5889fd289cd54ce44af10a84decf', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Sufrágio Popular e Poder de Sufrágio', '## Sufrágio Popular e Poder de Sufrágio

O sufrágio é o poder que determinada camada da população tem de influir na gerência da vida pública, participando da soberania de um país. O voto é o instrumento para materializar o sufrágio, enquanto o escrutínio é a forma como se pratica o voto.

### Conceitos
- **Sufrágio**: Poder que determinada camada da população tem de influir na gerência da vida pública
- **Voto**: Instrumento para materializar o sufrágio
- **Escrutínio**: Forma como se pratica o voto, estabelecendo o procedimento
- **Sufrágio Universal**: Direito conferido a todos os cidadãos para participar do processo eleitoral
- **Sufrágio Restrito**: Poder de participação no processo eleitoral conferido apenas a pessoas que preenchem determinados requisitos
- **Censitário**: Restrição ao poder de sufrágio baseada no poder econômico do eleitor
- **Capacitário**: Poder de sufrágio conferido a quem tiver um certo grau de instrução
- **Racial**: Restrição ao exercício do poder do sufrágio em razão da etnia

### Referências legais
- Art. 60, II, da CF

### Dicas de prova
- Diferença entre sufrágio, voto e escrutínio
- Hipóteses de sufrágio existentes (sufrágio universal e restrito)
- Restrições ao sufrágio (censitário, capacitário e racial)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.13", "page_number": 13, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 60, II, da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:32:49.160936+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=13", "doc_key": "6faa5889fd289cd54ce44af10a84decf"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'e28fb9eba93433099b3e9e08d4d145b3873c504a9f9e71bd2015067dc9d3fcda'),
  ('cpiuris2025::45822b95dc42df5edd21a2a895aa52df', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Mandato Político e Sufrágio', '## Mandato Político e Sufrágio

O mandato político é o instituto de direito público que permite ao povo delegar poderes a seus representantes eleitos. O sufrágio é o direito de voto, podendo ser direto ou indireto.

### Conceitos
- **Sufrágio Plural**: O mesmo indivíduo pode exercer mais de uma vez o seu direito ao voto.
- **Sufrágio Singular**: Cada pessoa tem direito a um voto, como no Brasil.
- **Sufrágio Direto**: Poder exercido diretamente pelo cidadão.
- **Sufrágio Indireto**: Poder democrático exercido por representantes do povo.
- **Mandato Político Imperativo**: A teoria que estabelece a vinculação entre o mandatário e a vontade do mandante.
- **Mandato Político Representativo**: A teoria que prevaleceu a partir do século XVIII, caracterizada por irrevogabilidade, generalidade e independência.
- **Recall**: Instituto de direito político que permite que o eleitorado convoque consulta popular para revogar o mandato antes conferido.

### Referências legais
- Art. 5º da Constituição Brasileira
- Decreto n.º 21.076/1932

### Jurisprudência
- RE 123456
- Tema repetitivo do Mandato Político

### Dicas de prova
- Entenda a diferença entre sufrágio plural e singular.
- Conheça as características do mandato político representativo.
- Aprenda sobre o instituto de Recall e sua aplicação nos Estados Unidos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.14", "page_number": 14, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 5º da Constituição Brasileira", "Decreto n.º 21.076/1932"], "jurisprudence": ["RE 123456", "Tema repetitivo do Mandato Político"], "confidence": 0.8, "extracted_at": "2026-05-26T22:33:33.919802+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=14", "doc_key": "45822b95dc42df5edd21a2a895aa52df"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'ec0bf8285576ec1b5c182667834eefc47439e363d7aff5bba6edaab12666fdbe'),
  ('cpiuris2025::47c848a22a7957b4f2cd2aa1e0070c26', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Princípios do Direito Eleitoral', '## Princípios do Direito Eleitoral

Os princípios do direito eleitoral são fundamentais para garantir a igualdade e a celeridade nos processos eleitorais. A isonomia garante que todos os candidatos concorram em igualdade de condições, enquanto o princípio da celeridade busca andar com rapidez nos processos eleitorais.

### Conceitos
- **Isonomia**: Garantia de igualdade de condições para todos os candidatos
- **Celeridade**: Andamento rápido dos processos eleitorais
- **Anualidade eleitoral**: Princípio que determina a realização das eleições em um ano específico

### Referências legais
- Art. 258 do CE
- Súmula 728 do STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre teoria do mandato partidário e teoria do mandato político representativo
- Conheça os prazos processuais para recursos eleitorais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.15 (1)", "page_number": 15, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 258 do CE", "Súmula 728 do STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T22:34:17.765334+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=15", "doc_key": "47c848a22a7957b4f2cd2aa1e0070c26"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'cff84d25847751fc135d67eefdd65000e41813c71ac94f3b614a306233309549'),
  ('cpiuris2025::3d1ba2099485d3a67e37968ad0fdbf03', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Princípio da Anualidade', '## Princípio da Anualidade

O princípio da anualidade é cláusula pétrea que determina que a lei alterando o processo eleitoral entra em vigor na data de sua publicação, não se aplicando à eleição que ocorre até 1 ano da data de sua vigência.

### Conceitos
- **Princípio da Anualidade**: Cláusula pétrea que determina a entrada em vigor da lei alteradora do processo eleitoral na data de sua publicação.
- **Anualidade**: Período de tempo durante o qual uma lei ou norma entra em vigor sem necessidade de reeleição.

### Referências legais
- Art. 16 da CF

### Dicas de prova
- Entenda que a anualidade é cláusula pétrea e não se aplica às eleições que ocorrem antes do prazo estabelecido.
- Diferencie entre regras instrumentais e aquelas que alteram o processo eleitoral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.15 (2)", "page_number": 15, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 16 da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:34:41.822122+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=15", "doc_key": "3d1ba2099485d3a67e37968ad0fdbf03"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '8cc3ed2c0c5a8ed1bdcfd702a5ad2a0da7fe1d10786baa950fa07e28fa2edbe4'),
  ('cpiuris2025::a0ffd4e9e0b40c33b82fa6bc41a3b9df', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Princípios Fundamentais do Direito Eleitoral', '## Princípios Fundamentais do Direito Eleitoral

Os princípios fundamentais do direito eleitoral incluem o aproveitamento do voto, a moralidade eleitoral e o princípio republicano. O aproveitamento do voto busca preservar a vontade do eleitor, enquanto a moralidade eleitoral visa proteger a probidade administrativa. O princípio republicano é fundamental para garantir a alternância de poder mediante eleições regulares.

### Conceitos
- **Aproveitamento do voto**: Princípio que busca preservar a vontade do eleitor, mesmo em caso de inobservância de regras
- **Moralidade eleitoral**: Princípio que visa proteger a probidade administrativa e garantir a integridade das eleições
- **Princípio republicano**: Princípio que garante a alternância de poder mediante eleições regulares

### Referências legais
- Art. 14, §9º, da CF
- Súmula n.º 13 do TSE
- LC n.º 64/90

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância do aproveitamento do voto e sua relação com a moralidade eleitoral
- Conheça o princípio republicano e como ele garante a alternância de poder', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.16", "page_number": 16, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 14, §9º, da CF", "Súmula n.º 13 do TSE", "LC n.º 64/90"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T22:35:18.627356+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=16", "doc_key": "a0ffd4e9e0b40c33b82fa6bc41a3b9df"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'f2b03ba07f4a2d29466edd255e56973615f79cf4ac0683d972c5e4a0ec280732'),
  ('cpiuris2025::84fff126bd639be22b6177ea288a8f7c', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Plebiscito e Consulta Popular', '## Plebiscito e Consulta Popular

Resumo do texto sobre o plebiscito e consulta popular no Brasil, destacando as regras e procedimentos para a realização de um plebiscito convocado pelo Congresso Nacional.

### Conceitos
- **Convocado o plebiscito**: O projeto legislativo ou medida administrativa não efetivada, cujas matérias constituem objeto da consulta popular, terá sustada sua tramitação até que o resultado das urnas seja proclamado.
- **Maioria absoluta**: O plebiscito requer, para ser aprovado, maioria absoluta, de acordo com o resultado homologado pelo Tribunal Superior Eleitoral.
- **Divulgação de postulados**: Aprovado o ato convocatório de plebiscito, o Presidente do Congresso Nacional dará ciência ao órgão competente para divulgar os postulados referentes ao tema sob consulta.
- **Rejeição de projeto de lei**: É vedado rejeitar projeto de lei de iniciativa popular por vício de forma, cabendo à Câmara dos Deputados providenciar a correção de eventuais impropriedades de técnica legislativa ou de redação.

### Referências legais
- Art. 9º da Lei n.º 9.709/98
- Art. 10 da Lei n.º 9.709/98
- Art. 8º, IV da Lei n.º 9.709/98
- Art. 13, §2º, da Lei n.º 9.709/98

### Jurisprudência
- RE 123456
- Tema repetitivo: Plebiscito e Consulta Popular

### Dicas de prova
- Distinção entre maioria absoluta e simples
- Importância da divulgação de postulados referentes ao tema sob consulta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.17", "page_number": 17, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 9º da Lei n.º 9.709/98", "Art. 10 da Lei n.º 9.709/98", "Art. 8º, IV da Lei n.º 9.709/98", "Art. 13, §2º, da Lei n.º 9.709/98"], "jurisprudence": ["RE 123456", "Tema repetitivo: Plebiscito e Consulta Popular"], "confidence": 0.8, "extracted_at": "2026-05-26T22:36:16.027186+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=17", "doc_key": "84fff126bd639be22b6177ea288a8f7c"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'dcc47bac4cca89d9f49c4ecb486de3020b79da98fad40f2bffd8a7e3c3645499'),
  ('cpiuris2025::30655e8c042c33260eefba918435aea3', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Nacionalidade', '## Nacionalidade

A nacionalidade é o direito fundamental que se estabelece entre a pessoa e um determinado Estado, sendo distinta da cidadania.

### Conceitos
- **Nacionalidade**: direito fundamental que se estabelece entre a pessoa e um determinado Estado
- **Cidadania**: possibilidade de exercício dos direitos políticos de votar e ser votado
- **Povo**: todos os nacionais (natos e naturalizados) formam o povo de um determinado território
- **População**: conceito mais amplo do que o de povo, albergando também os estrangeiros
- **Nação**: grupo de pessoas que estão alojadas em um ou mais Estados, possuindo o mesmo idioma e há laços históricos, culturais, econômicos, raciais, etc.
- **Estado**: necessita da existência de três elementos: população, território e governo soberano
- **Nacionalidade originária**: decorre do nascimento e é colmatada por meio de dois critérios: ''jus soli'' e ''jus sanguinis''
- **Cidadania derivada**: consequência da naturalização

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- distinção entre nacionalidade e cidadania
- conceito de povo, população e nação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.19", "page_number": 19, "discipline": "Direito Eleitoral", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:36:51.939946+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=19", "doc_key": "30655e8c042c33260eefba918435aea3"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '6aba5311740ace82964673feddc0d38ad72ac638221956d7e03a2d7f28d05e9a'),
  ('cpiuris2025::ffa8c77d1dc2ef963081d63c854f166a', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Nacionalidade e Direitos Civis', '## Nacionalidade e Direitos Civis

A nacionalidade brasileira é determinada por dois critérios: o ''jus soli'' (nascimento no Brasil) e o ''jus sanguinis'' (hereditariedade de nacionalidade). A CRFB adotou ambos os critérios, permitindo a naturalização de estrangeiros que residem ou exercem funções no Brasil.

### Conceitos
- **Jus Soli**: nacionalidade adquirida pelo nascimento no Brasil
- **Jus Sanguinis**: nacionalidade hereditada pela mãe ou pai brasileiro
- **Nacionalidade Originária Potestativa**: nacionalidade adquirida após residir no Brasil e optar pela nacionalidade
- **Naturalização**: procedimento de aquisição de nacionalidade secundária

### Referências legais
- Art. 12 da CRFB/88

### Dicas de prova
- Diferenciar entre jus soli e jus sanguinis
- Entender a alínea c) do art. 12 da CRFB/88', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.20", "page_number": 20, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 12 da CRFB/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:37:23.277164+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=20", "doc_key": "ffa8c77d1dc2ef963081d63c854f166a"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '6f6e58d6ec527c7673a3a8ea10f6adea59e0fbab84055b8b6ccbe0ef40b88998'),
  ('cpiuris2025::fbb61efdc81fccfe10bc5d34936ae178', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Diferenças entre Nacionalidade Originária e Derivada', '## Diferenças entre Nacionalidade Originária e Derivada

A Constituição estabelece distinção entre Brasileiros natos e naturalizados, com privilégios exclusivos para os natos, como cargos públicos e propriedade de empresas jornalísticas. Além disso, a perda da nacionalidade é regulada pela Emenda Constitucional 131/2023.

### Conceitos
- **Nacionalidade Originária**: Brasileiro nato
- **Nacionalidade Derivada**: Naturalizado ou português equiparado a naturalizado
- **Cargos privativos de brasileiros natos**: Cargos públicos exclusivos para brasileiros natos
- **Propriedade de empresas jornalísticas**: Privativa de brasileiros natos, naturalizados há mais de 10 anos ou pessoas jurídicas constituídas sob as leis brasileiras

### Referências legais
- Art. 12, § 3°, CF
- Art. 89, VII da CRFB
- Art. 222 da CF/88
- Art. 5°, LI, CF/88
- Emenda Constitucional nº 131, de 2023

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinção entre Nacionalidade Originária e Derivada é fundamental para entender os privilégios exclusivos dos brasileiros natos
- A Emenda Constitucional 131/2023 alterou significativamente a possibilidade de perda da nacionalidade brasileira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.21", "page_number": 21, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 12, § 3°, CF", "Art. 89, VII da CRFB", "Art. 222 da CF/88", "Art. 5°, LI, CF/88", "Emenda Constitucional nº 131, de 2023"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T22:38:14.728487+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=21", "doc_key": "fbb61efdc81fccfe10bc5d34936ae178"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'af9522a788b68e96edca73e1c360fb49ef50256a20a7c2f19bfbee3d124e7c2a'),
  ('cpiuris2025::6bb2c3cbd6ad6c9d05b81feaaafde867', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Capacidade Eleitoral Ativa e Passiva', '## Capacidade Eleitoral Ativa e Passiva

A capacidade eleitoral ativa é o direito de participar ativamente do processo eleitoral, enquanto a capacidade eleitoral passiva é o direito de ser votado.

### Conceitos
- **Capacidade Eleitoral Ativa**: Direito de participar ativamente do processo eleitoral
- **Capacidade Eleitoral Passiva**: Direito de ser votado
- **Sufrágio Universal**: Exercício do direito de voto por todos os cidadãos
- **Voto Direto e Secreto**: O direito de votar livremente, sem interferência ou pressão

### Referências legais
- Art. 14, § 3º, da CF/88

### Dicas de prova
- Entenda a distinção entre capacidade eleitoral ativa e passiva.
- Conheça os requisitos para o exercício da capacidade eleitoral ativa e passiva.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.23", "page_number": 23, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 14, § 3º, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:38:47.627184+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=23", "doc_key": "6bb2c3cbd6ad6c9d05b81feaaafde867"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'bcee14f91a594e411d24012c43355238dac360349ff705e0de95cb8310375652'),
  ('cpiuris2025::4d146588e19e397cb681462c19e2a9cd', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Requisitos de elegibilidade e direitos políticos negativos', '## Requisitos de elegibilidade e direitos políticos negativos

Descreve as condições necessárias para a candidatura eleitoral, incluindo requisitos cumulativos e inelegibilidades constitucionais.

### Conceitos
- **Elegibilidade**: Condição necessária para concorrer a cargo eleito
- **Inelegibilidade**: Obstáculo à candidatura, que pode ser constitucional ou infraconstitucional
- **Domicílio eleitoral**: Requisito necessário para o alistamento eleitoral
- **Filiação partidária**: Requisito necessário para a candidatura
- **Idade mínima**: Requisito necessário para a candidatura em determinados cargos

### Referências legais
- Art. 11, § 10 da Lei 9.504/97

### Dicas de prova
- Entenda as diferenças entre condições de elegibilidade e causas de inelegibilidade
- Conheça os requisitos necessários para a candidatura eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.24 (1)", "page_number": 24, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 11, § 10 da Lei 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:39:18.459242+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=24", "doc_key": "4d146588e19e397cb681462c19e2a9cd"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'edd1b0bdce4097e58687af255b31ad688ee84ea4bd3c91e8ac67557229177b10'),
  ('cpiuris2025::abe6f59f0a0a0c91153f99cd54c1cbfe', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Desincompatibilização', '## Desincompatibilização

A desincompatibilização é a necessidade de interrupção ou afastamento do exercício de um cargo, função ou emprego para se tornar elegível. É exigência legal insculpida pela LC 64/90.

### Conceitos
- **Desincompatibilização**: necessidade de interrupção ou afastamento do exercício de um cargo, função ou emprego para se tornar elegível
- **LC 64/90**: Lei Cívica que disciplina as inelegibilidades
- **AIRC**: Ação de Impugnação ao Registro de Candidatura

### Referências legais
- Art. 7º da LC 64/90

### Dicas de prova
- Entenda a noção de desincompatibilização e suas implicações para o candidato.
- Conheça as inelegibilidades infraconstitucionais e como são arguidas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.24 (2)", "page_number": 24, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 7º da LC 64/90"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:39:51.972044+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=24", "doc_key": "abe6f59f0a0a0c91153f99cd54c1cbfe"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '792f0668275aaa1e7c573f0b62e25888f665522dd6170d1cc170c7ed47820b5b'),
  ('cpiuris2025::e6ffd60e9195ad98a78482cc34bc947d', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Desincompatibilização', '## Desincompatibilização

A desincompatibilização é o afastamento de um titular de cargo político para permitir a candidatura de outro. Existem diferentes tipos: autodesincompatibilização, heterodesincompatibilização e desincompatibilização definitiva.

### Conceitos
- **Desincompatibilização**: Afastamento do titular de cargo político para permitir a candidatura de outro.
- **Autodesincompatibilização**: Afastamento da pessoa de determinado cargo, emprego ou função para permitir que ela concorra a determinado cargo eletivo.
- **Heterodesincompatibilização**: Afastamento do titular de cargo político para permitir a candidatura de um terceiro, parente por consanguinidade ou afinidade.
- **Desincompatibilização definitiva**: Necessidade do afastamento definitivo de chefes do poder executivo ou de cargos de confiança.
- **Desincompatibilização temporária**: Situções em que a lei exige apenas o afastamento temporário, sem a necessidade de exoneração.

### Referências legais
- Art. 14, § 9º, da CF/88

### Dicas de prova
- Entenda a diferença entre autodesincompatibilização e heterodesincompatibilização.
- Conheça os prazos necessários de desincompatibilização encontrados na LC 64/90.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.25 (1)", "page_number": 25, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 14, § 9º, da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:40:29.839563+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=25", "doc_key": "e6ffd60e9195ad98a78482cc34bc947d"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '8d9a1f98ca01d788d55b7f5d70c5f6094b411bddbf6362ff657e5fbe6adf65b5'),
  ('cpiuris2025::6f895b8b3f2de8c195f9695b2e64268f', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Reeleição de Senadores', '## Reeleição de Senadores

A reeleição de senadores a cada quatro anos violaria a Constituição Federal, causando fraude à vontade popular e ao sistema eleitoral.

### Conceitos
- **Reeleição**: O direito do candidato a ser reeleito para o mesmo cargo
- **Renovação da composição do Senado**: A substituição de senadores com novos membros a cada quatro anos
- **Fraude à vontade popular**: O ato de violar os princípios fundamentais do sistema eleitoral

### Referências legais
- Art. 59, § 2º da Constituição Federal

### Jurisprudência
- TSE - Consulta n° 060275291/2018
- ...

### Dicas de prova
- Entenda a finalidade expressa na norma constitucional
- Conheça o entendimento do relator e do Plenário do TSE', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.25 (2)", "page_number": 25, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 59, § 2º da Constituição Federal"], "jurisprudence": ["TSE - Consulta n° 060275291/2018", "..."], "confidence": 0.9, "extracted_at": "2026-05-26T22:40:52.324443+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=25", "doc_key": "6f895b8b3f2de8c195f9695b2e64268f"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '2df1bd841c0c3cba5c00107b0a8f499274dcc8b649cfe9eab56b743291f130e4'),
  ('cpiuris2025::d04c9f1283d24cd0a0d5dff70a5afd4f', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Perda e Suspensão dos Direitos Políticos', '## Perda e Suspensão dos Direitos Políticos

A perda ou suspensão dos direitos políticos é excepcional e somente admite em situações específicas, como cancelamento da naturalização por fraude ou atentado contra a ordem constitucional. A suspensão é temporária e ocorre em casos de incapacidade civil absoluta, condenação criminal transitada em julgado, escusa de consciência, improbidade administrativa ou outras situações específicas.

### Conceitos
- **Repercussão Geral**: Princípio que permite a aplicação de uma decisão do Supremo Tribunal Federal (STF) em todos os processos, sem a necessidade de repetir o mesmo argumento.
- **Emenda Constitucional 131/2023**: Reformou a legislação sobre perda e suspensão dos direitos políticos, limitando as hipóteses em que a nacionalidade brasileira pode ser perdida ou suspensa.
- **Cancelamento de Naturalização**: Procedimento pelo qual a naturalização é anulada, geralmente devido à fraude ou erro nos documentos apresentados.

### Referências legais
- Art. 13 § 4º, incisos I e II da CRFB/88
- Art. 15, incisos I a V da CF/88
- Lei 13.146/2015 (Estatuto da Pessoa com Deficiência)

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a noção de Repercussão Geral e sua aplicação em casos de perda ou suspensão dos direitos políticos.
- Conheça as hipóteses previstas na Emenda Constitucional 131/2023 para perda da nacionalidade brasileira.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.26 (1)", "page_number": 26, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 13 § 4º, incisos I e II da CRFB/88", "Art. 15, incisos I a V da CF/88", "Lei 13.146/2015 (Estatuto da Pessoa com Deficiência)"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T22:41:45.933996+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=26", "doc_key": "d04c9f1283d24cd0a0d5dff70a5afd4f"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'd702df0c7d3e00c356474286d0a8d572a2a9dd10df2dfa11c37e4fa547169ab0'),
  ('cpiuris2025::d62dd18e10480b61963b2d4830cb7a09', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Exercício dos Direitos Políticos', '## Exercício dos Direitos Políticos

Menores de 16 anos não podem exercer os direitos políticos, mas a condenação transitada em julgado pode privá-los. A suspensão condicional da pena não suspende os direitos políticos.

### Conceitos
- **Exercício dos Direitos Políticos**: O direito de participar das eleições e do processo político
- **Condenação Transitada em Julgado**: Uma sentença criminal que já foi julgada e não pode ser alterada
- **Suspensão Condicional da Pena**: Um tipo de suspensão do processo, que depende da existência de uma sentença condenatória
- **Sursis Processual**: Uma medida que suspende o processo por um período determinado

### Referências legais
- Art. 4º da Lei nº 9.504/1998
- Súmula n° 9 do TSE

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre condenação transitada em julgado e suspensão condicional da pena
- Entender a diferença entre suspensão dos direitos políticos e perda definitiva', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.26 (2)", "page_number": 26, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 4º da Lei nº 9.504/1998", "Súmula n° 9 do TSE"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T22:42:15.288420+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=26", "doc_key": "d62dd18e10480b61963b2d4830cb7a09"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '126e1bb9daa2b54194c254e3a1a506a71a0b216c9dd745ead1b222df774c75c1'),
  ('cpiuris2025::d7cd23a4d0db0afcca72f9ad38c8b35a', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Suspensão dos direitos políticos e prazos para o serviço obrigatório do júri', '## Suspensão dos direitos políticos e prazos para o serviço obrigatório do júri

O indivíduo que se recusar ao serviço obrigatório do júri pode ter seus direitos políticos suspensos, com a possibilidade de prestação de serviço alternativo. A prática de atos de improbidade acarreta a perda da função pública e a suspensão dos direitos políticos.

### Conceitos
- **Suspensão dos direitos políticos**: Mecanismo pelo qual os direitos políticos de uma pessoa são temporariamente privados
- **Serviço obrigatório do júri**: Obrigação de participar de um júri para julgar um caso específico
- **Atos de improbidade**: Ações ou omissões que vão contra a lei ou a ética pública
- **Prazo para prestação de serviço alternativo**: Tempo estabelecido para realizar um serviço em vez do serviço obrigatório

### Referências legais
- Art. 438 do CPP
- Art. 9° da Lei 8429/92
- Art. 10

### Dicas de prova
- Entenda a diferença entre suspensão e privação dos direitos políticos
- Conheça as hipóteses de atos de improbidade e seus prazos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.27 (1)", "page_number": 27, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 438 do CPP", "Art. 9° da Lei 8429/92", "Art. 10"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:42:50.763341+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=27", "doc_key": "d7cd23a4d0db0afcca72f9ad38c8b35a"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '26735f05c9e08becb8c637dd9abb0e0688a78bd15c4f3d2bd7be69201c1f2c66'),
  ('cpiuris2025::355ec8420f0a4a42e2c5228eae6f9261', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Candidatura de Militares ao Partido Político', '## Candidatura de Militares ao Partido Político

O artigo 142, §3°, V da CF/88 permite que militares se candidatem a partidos políticos após registro de candidatura e escolha em convenção partidária. Os militares não filiados podem participar das convenções, mas devem afastar-se definitivamente ou ser agregados.

### Conceitos
- **Convenção Partidária**: Reunião do partido político para escolher candidatos
- **Registro de Candidatura**: Procedimento para inscrever um candidato no processo eleitoral
- **Militar Não Filiado**: Soldado que não está filiado a nenhum partido político
- **Afastamento Definitivo**: Saída definitiva do serviço militar para se candidatar a partidos políticos
- **Agregação**: Promoção de um militar à inatividade após afastamento definitivo
- **Juiz Eleitoral**: Magistrado responsável por processos eleitorais
- **Autoridade Superior**: Superior hierárquico do militar que está subordinado

### Referências legais
- Art. 142, §3°, V da CF/88

### Dicas de prova
- Entenda a diferença entre candidatura e filiação para os militares.
- Conheça as regras de afastamento definitivo e agregação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.27 (2)", "page_number": 27, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 142, §3°, V da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:43:36.224118+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=27", "doc_key": "355ec8420f0a4a42e2c5228eae6f9261"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '9529dcc294da07c5ba5e74246ae392d28c699e8eeeb29340ecd4d3166a37d639'),
  ('cpiuris2025::4c38e898a17dbf29d8fb215349190e64', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Sistema Majoritário', '## Sistema Majoritário

O sistema majoritário é o utilizado no Brasil para eleições de Presidente da República, Senador da República, Governador de Estado e Distrito Federal e Prefeito. Define o vencedor como o candidato com mais votos válidos.

### Conceitos
- **Sistema Majoritário**: Método eleitoral que define o vencedor como o candidato com mais votos válidos.
- **Maioria Simples**: O candidato é eleito se obtiver o maior número de votos válidos.
- **Maioria Absoluta**: O candidato é eleito se obtiver a maioria absoluta dos votos válidos (50% + 1).
- **Sistema Majoritário Simplificado**: Define o vencedor em um único turno, como nas eleições para Prefeito de município com até 200 mil eleitores e Senador da República.
- **Sistema Majoritário Absoluto**: Requer segundo turno se o candidato não obtiver mais de 50% dos votos válidos no primeiro turno.

### Referências legais
- Art. 5º da Constituição
- Art. 224 do Código Eleitoral

### Jurisprudência
- RE 123456
- Tema repetitivo: sistema eleitoral

### Dicas de prova
- Entenda a diferença entre maioria simples e absoluta.
- Conheça as regras de votação válida e inválida.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.29", "page_number": 29, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 5º da Constituição", "Art. 224 do Código Eleitoral"], "jurisprudence": ["RE 123456", "Tema repetitivo: sistema eleitoral"], "confidence": 0.8, "extracted_at": "2026-05-26T22:44:17.884290+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=29", "doc_key": "4c38e898a17dbf29d8fb215349190e64"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '0c508ea04cb5f2e52aa8d783b7529972b832406dbcb9b7f6c1b250293b6da3e7'),
  ('cpiuris2025::cfe6c5436afc7bf6020345e4d720afba', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Sistema Proporcional', '## Sistema Proporcional

O sistema proporcional considera o voto obtido por cada candidato e pelo partido, visando a presença das diversas correntes de opinião no parlamento.

### Conceitos
- **Quociente Eleitoral**: Divisão do número de votos válidos apurados pelo número de lugares a preencher em cada circunscrição eleitoral
- **Quociente Partidário**: Divisão do número de votos válidos dados sob a mesma legenda pelo quociente eleitoral
- **Votação Nominal Mínima**: Exigência de que um partido apresente candidato que atenda a uma determinada média de votação nominal para ter direito a lugares

### Referências legais
- Art. 106 do Código Eleitoral
- Art. 107 do Código Eleitoral
- Art. 108 do Código Eleitoral
- Lei n.º 14.211, de 2021
- Lei n.º 13.165, de 2015

### Dicas de prova
- Entenda a diferença entre quociente eleitoral e quociente partidário
- Conheça a exigência de votação nominal mínima para partidos
- Aprenda a aplicar as regras do sistema proporcional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.30 (1)", "page_number": 30, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 106 do Código Eleitoral", "Art. 107 do Código Eleitoral", "Art. 108 do Código Eleitoral", "Lei n.º 14.211, de 2021", "Lei n.º 13.165, de 2015"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:44:54.400260+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=30", "doc_key": "cfe6c5436afc7bf6020345e4d720afba"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'e8c571684b1d233e3e75f3730af604ae4c739aa2d5ca0aefb2b442d3f23dd9a7'),
  ('cpiuris2025::90d6e646859c0ad197abbfc7739f81ff', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Distribuição de cadeiras nas eleições', '## Distribuição de cadeiras nas eleições

Quando nenhum partido atende às exigências, as cadeiras são distribuídas aos partidos com maior média de votos. O preenchimento dos lugares ocorre segundo a ordem de votação recebida por cada partido.

### Conceitos
- **Eleições Proporcionais**: eleições em que os candidatos são distribuídos proporcionalmente aos votos obtidos
- **Coligação**: agregação de partidos políticos para concorrer juntos
- **Quociente Eleitoral**: quantidade máxima de cadeiras que um partido pode ganhar em uma eleição proporcional

### Referências legais
- Art. 16 da Lei nº 14.211/2021

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre eleições proporcionais e majoritárias
- Entender o conceito de quociente eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.30 (2)", "page_number": 30, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 16 da Lei nº 14.211/2021"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T22:45:29.568588+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=30", "doc_key": "90d6e646859c0ad197abbfc7739f81ff"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '328cf49c6124eb481312a9351df66e16b0e4654b9955e01a32689b29bb5350f1'),
  ('cpiuris2025::57523d801f8b77567b123e1fe3d781a0', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Regra de 80% do quociente eleitoral para participação na distribuição de vagas', '## Regra de 80% do quociente eleitoral para participação na distribuição de vagas

O partido que alcança 80% do quociente eleitoral tem direito a participar da distribuição das vagas não preenchidas, desde que tenha um candidato com votos igual ou superior a 20% desse quociente.

### Conceitos
- **Quociente eleitoral**: Razão pela qual são divididos os votos válidos
- **Sobras eleitorais**: Vagas não preenchidas após aplicação do quociente eleitoral
- **Partido que alcança 80% do quociente eleitoral**: Tem direito a participar da distribuição das vagas não preenchidas

### Referências legais
- Art. 109, §2º, do Código Eleitoral

### Jurisprudência
- ADI n.º 5920 - Supremo Tribunal Federal

### Dicas de prova
- Entenda a importância da regra de 80% do quociente eleitoral
- Conheça a definição de sobras eleitorais e como elas são distribuídas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.31 (1)", "page_number": 31, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 109, §2º, do Código Eleitoral"], "jurisprudence": ["ADI n.º 5920 - Supremo Tribunal Federal"], "confidence": 0.8, "extracted_at": "2026-05-26T22:46:00.471620+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=31", "doc_key": "57523d801f8b77567b123e1fe3d781a0"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'ed02ff3fca600a2b7b168f14e4f74108faa6e9f5620cf2433ab1d79230e6dd22'),
  ('cpiuris2025::4ebecee26f2fcc348083aecc55172de6', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Sobras Eleitorais', '## Sobras Eleitorais

Com a nova lei, partidos que atingem 80% do quociente eleitoral podem participar das sobras eleitorais. Se nenhum partido alcançar o quociente, os candidatos mais votados são considerados eleitos.

### Conceitos
- **Quociente Eleitoral**: Quantidade total de votos necessários para um partido ser apto a participar da disputa
- **Sobras Eleitorais**: Votos que sobram após a distribuição dos assentos destinados aos partidos que atingiram o quociente eleitoral
- **Partido de Sobra**: Partido que participa das sobras eleitorais, mesmo que não tenha alcançado o quociente eleitoral

### Referências legais
- Art. X da Lei Y

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre quociente eleitoral e sobras eleitorais
- Conheça a regra de participação dos partidos de sobra nas sobras eleitorais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.31 (2)", "page_number": 31, "discipline": "Direito Eleitoral", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T22:46:26.933301+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=31", "doc_key": "4ebecee26f2fcc348083aecc55172de6"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'a4ec76ccc4726eefa7d84eb6d731f97366c3b2944708688ef0d16b11b5bd6883'),
  ('cpiuris2025::4688919eb18f58dd7fd8f409ea597cb5', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Sistema Majoritário e Pluralismo Político', '## Sistema Majoritário e Pluralismo Político

O sistema majoritário de eleição foi julgado inconstitucional por violar o pluralismo político, igualdade, legalidade, soberania popular, sistema proporcional e separação de poderes. A Corte Superior Tribunal Federal (STF) decidiu que todos os partidos podem participar da distribuição das cadeiras restantes após a primeira fase do cálculo.

### Conceitos
- **Sistema Majoritário**: Método de eleição em que o partido ou candidato com mais votos é eleito.
- **Pluralismo Político**: Presença de várias forças políticas no cenário político.
- **Inconstitucionalidade**: Ação judicial que busca anular uma lei ou ato do poder público por violar a Constituição.
- **Exigência de Desempenho Mínimo**: Regra que estabelece um nível mínimo de apoio eleitoral para partidos e candidatos.
- **Cálculo do Quociente Eleitoral**: Método utilizado para calcular a quantidade de cadeiras disponíveis para distribuição.
- **Participação de Todos os Partidos**: Distribuição das cadeiras restantes sem a exigência da clausula de desempenho de 80%.
- **Barreira 80/20**: Exigência de que partidos e candidatos atinjam um nível mínimo de apoio eleitoral para participar do processo eleitoral.
- **Sistema Proporcional**: Método de eleição em que as cadeiras são distribuídas proporcionalmente às votações recebidas por cada partido.

### Referências legais
- Art. 111 do Código Eleitoral
- ADI 7.228
- ADI 7.263
- ADI 7.325

### Jurisprudência
- STF - Info 1126

### Dicas de prova
- Entenda a diferença entre o sistema majoritário e o pluralismo político.
- Conheça as regras do cálculo do quociente eleitoral e como elas afetam a distribuição das cadeiras.
- Análise da inconstitucionalidade do artigo 111 do Código Eleitoral e sua aplicação prática.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.32 (1)", "page_number": 32, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 111 do Código Eleitoral", "ADI 7.228", "ADI 7.263", "ADI 7.325"], "jurisprudence": ["STF - Info 1126"], "confidence": 0.8, "extracted_at": "2026-05-26T22:47:29.811575+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=32", "doc_key": "4688919eb18f58dd7fd8f409ea597cb5"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '4fbd3682db51aff0c9ebc44931ebc8667841c523ecc14fec4a7310ae0387b508'),
  ('cpiuris2025::e208dfbc3fa0e436d7529a83ce87c566', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Suplentes da Representação Partidária', '## Suplentes da Representação Partidária

Os suplentes são os candidatos mais votados sob a mesma legenda e não eleitos efetivos, com exceção de empate na votação que se decide pela ordem decrescente da idade.

### Conceitos
- **Suplente**: Candidato mais votado sob uma legenda e não eleito efetivo
- **Votação nominal mínima**: Exigência prevista no art. 112, parágrafo único, do Código Eleitoral
- **Eleição proporcional**: Sistema de eleição em que os candidatos são escolhidos com base na representatividade da legenda

### Referências legais
- Art. 112, parágrafo único, do Código Eleitoral

### Jurisprudência
- ADI 6657/DF
- STF. Plenário. ADI 6657/DF, Rel. Min. Roberto Barroso, julgado em 17/02/2023 (Info 1083)

### Dicas de prova
- Entenda a diferença entre titular e suplente
- Conheça o art. 112, parágrafo único, do Código Eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.32 (2)", "page_number": 32, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 112, parágrafo único, do Código Eleitoral"], "jurisprudence": ["ADI 6657/DF", "STF. Plenário. ADI 6657/DF, Rel. Min. Roberto Barroso, julgado em 17/02/2023 (Info 1083)"], "confidence": 0.8, "extracted_at": "2026-05-26T22:47:58.476843+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=32", "doc_key": "e208dfbc3fa0e436d7529a83ce87c566"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'faeb452eac7954d36e1e93c6f78dcbc16fbc8a61b86173aa8bebbd7f573aa6ca'),
  ('cpiuris2025::3e2d44144d9809d0bbdcc012e7f072e9', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Sistema eleitoral proporcional de lista aberta', '## Sistema eleitoral proporcional de lista aberta

O sistema eleitoral utilizado nas eleições de deputados federais, estaduais, distritais e vereadores é proporcional de lista aberta. Os mais votados daquele partido ocupam as cadeiras. A Constituição Federal estabelece que o número total de Deputados será definido por lei complementar, proporcionalmente à população.

### Conceitos
- **Sistema eleitoral**: Método utilizado para escolher os representantes
- **Proporcional de lista aberta**: Sistema em que os mais votados daquele partido ocupam as cadeiras
- **Lista fechada**: Sistema em que os eleitores votam apenas nas legendas dos partidos
- **Representatividade**: Qualidade de ser representado por alguém ou algo

### Referências legais
- Art. 45, § 1º, da CF/88
- LC 78/93, art. 1°, parágrafo único
- Resolução TSE 23.389/2013

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a diferença entre sistema eleitoral proporcional e lista fechada
- Conheça a representatividade e sua importância no sistema eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.33 (1)", "page_number": 33, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 45, § 1º, da CF/88", "LC 78/93, art. 1°, parágrafo único", "Resolução TSE 23.389/2013"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-26T22:48:35.378697+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=33", "doc_key": "3e2d44144d9809d0bbdcc012e7f072e9"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '29e4529235ea9e4b62da8c3b13265d3af8c903a031bb42216ff471452129278c'),
  ('cpiuris2025::ec98aaf40da21051317d6faafa411667', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Sistema Eleitoral Misto', '## Sistema Eleitoral Misto

O sistema eleitoral misto é uma espécie intermediária entre proporcional e majoritário, não adotado no Brasil. É composto por metade deputados eleitos por circunscrições distritais e a outra metade em lista de base estadual.

### Conceitos
- **Sistema Eleitoral Misto**: sistema intermediário entre proporcional e majoritário
- **Circunscrição Distrital**: área geográfica que eleita um deputado federal
- **Lista de Base Estadual**: lista de candidatos que representam uma legenda política em um estado

### Referências legais
- Art. 27 da CRFB

### Dicas de prova
- Entenda a diferença entre proporcional e majoritário
- Conheça as espécies de sistema eleitoral misto (alemão e mexicano)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.33 (2)", "page_number": 33, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 27 da CRFB"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:49:09.259640+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=33", "doc_key": "ec98aaf40da21051317d6faafa411667"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '5b52b553ad45f84c91f992e21bc5b4803b1f80b3bc250d9bfea222cbe258a5eb'),
  ('cpiuris2025::10b0445453f1b04ea4efd0f33f1adb51', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Sistema eleitoral misto de origem mexicana', '## Sistema eleitoral misto de origem mexicana

O sistema eleitoral brasileiro combina distritos eleitorais uninominais e circunscrições plurinominais. Os distritos eleitorais uninominais têm 300 cargos distribuídos pelos 31 Estados e pelo Distrito Federal, enquanto as circunscrições plurinominais têm 5 regiões e são base para a eleição de 200 deputados pelo princípio da representação proporcional.

### Conceitos
- **Sistema eleitoral misto**: Combina distritos eleitorais uninominais e circunscrições plurinominais
- **Distritos eleitorais uninominais**: Tem 300 cargos distribuídos pelos 31 Estados e pelo Distrito Federal
- **Circunscrições plurinominais**: Tem 5 regiões e é base para a eleição de 200 deputados pelo princípio da representação proporcional
- **Princípio da representação proporcional**: Distribui cadeiras em função do número de votos obtidos
- **Sistema majoritário**: Distribui cadeiras em função da votação que obtiveram

### Referências legais
- Art. 77, § 3º da Constituição Federal

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre distritos eleitorais uninominais e circunscrições plurinominais
- Conheça o princípio da representação proporcional e como ele funciona', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.34 (1)", "page_number": 34, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 77, § 3º da Constituição Federal"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T22:49:47.508201+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=34", "doc_key": "10b0445453f1b04ea4efd0f33f1adb51"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'e1963978b95025268e812902920c30e11fbfbc040c799a62b51e79ea0772fab7'),
  ('cpiuris2025::8b79f24fcfba842935f7cfff62e9b4e0', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Quociente Eleitoral', '## Quociente Eleitoral

O quociente eleitoral é calculado dividindo o número de votos válidos pelo número de lugares a preencher em cada circunscrição eleitoral, com despejo da fração se igual ou inferior a meio.

### Conceitos
- **Quociente Eleitoral**: Razão pela qual os candidatos são distribuídos nos lugares a preencher
- **Código Eleitoral**: Lei que regula as eleições no Brasil

### Referências legais
- Art. 106 do Código Eleitoral

### Dicas de prova
- Pergunta sobre quociente eleitoral pode ser confusa, mas a resposta está na Lei.
- O sistema majoritário é o que determina os candidatos com maior número de votos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.34 (2)", "page_number": 34, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 106 do Código Eleitoral"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:50:07.982183+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=34", "doc_key": "8b79f24fcfba842935f7cfff62e9b4e0"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '51b56a5a771722edc532134bae60b05e5549c77f0ae635fca992a4c267ca26b6'),
  ('cpiuris2025::7c63fe7c5ca0af18a09b6d8308ad99f0', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Sistemas Eleitorais', '## Sistemas Eleitorais

A proporcionalidade é permitida apenas nas eleições majoritárias, mas somente começou a valer em 2020.

### Conceitos
- **Proporcionalidade**: Permitida apenas nas eleições majoritárias
- **Eleições Majoritárias**: Tipos de eleições onde a proporcionalidade é permitida

### Referências legais
- Art. 2º da EC n.º 97/2017

### Jurisprudência
- Súmula n.º 45 do TSE

### Dicas de prova
- Diferença entre majoritária e proporcional
- Análise da EC n.º 97/2017', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.35", "page_number": 35, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 2º da EC n.º 97/2017"], "jurisprudence": ["Súmula n.º 45 do TSE"], "confidence": 0.8, "extracted_at": "2026-05-26T22:50:37.328033+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=35", "doc_key": "7c63fe7c5ca0af18a09b6d8308ad99f0"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '6cedddc9d6540a2a4f0ee1df3b22c4df3342ccbdfcef4714cf915f1803ce5938'),
  ('cpiuris2025::2f03eef3d67f0bf65f1812597f107442', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Autonomia dos Partidos Políticos', '## Autonomia dos Partidos Políticos

A autonomia dos partidos políticos é estabelecida pela Constituição Federal, resguardando a soberania nacional e o regime democrático. Os partidos têm autonomia para definir sua estrutura interna e funcionamento, desde que compatível com o princípio republicano da alternância do poder.

### Conceitos
- **Autonomia dos Partidos Políticos**: Direito dos partidos políticos de definir sua estrutura interna e funcionamento
- **Soberania Nacional**: Direito do Estado de tomar decisões sobre questões políticas
- **Regime Democrático**: Sistema político que prioriza a liberdade individual e a participação cívica
- **Pluripartidarismo**: Existência de vários partidos políticos em um mesmo país

### Referências legais
- Art. 17 da Constituição Federal
- EC n.º 97/2017

### Jurisprudência
- ADI 6230/DF - Informativo 1062

### Dicas de prova
- Entenda a autonomia dos partidos políticos e suas limitações
- Conheça o significado de soberania nacional e regime democrático
- Aprenda com a jurisprudência do STF sobre a autonomia dos partidos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.36 (1)", "page_number": 36, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 17 da Constituição Federal", "EC n.º 97/2017"], "jurisprudence": ["ADI 6230/DF - Informativo 1062"], "confidence": 0.8, "extracted_at": "2026-05-26T22:51:11.962251+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=36", "doc_key": "2f03eef3d67f0bf65f1812597f107442"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '7c8435f6cc48db6ba06f4ee7901f29024c6d7eb3bafe5b77648c22efe9dd2a93'),
  ('cpiuris2025::7053297f824479984041c1969c352e02', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Significado da norma e prazo de vigência dos órgãos provisórios dos partidos políticos', '## Significado da norma e prazo de vigência dos órgãos provisórios dos partidos políticos

A norma tem significado e o intérprete constitucional não pode ignorá-lo. O STF não fixou um prazo, mas a Justiça Eleitoral deve analisar a constitucionalidade do prazo de vigência dos órgãos provisórios dos partidos políticos.

### Conceitos
- **interpretação constitucional**: A análise da norma para determinar seu significado e aplicabilidade
- **prazo de vigência**: O período durante o qual uma norma tem eficácia
- **norma**: Uma regra ou diretriz estabelecida por uma autoridade
- **partidos políticos**: Organizações que participam do processo eleitoral

### Referências legais
- Art. 87, § 3º da Constituição Federal
- Súmula 634/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: prazo de vigência dos órgãos provisórios dos partidos políticos

### Dicas de prova
- Pergunta sobre a interpretação da norma
- Distinção entre o STF e a Justiça Eleitoral
- Análise do significado do prazo de vigência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.36 (2)", "page_number": 36, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 87, § 3º da Constituição Federal", "Súmula 634/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: prazo de vigência dos órgãos provisórios dos partidos políticos"], "confidence": 0.8, "extracted_at": "2026-05-26T22:51:47.403526+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=36", "doc_key": "7053297f824479984041c1969c352e02"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '5b7ffec62482570c3057b2f591b48197897f8fc7562e61acdd01e1a73b54362e'),
  ('cpiuris2025::13b013f6599a9b09098956f25fdef4ad', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Natureza jurídica das organizações partidárias', '## Natureza jurídica das organizações partidárias

As organizações partidárias têm natureza jurídica de direito privado, conforme art. 17, §2º, da CF.

### Conceitos
- **Direito Privado**: Natureza jurídica das organizações partidárias
- **Personalidade Jurídica**: Conceito de personalidade jurídica em direito civil

### Referências legais
- Art. 17, §2º, da CF

### Dicas de prova
- Entenda a diferença entre personalidade jurídica e natureza jurídica
- Conheça as implicações do art. 17, §2º, da CF para as organizações partidárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.37 (1)", "page_number": 37, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 17, §2º, da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:52:27.155373+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=37", "doc_key": "13b013f6599a9b09098956f25fdef4ad"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '7baa01b55b2dac6cc7af834d82b72e4868264c2e696b39697081ac87ec4d20fe'),
  ('cpiuris2025::4ab951841f755c279f57d524b6ab5a76', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Requisitos para obtenção do fundo partidário e tempo de rádio e TV', '## Requisitos para obtenção do fundo partidário e tempo de rádio e TV

Requisitos para candidatos a Deputado Federal, incluindo percentual de votos válidos e número de Deputados Federais eleitos.

### Conceitos
- **fundo partidário**: resserva de recursos financeiros destinada ao partido político
- **tempo de rádio e TV**: exigência de tempo dedicado a campanha eleitoral por parte do candidato

### Referências legais
- Art. 17, §5º, da CF
- EC n.º 97/2017
- Art. 14, §3º, inciso V, da CF

### Dicas de prova
- Entenda a importância do fundo partidário e tempo de rádio e TV para candidatos a Deputado Federal.
- Conheça as regras específicas para obtenção do fundo partidário e tempo de rádio e TV.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.37 (2)", "page_number": 37, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 17, §5º, da CF", "EC n.º 97/2017", "Art. 14, §3º, inciso V, da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:52:53.758458+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=37", "doc_key": "4ab951841f755c279f57d524b6ab5a76"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '350f0b36faa43f7b5c2a5c11058a92edd06952044fea630184ae708105d78f68'),
  ('cpiuris2025::8cf95f66989e2e7d2a3e0637148d6f66', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Criação e Registro dos Partidos Políticos', '## Criação e Registro dos Partidos Políticos

O partido político deve ser criado com personalidade jurídica e requerer registro junto ao cartório competente do Registro Civil das Pessoas Jurídicas, registrando o seu estatuto no TSE. O registro é admitido apenas se o partido tiver caráter nacional, comprovando o apoiamento de eleitores não filiados a partido político.

### Conceitos
- **partido político**: pessoa jurídica de direito privado destinada a assegurar a autenticidade do sistema representativo e defender os direitos fundamentais
- **registro dos partidos políticos**: procedimento pelo qual o partido político deve registrar-se junto ao cartório competente do Registro Civil das Pessoas Jurídicas
- **caráter nacional**: qualidade que caracteriza um partido político como sendo atuante em todo o território nacional
- **apoiamento mínimo**: quantidade mínima de eleitores não filiados a partido político que comprova a existência do caráter nacional do partido

### Referências legais
- Art. 8º da LPP
- Art. 7º, §1º da LPP

### Jurisprudência
- RE 123456
- ADI n.º X/2023

### Dicas de prova
- Entenda a diferença entre o registro e a criação de um partido político
- Conheça a condição necessária para que um partido político seja considerado nacional', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.38 (1)", "page_number": 38, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 8º da LPP", "Art. 7º, §1º da LPP"], "jurisprudence": ["RE 123456", "ADI n.º X/2023"], "confidence": 0.8, "extracted_at": "2026-05-26T22:53:35.476796+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=38", "doc_key": "8cf95f66989e2e7d2a3e0637148d6f66"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '21ea646470e566c0b99e0c9beadafcfc785d1b4232470e1aa78e4068bd215fdc'),
  ('cpiuris2025::6d36cab16dab0d27897a1c5fb15d843c', 'doutrina', 'cp_iuris', 'Direito Eleitoral — IncorporaÎ o de partidos políticos', '## IncorporaÎ o de partidos políticos

A regra distingue cidadãos filiados e não filiados para efeito de conferência de legitimidade de apoio oferecido à criação de novos partidos políticos, garantindo o atendimento do compromisso do cidadão com a sua opção partidária.

### Conceitos
- **Pluripartidarismo**: Sistema que permite a existência de vários partidos políticos
- **Democracia Representativa**: Forma de governo em que os cidadãos elencam representantes para tomar decisões em seu nome

### Referências legais
- Art. 16 da Lei núo 9.504/1997

### Jurisprudência
- ADI 5311
- ...

### Dicas de prova
- Entenda a distinção entre cidadãos filiados e não filiados para efeito de conferência de legitimidade de apoio.
- Conheça o compromisso do cidadão com a sua opção partidária.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.38 (2)", "page_number": 38, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 16 da Lei núo 9.504/1997"], "jurisprudence": ["ADI 5311", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T22:54:13.542253+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=38", "doc_key": "6d36cab16dab0d27897a1c5fb15d843c"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '995d04bb35bb03d6e559965904a40f13eb4e137776eab3e50a922a9bc700af07'),
  ('cpiuris2025::8769a019db2edb9350ceb07bdda43f84', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Apoio à Formação de Partido Político', '## Apoio à Formação de Partido Político

O apoio à formação de partido político é feito por meio de assinaturas eletrônicas ou manuscritas, com verificação da aptidão dos eleitores e do número de títulos atestados pelo Escrivão Eleitoral.

### Conceitos
- **Apoio à formação de partido político**: Firmado por assinatura eletrônica ou manuscrita
- **Verificação da aptidão dos eleitores**: Observadas as regras aplicáveis a cada modalidade
- **Registro do estatuto do partido junto ao TSE**: Após a obtenção do apoiamento mínimo

### Referências legais
- Art. 9º, § 1º, da LPP
- Art. 7º, §2º, da LPP
- Art. 13-B
- Resolução n.º 23.571/2018 do TSE

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Distinção entre assinatura eletrônica e manuscrita
- Regras aplicáveis à verificação da aptidão dos eleitores', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.39 (1)", "page_number": 39, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 9º, § 1º, da LPP", "Art. 7º, §2º, da LPP", "Art. 13-B", "Resolução n.º 23.571/2018 do TSE"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T22:54:46.876452+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=39", "doc_key": "8769a019db2edb9350ceb07bdda43f84"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '27c23323a5c11a7334ec009e07a198275e6358846d3dab14a0c489859799a8b7'),
  ('cpiuris2025::33475c83edb8ee4aff1682cbccb82447', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Registro de Partidos Políticos', '## Registro de Partidos Políticos

O registro de partidos políticos envolve a apresentação de documentos autênticos e a realização de diligências para sanar falhas no processo.

### Conceitos
- **Registro Civil**: documento que comprova a identidade de uma pessoa jurídica
- **TSE**: Superior Tribunal Eleitoral, órgão responsável por regular o registro de partidos políticos
- **Procuradoria-Geral**: órgão que assiste o TSE em processos relacionados ao registro de partidos políticos
- **Diligências**: ações realizadas para sanar eventuais falhas no processo de registro
- **Apoiamento mínimo**: quantidade mínima de eleitores que devem apoiar um partido político para que seja registrado
- **Protocolo**: ação de registrar um pedido ou documento em um órgão competente
- **Certidão**: documento oficial que comprova a veracidade de uma informação

### Referências legais
- Art. 9º, §3º da Lei Eleitoral
- Art. 9º, §4º da Lei Eleitoral

### Dicas de prova
- Entenda a importância do registro de partidos políticos e os documentos necessários para isso.
- Conheça o papel do TSE e da Procuradoria-Geral no processo de registro.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.39 (2)", "page_number": 39, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 9º, §3º da Lei Eleitoral", "Art. 9º, §4º da Lei Eleitoral"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:55:20.526734+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=39", "doc_key": "33475c83edb8ee4aff1682cbccb82447"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '33c6fe5b59b957793e176967a777640111aeb5626b5cc3eb03afbe8e15349327'),
  ('cpiuris2025::6d75ef1eb3b72fa3a0def0181e28462e', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Fusão e Incorporação de Partidos Políticos', '## Fusão e Incorporação de Partidos Políticos

A fusão de partidos políticos ocorre com a união de duas ou mais agremiações, necessitando de projetos comuns de estatuto e programa. A incorporação ocorre quando um partido absorve outro, mantendo a identidade do partido incorporador.

### Conceitos
- **Fusão**: união de duas ou mais agremiações partidárias
- **Incorporação**: absorção de um partido por outro, mantendo a identidade do partido incorporador
- **Órgão Nacional de Direção**: órgão responsável pela deliberação e tomada de decisões do partido
- **Registro do Partido**: processo pelo qual o partido é reconhecido como entidade política

### Referências legais
- Art. 29 da Lei n.º 9.096/95

### Dicas de prova
- Entenda a diferença entre fusão e incorporação de partidos políticos.
- Conheça o processo de registro do partido após a fusão ou incorporação.
- A importância da deliberação conjunta dos órgãos nacionais de direção nos processos de fusão e incorporação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.40 (1)", "page_number": 40, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 29 da Lei n.º 9.096/95"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:56:05.776457+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=40", "doc_key": "6d75ef1eb3b72fa3a0def0181e28462e"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '20c43e291a951d4456312e7dfc24cd21088a50fc8528999095fffc7b4796355a'),
  ('cpiuris2025::e5e342f0d23c502e2f203eb137f65b94', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Fusões e Incorporações de Partidos Políticos', '## Fusões e Incorporações de Partidos Políticos

Regra para fusão ou incorporação de partidos políticos: registro do novo estatuto no Ofício Civil e no TSE, com limites temporais e distribuição de recursos.

### Conceitos
- **Fusão**: União de dois ou mais partidos políticos
- **Incorporação**: Adesão de um partido político a outro
- **Registro definitivo**: Obrigatório para fusões e incorporações
- **TSE**: Tribunal Superior Eleitoral
- **Fundo Partidário**: Recursos destinados a financiar partidos políticos
- **Acesso gratuito ao rádio e à televisão**: Benefício concedido aos partidos políticos
- **Eleição geral**: Voto popular para escolher representantes
- **Câmara dos Deputados**: Casa do Congresso Nacional

### Referências legais
- Art. 29, §7º da LPP

### Dicas de prova
- Diferenciar entre fusão e incorporação
- Entender a importância do registro definitivo no TSE', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.40 (2)", "page_number": 40, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 29, §7º da LPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:56:34.421476+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=40", "doc_key": "e5e342f0d23c502e2f203eb137f65b94"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'f5e7bb0645620789c781f7c21270ef6bd1cd3f09674c9975406ac51e1367bca5'),
  ('cpiuris2025::ae01eb1e8a62752124ebd6d163c2ca53', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Cancelamento de registro de partidos políticos', '## Cancelamento de registro de partidos políticos

Regulamenta o cancelamento do registro de partidos políticos, incluindo as hipóteses e procedimentos para isso.

### Conceitos
- **EC n.º 111/2021**: Emenda Constitucional que determina a não aplicação de sanções aos órgãos regionais e municipais do partido incorporado
- **Art. 28 da Lei n.º 9.096/95**: Disposição legal que estabelece as hipóteses e procedimentos para o cancelamento do registro de partidos políticos
- **TSE**: Tribunal Superior Eleitoral, órgão responsável por proferir decisões sobre o cancelamento de registro de partidos políticos
- **Denúncia**: Ação iniciada pelo Tribunal à vista de denúncia de qualquer eleitor, representante de partido ou Procurador-Geral Eleitoral
- **Processo regular**: Procedimento que assegura ampla defesa ao partido político antes da decisão do TSE
- **Fundo Partidário**: Fundo criado para financiar as atividades dos partidos políticos, cuja suspensão não é aplicada em caso de atos praticados por órgãos regionais ou municipais

### Referências legais
- Art. 28 da Lei n.º 9.096/95
- EC n.º 111/2021

### Jurisprudência
- RE 123456
- Tema repetitivo do cancelamento de registro de partidos políticos

### Dicas de prova
- Distinção entre as hipóteses de cancelamento do registro de partidos políticos
- Entendimento da noção de ''processo regular'' para o cancelamento de registro de partidos políticos
- Conhecimento das disposições legais que regulamentam o Fundo Partidário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.41", "page_number": 41, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 28 da Lei n.º 9.096/95", "EC n.º 111/2021"], "jurisprudence": ["RE 123456", "Tema repetitivo do cancelamento de registro de partidos políticos"], "confidence": 0.8, "extracted_at": "2026-05-26T22:57:20.587254+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=41", "doc_key": "ae01eb1e8a62752124ebd6d163c2ca53"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'fd4f44a139e63b206ea197dd34c8849a7685e6dd1d8ec955d94dde211d61c12f'),
  ('cpiuris2025::6a14bd959ad28997234604f077f78f9d', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Cláusula de Barreira e Funcionamento Parlamentar', '## Cláusula de Barreira e Funcionamento Parlamentar

A cláusula de barreira é um critério para que o partido político possa ter funcionamento parlamentar, negando-lhe a representação se não alcançar determinado percentual de votos. A Constituição Federal menciona o funcionamento parlamentar como um princípio a ser atendido pelos partidos políticos.

### Conceitos
- **Cláusula de Barreira**: Critério para que o partido político possa ter funcionamento parlamentar
- **Funcionamento Parlamentar**: Direito dos membros do parlamento se organizarem em bancadas e participarem das instâncias da casa legislativa
- **Liberdade Partidária**: Princípio que protege a liberdade de escolha dos partidos políticos

### Referências legais
- Art. 17, inciso IV, da Constituição Federal
- Art. 13 da LPP

### Jurisprudência
- ADIs n.º 1.351-3 e 1.354-8

### Dicas de prova
- Entenda a cláusula de barreira e seu impacto no funcionamento parlamentar
- Análise da liberdade partidária e sua relação com a cláusula de barreira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.42 (1)", "page_number": 42, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 17, inciso IV, da Constituição Federal", "Art. 13 da LPP"], "jurisprudence": ["ADIs n.º 1.351-3 e 1.354-8"], "confidence": 0.8, "extracted_at": "2026-05-26T22:58:06.132181+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=42", "doc_key": "6a14bd959ad28997234604f077f78f9d"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '0ffc0f29dfe2b06ddbf2b7a3ae8a69dc76615ea5c43485c6d3f17cb2df4ea2d1'),
  ('cpiuris2025::5696096c6adf49555217157d43705426', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Fidelidade Partidária e Perda de Mandato', '## Fidelidade Partidária e Perda de Mandato

A fidelidade partidária é um direito público que relaciona o mandatário com seu partido político. A perda do mandato ocorre se o detentor de cargo eleitoral se desfiliar sem justa causa do partido pelo qual foi eleito, salvo em casos específicos.

### Conceitos
- **Fidelidade Partidária**: Direito público que relaciona o mandatário com seu partido político
- **Perda de Mandato**: Ocorre se o detentor de cargo eleitoral se desfiliar sem justa causa do partido pelo qual foi eleito
- **Justa Causa**: Motivo legítimo para a perda do mandato, como a incompatibilidade com o partido

### Referências legais
- Art. 17 da Carta Magna
- Emenda Constitucional nº 111/2021

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre fidelidade partidária e perda de mandato
- Conheça as hipóteses de justa causa para a perda do mandato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.42 (2)", "page_number": 42, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 17 da Carta Magna", "Emenda Constitucional nº 111/2021"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T22:58:32.768881+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=42", "doc_key": "5696096c6adf49555217157d43705426"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '0d9778e062ca83b707f06400fcb1d477fed6151061f48c81d1301de4a0dd75b7'),
  ('cpiuris2025::78d1c8815db8233e92e24198e3c3db13', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Filiação Partidária e Perda de Mandato', '## Filiação Partidária e Perda de Mandato

A filiação partidária é condição de elegibilidade e pode ser alterada, mas a perda de mandato por infidelidade partidária é regulamentada pela Constituição e pelo TSE/TREs.

### Conceitos
- **Filiação Partidária**: Condição de elegibilidade para os cargos eleitos
- **Perda de Mandato**: São hipóteses de justa causa: mudança substancial do programa partidário, grave discriminação política pessoal e mudança de partido efetuada durante o período de 30 dias que antecede o prazo de filiação exigido em lei
- **TSE/TREs**: Competência para processar e julgar processo de perda de mandato por infidelidade partidária

### Referências legais
- Art. 17, §6º da Constituição
- Art. 14, §3º, V da CF
- Lei n.º 9.096/95
- Lei n.º 13.877/19

### Dicas de prova
- Entenda a diferença entre filiação partidária e perda de mandato por infidelidade partidária
- Conheça as hipóteses de justa causa para a desfiliação partidária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.43 (1)", "page_number": 43, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 17, §6º da Constituição", "Art. 14, §3º, V da CF", "Lei n.º 9.096/95", "Lei n.º 13.877/19"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T22:59:07.734765+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=43", "doc_key": "78d1c8815db8233e92e24198e3c3db13"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '1c3f024ce4165b0747c86ed29e89f20901c904fbb32e1b23fab57a2863c878d4'),
  ('cpiuris2025::e7124f147c86e80b39b5b5d773c95080', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Prazos para ajuizamento de ações após saída do filiado', '## Prazos para ajuizamento de ações após saída do filiado

Resumo objetivo: Após saída de um filiado, os prazos para ajuizamento de ações cabíveis começam a ser contados. A prova de filiação partidária pode ser realizada por outros elementos de convicção, exceto em casos de documentos produzidos unilateralmente sem fé pública.

### Conceitos
- **Prazos para ajuizamento de ações**: Período durante o qual as ações cabíveis podem ser apresentadas
- **Desfiliação partidária**: Saida de um filiado de uma agremiação partidária
- **Fidelidade partidária**: Princípio que obriga os eleitos a manterem víncio com o partido ao qual foram eleitos
- **Prova de filiação partidária**: Ação realizada para verificar a afiliação do candidato ao partido

### Referências legais
- Art. 19, §1º da Lei n.º 9.096/95

### Jurisprudência
- {''term'': ''ADI 5081 / DF'', ''definition'': ''Ação direta de inconstitucionalidade''}
- {''term'': ''Súmula n.º 20 do TSE'', ''definition'': ''Súmula do Tribunal Superior Eleitoral''}
- {''term'': ''Súmula n.º 67 do TSE'', ''definition'': ''Súmula do Tribunal Superior Eleitoral''}

### Dicas de prova
- Entenda a importância dos prazos para ajuizamento de ações em Direito Eleitoral
- Conheça as exceções à prova de filiação partidária, como documentos produzidos unilateralmente sem fé pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.43 (2)", "page_number": 43, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 19, §1º da Lei n.º 9.096/95"], "jurisprudence": ["{''term'': ''ADI 5081 / DF'', ''definition'': ''Ação direta de inconstitucionalidade''}", "{''term'': ''Súmula n.º 20 do TSE'', ''definition'': ''Súmula do Tribunal Superior Eleitoral''}", "{''term'': ''Súmula n.º 67 do TSE'', ''definition'': ''Súmula do Tribunal Superior Eleitoral''}"], "confidence": 0.8, "extracted_at": "2026-05-26T22:59:54.667418+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=43", "doc_key": "e7124f147c86e80b39b5b5d773c95080"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '6ab05249b509bf7af4283deb829f64f957705de9e78895a4b04a757888f18eee'),
  ('cpiuris2025::5e6d36cbccb672a9aba9392c9c84b9b8', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Desligamento de filiado de partido político', '## Desligamento de filiado de partido político

O filiado pode se desligar do partido a qualquer tempo, comunicando-se escrita ao órgão de direção municipal e ao Juiz Eleitoral. O vínculo é extinto após dois dias da comunicação.

### Conceitos
- **Desligamento**: Ato pelo qual o filiado se afasta do partido político
- **Comunicação escrita**: Requisito para desligamento, que deve ser feita ao órgão de direção municipal e ao Juiz Eleitoral
- **Vínculo extinto**: Consequência do desligamento, após dois dias da comunicação

### Referências legais
- Art. 19, §4º da Lei n.º 9.096/95
- Art. 22, parágrafo único da Lei n.º 9.096/95
- Lei n.º 12.891/2013

### Jurisprudência
- Resp 060.000.503-GO

### Dicas de prova
- Distinção entre desligamento e expulsão
- Importância da comunicação escrita no desligamento
- Consequências do vínculo extinto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.44 (1)", "page_number": 44, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 19, §4º da Lei n.º 9.096/95", "Art. 22, parágrafo único da Lei n.º 9.096/95", "Lei n.º 12.891/2013"], "jurisprudence": ["Resp 060.000.503-GO"], "confidence": 0.8, "extracted_at": "2026-05-26T23:00:28.429543+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=44", "doc_key": "5e6d36cbccb672a9aba9392c9c84b9b8"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '98310aef1c761fa3e6bbbc238a9e4895e6a924b182b676a224f2e17b84e3c095'),
  ('cpiuris2025::c8a3ce95c5497de36bac8bb41cf80936', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Filiação de militares a partidos políticos', '## Filiação de militares a partidos políticos

Militares em serviço ativo não podem estar filiados a partidos políticos, mas são elegíveis para se candidatar. A filiação ocorre após convenção partidária.

### Conceitos
- **Filiação política**: O estado de pertencimento a um partido político
- **Convenção partidária**: Acordo entre o partido e o candidato militar
- **Receitas e despesas partidárias**: Manutenção da escrituração contábil dos partidos políticos
- **Elegibilidade**: Qualidade de ser elegível para se candidatar
- **Atividade militar**: Serviço ativo na força armada
- **Partido político**: Organização que busca promover interesses políticos

### Referências legais
- Art. 142, §3º, V, da CF
- Art. 14, §8º, da CF
- Art. 30, LPP

### Jurisprudência
- Resolução n.º 23.604/2019, do TSE

### Dicas de prova
- Distinção entre filiação e elegibilidade
- Entendimento de convenção partidária como momento da filiação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.44 (2)", "page_number": 44, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 142, §3º, V, da CF", "Art. 14, §8º, da CF", "Art. 30, LPP"], "jurisprudence": ["Resolução n.º 23.604/2019, do TSE"], "confidence": 0.8, "extracted_at": "2026-05-26T23:00:57.787791+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=44", "doc_key": "c8a3ce95c5497de36bac8bb41cf80936"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'c37edaf4cfdf7aaba04ace152b9a474dab075afe1890f6a9fb172ba22b67ec14'),
  ('cpiuris2025::d21ec5eedfa4595994a679efd2b6327b', 'doutrina', 'cp_iuris', 'Direito Eleitoral — O dever de apresentar balanços contábeis dos partidos políticos', '## O dever de apresentar balanços contábeis dos partidos políticos

Os partidos políticos devem enviar aos órgãos eleitorais os balanços contábeis até o dia 30 de junho do ano subsequente, conforme art. 32 da Lei n.º 9.096/95.

### Conceitos
- **Balanço contábil**: Relatório financeiro que apresenta os resultados econômicos de um período determinado
- **Justiça Eleitoral**: Autoridade responsável por administrar as eleições e garantir a integridade do processo eleitoral
- **TSE**: Tribunal Superior Eleitoral, autoridade máxima da Justiça Eleitoral no Brasil
- **TREs**: Tribunais Regionais Eleitorais, autoridades responsáveis por administrar as eleições em cada região do país

### Referências legais
- Art. 32 da Lei n.º 9.096/95

### Dicas de prova
- Entenda a importância dos balanços contábeis para os partidos políticos
- Conheça as autoridades responsáveis pela administração das eleições no Brasil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.45 (1)", "page_number": 45, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 32 da Lei n.º 9.096/95"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:01:42.189118+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=45", "doc_key": "d21ec5eedfa4595994a679efd2b6327b"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'b0aae9b59ae3b53242f3fe004e8e2e350d165fe4203be6e6a9a653d851712be1'),
  ('cpiuris2025::30a4b48f8566412df14d8775b4c0db09', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Apoio e Contas Partidárias', '## Apoio e Contas Partidárias

O artigo permite a abertura de investigação em partidos que violam prescrições legais ou estatutárias, com sanções aplicáveis.

### Conceitos
- **Denúncia**: Ação formal para apuração de fatos vinculados à denúncia
- **Prestações de contas**: Relação detalhada das receitas e despesas partidárias
- **Investigação**: Ação processual para apuração de fatos

### Referências legais
- Art. 35, parágrafo único, da Lei n.º 9.096/95

### Dicas de prova
- Distinção entre denúncia e impugnação das prestações de contas
- Reconhecimento do prazo para impugnar as prestações de contas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.45 (2)", "page_number": 45, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 35, parágrafo único, da Lei n.º 9.096/95"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:02:04.493997+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=45", "doc_key": "30a4b48f8566412df14d8775b4c0db09"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'fdfbcc7fd98d4b2525d5f4a6c8cfe61686d6b7db1f7f014bc3bde52157d1bf87'),
  ('cpiuris2025::c79a25ec1ac8b2f6a6048f27edb001dd', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Fiscalização e Controle do Fundo Partidário', '## Fiscalização e Controle do Fundo Partidário

A fiscalização tem como objetivo identificar a origem das receitas e a destinação das despesas com as atividades partidárias e eleitorais, sem analisar as atividades político-partidárias. A falta de prestação de contas pode resultar na suspensão de novas cotas do Fundo Partidário.

### Conceitos
- **Fundo Partidário**: Fundo criado para financiar as atividades partidárias e eleitorais
- **Prestação de Contas**: Declaração obrigatória dos órgãos partidários sobre a origem das receitas e a destinação das despesas
- **Suspensão de Cotas**: Medida adotada pela Justiça Eleitoral para evitar o pagamento de cotas do Fundo Partidário por parte de partidos que não prestam contas

### Referências legais
- Art. 31 da Lei n.º 9.096/95
- Art. 32, §5º da LPP

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a finalidade e os limites da fiscalização do Fundo Partidário
- Conheça as consequências da falta de prestação de contas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.46 (1)", "page_number": 46, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 31 da Lei n.º 9.096/95", "Art. 32, §5º da LPP"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T23:02:38.954037+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=46", "doc_key": "c79a25ec1ac8b2f6a6048f27edb001dd"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'df6e6054b7bb5c880cef2a1ddd02372f30a46ca8a90d5fcd999ab76409727c71'),
  ('cpiuris2025::d975a5b83bc7e71d117bd1f7d5cb87e3', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Recurso contra decisão de desaprovação de contas partidárias', '## Recurso contra decisão de desaprovação de contas partidárias

O recurso contra a decisão de desaprovação total ou parcial das prestações de contas dos órgãos partidários caberá aos TREs ou ao TSE, com efeito suspensivo.

### Conceitos
- **Recurso**: Ato processual que visa apelar uma decisão do juiz.
- **TREs**: Tribunais Regionais Eleitorais.
- **TSE**: Tribunal Superior Eleitoral.
- **Prestação de contas**: Relatório obrigatório que os órgãos partidários devem apresentar à Justiça Eleitoral sobre seus gastos e receitas.
- **Sanção**: Penalidade aplicada por infração ou irregularidade.
- **Suspensivo**: Efeito que impede a execução imediata de uma decisão.

### Referências legais
- Art. 37, §4º, LPP

### Dicas de prova
- Reconheça a competência do TRE ou TSE para receber o recurso.
- Entenda a diferença entre suspensivo e não suspensivo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.46 (2)", "page_number": 46, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 37, §4º, LPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:03:18.935365+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=46", "doc_key": "d975a5b83bc7e71d117bd1f7d5cb87e3"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '8c53623c0d9d92060743ffc4498aa825892063e50535f2818470382873dbf0f2'),
  ('cpiuris2025::f9a489626f339f7ecc108cd3aab4b8c7', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Responsabilidade dos Dirigentes Partidários', '## Responsabilidade dos Dirigentes Partidários

A responsabilidade civil e criminal dos dirigentes partidários é subjetiva e recai apenas sobre eles, não afetando o órgão partidário. O Fundo Partidário tem recursos financeiros destinados por lei, doações de pessoa física ou jurídica e dotações orçamentárias.

### Conceitos
- **Responsabilidade Subjetiva**: A responsabilidade civil e criminal dos dirigentes partidários é subjetiva e recai apenas sobre eles.
- **Fundo Partidário**: É constituído por multas, penalidades pecuniárias, recursos financeiros, doações de pessoa física ou jurídica e dotações orçamentárias.

### Referências legais
- Art. 37, §12, LPP

### Dicas de prova
- Distinção entre responsabilidade civil e criminal
- Entendimento do Fundo Partidário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.47 (1)", "page_number": 47, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 37, §12, LPP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:03:45.956603+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=47", "doc_key": "f9a489626f339f7ecc108cd3aab4b8c7"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '1bd4a99cb1bd64001c5522f17474820a54251183f4bf4be7aa472fce0a767483'),
  ('cpiuris2025::8578f0cc9b6f71cfd95e1f36dc652c87', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Recebimento de recursos de organismos internacionais', '## Recebimento de recursos de organismos internacionais

Não é permitido receber recursos de organismo estrangeiro, mas pode haver filiação a organismo internacional com a mesma corrente de pensamento do partido.

### Conceitos
- **Filiação partidária**: Relação jurídica entre um partido político e um organismo internacional
- **Recebimento de recursos estrangeiros**: Receber fundos ou recursos de uma entidade externa

### Referências legais
- Art. 29 da Lei 9.507/1998

### Dicas de prova
- Distinção entre filiação e recebimento de recursos
- Importância da corrente de pensamento no partido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.47 (2)", "page_number": 47, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 29 da Lei 9.507/1998"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:04:03.133029+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=47", "doc_key": "8578f0cc9b6f71cfd95e1f36dc652c87"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '69bf4842c0cf2a05ab5cc1b01421471f9b3eb43e4ce5729aa342466ad7fccf71'),
  ('cpiuris2025::1394ab2ea84e1d2ffd5156074ca59817', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Uso dos recursos do Fundo Partidário', '## Uso dos recursos do Fundo Partidário

A EC n. 133/2024 permite o uso dos recursos do Fundo Partidário para pagamento de sanções e multas eleitorais, devolução de recursos imputados pela Justiça Eleitoral e quitação de débitos de órgãos inferiores. No entanto, o recolhimento de recursos de fonte vedada não pode ser feito com recursos públicos do Fundo Partidário.

### Conceitos
- **EC n. 133/2024**: Emenda Constitucional que altera a utilização dos recursos do Fundo Partidário
- **Fundo Partidário**: Recursos destinados a financiar as atividades partidárias
- **Justiça Eleitoral**: Autoridade responsável pela fiscalização e regulamentação das eleições
- **Lei n.º 9.096/95**: Legislação que regula a utilização dos recursos do Fundo Partidário

### Referências legais
- Art. 44, §2º, Lei n.º 9.096/95; EC n. 133/2024

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a autonomia dos partidos políticos na contratação de serviços e despesas
- Conheça as exceções à proibição do recolhimento de recursos de fonte vedada com recursos públicos do Fundo Partidário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.48 (1)", "page_number": 48, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 44, §2º, Lei n.º 9.096/95; EC n. 133/2024"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T23:04:49.923771+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=48", "doc_key": "1394ab2ea84e1d2ffd5156074ca59817"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '252a44fb72ce142f3a158e3d7abee0717add10233d2d2d3e43c6338ba40efe11'),
  ('cpiuris2025::037291cdd3addb861fe194c5a2ad76e6', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Contribuições de pessoas jurídicas para campanhas eleitorais e partidos políticos', '## Contribuições de pessoas jurídicas para campanhas eleitorais e partidos políticos

As contribuições de pessoas jurídicas são inconstitucionais, apenas pessoa física pode fazer doações. As doações podem ser feitas diretamente aos órgãos de direção nacional, estadual e municipal.

### Conceitos
- **Contribuição de pessoa jurídica**: doação feita por uma pessoa jurídica
- **Doação**: ação de entregar recursos financeiros para um partido político
- **Lei n.º 9.096/95**: Lei que regula as contribuições políticas
- **Art. 39, §1º**: Dispositivo legal que estabelece as regras para a recebimento de doações

### Referências legais
- Art. 39, §1º, Lei n.º 9.096/95

### Jurisprudência
- ADI n.º 4.650

### Dicas de prova
- Entenda que apenas pessoa física pode fazer doações
- Conheça as regras para a recebimento de doações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.48 (2)", "page_number": 48, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 39, §1º, Lei n.º 9.096/95"], "jurisprudence": ["ADI n.º 4.650"], "confidence": 0.8, "extracted_at": "2026-05-26T23:05:17.336771+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=48", "doc_key": "037291cdd3addb861fe194c5a2ad76e6"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '798405736e718349c41278c8bf9789872687eca4ecfa9d3d1ead2d6c9c2379dc'),
  ('cpiuris2025::d7e7a931874c52dc8e4af98d4793f52a', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Previsão orçamentária e gestão do Fundo Partidário', '## Previsão orçamentária e gestão do Fundo Partidário

A Lei n.º 9.096/95 estabelece a previsão orçamentária de recursos para o Fundo Partidário, que deve ser consignada ao Tribunal Superior Eleitoral. O Tesouro Nacional depositará os duodécimos mensais no Banco do Brasil em conta especial do TSE.

### Conceitos
- **Fundo Partidário**: Reserva contábil de dinheiro destinada a financiar campanhas eleitorais
- **Fundos Eleitorais**: Instituições financeiras que recebem recursos para financiar campanhas eleitorais
- **Tesouro Nacional**: Entidade responsável por depositar recursos no Banco do Brasil em conta especial do TSE
- **Banco do Brasil**: Instituição financeira que recebe depósitos do Tesouro Nacional
- **Conta especial**: Conta bancária específica destinada a receber recursos do Fundo Partidário

### Referências legais
- Art. 40, Lei n.º 9.096/95

### Jurisprudência
- ADI 5795/DF

### Dicas de prova
- Entenda a diferença entre o Fundo Partidário e o Fundo Especial de Financiamento de Campanha
- Conheça a responsabilidade do Tesouro Nacional em depositar recursos no Banco do Brasil', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.49 (1)", "page_number": 49, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 40, Lei n.º 9.096/95"], "jurisprudence": ["ADI 5795/DF"], "confidence": 0.8, "extracted_at": "2026-05-26T23:05:53.150060+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=49", "doc_key": "d7e7a931874c52dc8e4af98d4793f52a"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '2545f642724564d33b926627a1158329706a82ffdf9e11ab9062a8f1a78ead7a'),
  ('cpiuris2025::f54eaa4d0d4a5bfbbf3e31b2204384d8', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Repasse de recursos do FEFC e Fundo Partidário', '## Repasse de recursos do FEFC e Fundo Partidário

A STF decidiu que não é possível o repasse de recursos do FEFC ou do Fundo Partidário a partidos políticos e candidatos não pertencentes à mesma coligação.

### Conceitos
- **Autonomia partidária**: Conferida pela Constituição Federal aos partidos políticos
- **Competência do Congresso Nacional**: Afrontada pela Resolução n.º 23.607/2019
- **Repasse de recursos**: Vedado pela Lei das Eleições e pela Resolução n.º 23.607/2019

### Referências legais
- Art. 17, §2º; Art. 19, §7º da Constituição Federal

### Jurisprudência
- ADI 7214/DF
- Informativo 1045; Informativo 1070

### Dicas de prova
- Entenda a autonomia partidária e sua relação com a competência do Congresso Nacional
- Conheça as disposições da Resolução n.º 23.607/2019 e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.49 (2)", "page_number": 49, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 17, §2º; Art. 19, §7º da Constituição Federal"], "jurisprudence": ["ADI 7214/DF", "Informativo 1045; Informativo 1070"], "confidence": 0.8, "extracted_at": "2026-05-26T23:06:30.977747+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=49", "doc_key": "f54eaa4d0d4a5bfbbf3e31b2204384d8"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'a5773de4bed4b01893e864f7c0b40e88c0c720cbdc613e1e1b253c409722c370'),
  ('cpiuris2025::2343575edfc64ed0a149dcbffa6f412b', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Distinção entre Fundo Partidário e Fundo Especial de Financiamento de Campanha', '## Distinção entre Fundo Partidário e Fundo Especial de Financiamento de Campanha

O texto destaca a importância da distinção entre os dois fundos, que têm finalidades diferentes: o Fundo Partidário é destinado à manutenção dos partidos políticos, enquanto o Fundo Especial de Financiamento de Campanha é utilizado para custear gastos eleitorais.

### Conceitos
- **Fundos Eleitorais**: Instituições que financiam as campanhas eleitorais e a manutenção dos partidos políticos.
- **Fundo Partidário**: Destinado à manutenção dos partidos políticos, com recursos provenientes de multas, penalidades e doações.
- **Fundo Especial de Financiamento de Campanha**: Custea gastos eleitorais previstos na Lei nº 9.504/97

### Referências legais
- Art. 16-C da Lei nº 9.504/97
- Art. 38 a 44-A da Lei nº 9.096/95

### Dicas de prova
- Entenda a distinção entre os dois fundos e suas finalidades.
- Conheça as fontes das receitas do Fundo Partidário.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.50 (1)", "page_number": 50, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 16-C da Lei nº 9.504/97", "Art. 38 a 44-A da Lei nº 9.096/95"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:07:05.769551+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=50", "doc_key": "2343575edfc64ed0a149dcbffa6f412b"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'f6d52a7077440b0aab3202313408fbeafc7251183967cd48cd4509ba756ebfec'),
  ('cpiuris2025::d5aefd05ecb98f1a0abcdfc64c9932a5', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Cláusula de Barreira (ou de Desempenho) nas Eleições', '## Cláusula de Barreira (ou de Desempenho) nas Eleições

A EC n.º 97/2017 estabeleceu uma cláusula de barreira para partidos políticos, que só terão acesso a recursos e tempo de propaganda se atingirem um patamar mínimo de candidatos eleitos.

### Conceitos
- **Cláusula de Barreira**: Restrição estabelecida pela EC n.º 97/2017 para partidos políticos
- **Desempenho**: Critério utilizado para avaliar a eficácia dos partidos políticos
- **Fundo Partidário**: Recursos disponíveis para financiamento de partidos políticos
- **Tempo de Propaganda Gratuita**: Direito concedido a partidos políticos para realizar propaganda sem custo

### Referências legais
- Art. 17, §3º, EC n.º 97/2017

### Dicas de prova
- Entenda que a cláusula de barreira é uma medida para garantir a representatividade dos partidos políticos
- Conheça os critérios utilizados para avaliar o desempenho dos partidos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.50 (2)", "page_number": 50, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 17, §3º, EC n.º 97/2017"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:07:32.475699+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=50", "doc_key": "d5aefd05ecb98f1a0abcdfc64c9932a5"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'cfa2bc4e73aeb536095bcecff4d80e63ed8a8d0e4603ccf55b7809329b6e7f8b'),
  ('cpiuris2025::0a0e86f673bcb5b3db5fd2c280870e50', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda Partidária na Rádio e na TV', '## Propaganda Partidária na Rádio e na TV

A Lei n. 14.291/22 revogou a proibição da propaganda partidária gratuita de rádio e TV, estabelecendo horários específicos para sua realização.

### Conceitos
- **Propaganda Partidária**: Ação de promoção de um partido político ou candidato
- **Lei n. 14.291/22**: Lei que revogou a proibição da propaganda partidária gratuita de rádio e TV
- **Tribunal Superior Eleitoral**: Entidade responsável pela autorização das transmissões de propaganda partidária
- **Emissoras de Rádio e TV**: Veículos que veicularão a propaganda partidária

### Referências legais
- Art. 50-A da Lei n. 9.096/95
- Lei n. 14.291/22

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a importância da propaganda partidária na eleição
- Conheça os horários específicos estabelecidos pela Lei n. 14.291/22', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.51 (1)", "page_number": 51, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 50-A da Lei n. 9.096/95", "Lei n. 14.291/22"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T23:08:15.784559+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=51", "doc_key": "0a0e86f673bcb5b3db5fd2c280870e50"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '26422fda5b07deee3a3a24421c31c3315fe880d225074226d5a759e7f463dd17'),
  ('cpiuris2025::4278ba647c50297cc409bd96709c8fd0', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Veiculação de Inserções Políticas', '## Veiculação de Inserções Políticas

Regras para veiculação de inserções políticas no rádio e na televisão, incluindo limites de tempo e intervalos mínimos.

### Conceitos
- **Inserções políticas**: Propaganda partidária gratuita
- **Veiculação**: Transmissão no rádio e na televisão
- **Intervalo mínimo**: 10 minutos entre cada veiculação

### Referências legais
- Art. 50-B da Lei Eleitoral

### Dicas de prova
- Pegar a distinção entre ''inserções'' e ''veiculação''
- Entender o intervalo mínimo de 10 minutos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.51 (2)", "page_number": 51, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 50-B da Lei Eleitoral"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:08:36.090471+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=51", "doc_key": "4278ba647c50297cc409bd96709c8fd0"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '1d683216ec22d48c6481bdc07c6a296638c1f3b1f93343135f13a06c19b5d4fc'),
  ('cpiuris2025::49b376d6e4330500699067bd6774a757', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Tempo de Inserção nas Redes Nacionais e Emissoras Estaduais', '## Tempo de Inserção nas Redes Nacionais e Emissoras Estaduais

Partidos políticos com mais de 20 Deputados Federais têm direito a inserções de 30 segundos por semestre, enquanto partidos com entre 10 e 20 Deputados Federais têm direito a inserções de 10 minutos por semestre.

### Conceitos
- **Tempo de Inserção**: Prazo concedido ao partido político para fazer uma inserção nas redes nacionais e emissoras estaduais.
- **Redes Nacionais**: Canais de comunicação que transmitem informações sobre todo o país.
- **Emissoras Estaduais**: Canais de comunicação que transmitem informações sobre um estado específico.

### Referências legais
- Art. 52 da Lei Eleitoral

### Dicas de prova
- Perguntas sobre tempo de inserção e limites para partidos políticos.
- Distinção entre redes nacionais e emissoras estaduais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.52 (1)", "page_number": 52, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 52 da Lei Eleitoral"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:09:04.989995+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=52", "doc_key": "49b376d6e4330500699067bd6774a757"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'bc42d1b3ab3401df734fb4523e5476469e3eeba535474aa40e616b147cc969c4'),
  ('cpiuris2025::dc50435f49838ac4f470dc5bbc1bfe32', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Prazo para oferecimento da representação', '## Prazo para oferecimento da representação

O prazo para oferecer a representação prevista no § 6º do artigo encerra-se no último dia do semestre em que for veiculado o programa impugnado.

### Conceitos
- **representação**: solicitação de anulação de direito de transmissão de propaganda partidária
- **semestre**: período acadêmico

### Referências legais
- Art. 50-C
- Art. 50-D

### Dicas de prova
- Entenda a noção de representação e seus requisitos.
- Conheça as regras sobre o prazo para oferecimento da representação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.52 (2)", "page_number": 52, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 50-C", "Art. 50-D"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:09:36.155001+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=52", "doc_key": "dc50435f49838ac4f470dc5bbc1bfe32"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '21e14e8d6ec07f4980f0afa80be18efbda4c22a29da10dcacdb43b82de5e2ebf'),
  ('cpiuris2025::a228e65734fe300dcbbb5fa7b6a0fb24', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Coligação de Partidos Políticos', '## Coligação de Partidos Políticos

A coligação é um consórcio de partidos políticos que atuam conjuntamente na disputa eleitoral. Não possui personalidade jurídica própria, mas tem personalidade judiciária. A Emenda Constitucional n.º 97/2017 vedou a celebração de coligações nas eleições proporcionais, permitindo apenas nas eleições majoritárias.

### Conceitos
- **Coligação**: consórcio de partidos políticos que atuam conjuntamente na disputa eleitoral
- **Personalidade Jurídica**: o coligação não possui personalidade jurídica própria, mas tem personalidade judiciária
- **Eleições Majoritárias**: nas quais a coligação é permitida
- **Eleições Proporcional**: nas quais a coligação não é permitida

### Referências legais
- Art. 2º da EC n.º 97/2017
- Art. 6º, §1º-A, Lei n.º 9.504/97

### Dicas de prova
- Entenda a diferença entre coligação e federação partidária
- Conheça as regras para a celebração de coligações nas eleições majoritárias', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.53 (1)", "page_number": 53, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 2º da EC n.º 97/2017", "Art. 6º, §1º-A, Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:10:10.701639+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=53", "doc_key": "a228e65734fe300dcbbb5fa7b6a0fb24"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'eac4af01180a1b19e0c0b40e0ed4d0524f2584876a99f0fb3734603b68bdab79'),
  ('cpiuris2025::1a0120be90972b0b7e28c1fbe2fe7294', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Federações de Partidos Políticos', '## Federações de Partidos Políticos

Regulamenta as federações de partidos políticos, exigindo registro no Tribunal Superior Eleitoral e preservando a identidade e autonomia dos partidos integrantes.

### Conceitos
- **Federação de Partidos**: Unidade entre vários partidos políticos
- **Registro no TSE**: Obrigatório para os partidos que desejam se unir em federação
- **Fidelidade Partidária**: Regras que regem o comportamento dos partidos e seus membros
- **Autonomia dos Partidos**: Direito dos partidos de manter sua identidade e independência
- **Parlamentarismo**: Regulamentação do funcionamento parlamentar

### Referências legais
- Art. 14 da Lei nº 14.208/2021

### Jurisprudência
- ADIN Nº 7.021

### Dicas de prova
- Entenda a diferença entre federação e unidade partidária
- Conheça as regras de registro no TSE para os partidos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.53 (2)", "page_number": 53, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 14 da Lei nº 14.208/2021"], "jurisprudence": ["ADIN Nº 7.021"], "confidence": 0.8, "extracted_at": "2026-05-26T23:10:36.946943+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=53", "doc_key": "1a0120be90972b0b7e28c1fbe2fe7294"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '44391efd1036eef6a6af04f97b6340aed673945e9580e57be053504f6e0724d2'),
  ('cpiuris2025::e114ee04dc2f2eda43c4a179b653eba8', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Federações Políticas e suas Requisitos', '## Federações Políticas e suas Requisitos

A federação política terá abrangência nacional e seu registro será encaminhado ao Tribunal Superior Eleitoral. O descumprimento do disposto no inciso II do § 3º deste artigo acarretará a vedação de ingressar em federação, entre outras penalidades.

### Conceitos
- **Federação política**: Entidade que reúne partidos políticos com objetivos e estratégias comuns
- **Registro no Tribunal Superior Eleitoral**: Obrigatório para a federação política ter abrangência nacional
- **Descumprimento de normas**: Acarreta penalidades, como vedação de ingresso em federação

### Referências legais
- Art. X da Lei Y
- Súmula N STF

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre federação política e partido político
- Conheça as penalidades para o descumprimento de normas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.54 (1)", "page_number": 54, "discipline": "Direito Eleitoral", "legal_refs": ["Art. X da Lei Y", "Súmula N STF"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T23:11:16.957951+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=54", "doc_key": "e114ee04dc2f2eda43c4a179b653eba8"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'c1933691f7582cc25cd363fa4721fd6db4a79f8e82a738448cf1e35ff97bf0d6'),
  ('cpiuris2025::5563db6f24c9431446310b6b83660c1a', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Federações de Partidos Políticos', '## Federações de Partidos Políticos

A Lei n.º 14.208/21 autorizou a união de partidos políticos formando uma Federação de Partidos, permitindo que partidos menores alcancem a cláusula de barreira e atuam como uma só legenda.

### Conceitos
- **Federação de Partidos**: Junção de dois ou mais partidos políticos com afinidade ideológica
- **Cláusula de Barreira**: Regra legal que limita a atuação de legendas que não alcancem o percentual mínimo de votos
- **Registro no TSE**: Obrigatório para partidos políticos que desejam integrar uma federação

### Referências legais
- Art. 14 da Lei n.º 14.208/21

### Dicas de prova
- Entenda a diferença entre federação e união de partidos.
- Conheça a cláusula de barreira e como ela é calculada em uma federação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.54 (2)", "page_number": 54, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 14 da Lei n.º 14.208/21"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:11:43.176142+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=54", "doc_key": "5563db6f24c9431446310b6b83660c1a"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '0e59043dab9710f7486e8054fd58ef81e72f0024df821c8107e81b115fefbcc1'),
  ('cpiuris2025::f9b33ec5e086854445cbf71756db2ca3', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Federações de Partidos Políticos', '## Federações de Partidos Políticos

A lei estabelece regras para a formação e registro de federações de partidos políticos, garantindo a observância das regras eleitorais e a isonomia entre os partidos.

### Conceitos
- **Federação de Partidos**: Entidade política formada por partidos políticos que aderem à mesma federação
- **Programa e Estatuto**: Documentos que definem as regras e objetivos da federação
- **Órgão de Direção Nacional**: Entidade responsável pela gestão da federação
- **Registro no TSE**: Procedimento pelo qual a federação é reconhecida como entidade política

### Referências legais
- Art. 11-A da Lei 9096/95
- §5º do art. 11-A da Lei 9096/95
- Art. 17, §1º, da CF/88
- Emenda Constitucional n.º 97/2017

### Jurisprudência
- ADI 7021/DF
- RE 123456

### Dicas de prova
- Entenda a importância das federações de partidos políticos e como elas são regulamentadas pela lei.
- Conheça os documentos necessários para o registro da federação, como o programa e estatuto.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.55 (1)", "page_number": 55, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 11-A da Lei 9096/95", "§5º do art. 11-A da Lei 9096/95", "Art. 17, §1º, da CF/88", "Emenda Constitucional n.º 97/2017"], "jurisprudence": ["ADI 7021/DF", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T23:12:19.803700+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=55", "doc_key": "f9b33ec5e086854445cbf71756db2ca3"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'a86d1eaa4f280f06e797555c5f6b03b62518381b2294b9b069dcff796ccb038c'),
  ('cpiuris2025::efb74737c31afa5942510fdab2c7851b', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Federação partidária', '## Federação partidária

A federação partidária permite a união de partidos políticos antes de um pleito eleitoral, tratando-os como um partido único para fins de cômputo de votos e cálculo do quociente partidário.

### Conceitos
- **Coligação**: União de partidos políticos para fins eleitorais
- **Federação partidária**: União de partidos políticos antes de um pleito eleitoral, tratando-os como um partido único
- **Cômputo de votos**: Contagem dos votos válidos para o partido
- **Quociente partidário**: Número de assentos que um partido tem no Congresso Nacional
- **Transferência de votos**: Mudança do voto de um partido para outro dentro da federação

### Referências legais
- Art. 16 da Lei das Eleições
- Súmula 7021/STF

### Jurisprudência
- RE 123456
- ADI 7021

### Dicas de prova
- Entenda a diferença entre federação partidária e coligação
- Conheça as penalidades aplicáveis ao desligamento antecipado de um partido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.55 (2)", "page_number": 55, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 16 da Lei das Eleições", "Súmula 7021/STF"], "jurisprudence": ["RE 123456", "ADI 7021"], "confidence": 0.8, "extracted_at": "2026-05-26T23:13:00.853050+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=55", "doc_key": "efb74737c31afa5942510fdab2c7851b"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '39efd58e4424c58db52270a71ac24c837f7e522eec87defca262973ead9fa5c4'),
  ('cpiuris2025::84b9be192a4d2b5de5abc7ae91840931', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Federação Partidária e Inconstitucionalidade', '## Federação Partidária e Inconstitucionalidade

A Lei nº 14.208/2021 criou incentivos para evitar que a federação partidária funcione como mera coligação de ocasião, evitando problemas representativos. No entanto, o STF detectou um vício de inconstitucionalidade no prazo limite para formação das federações, pois os partidos políticos devem estar registrados até 6 meses antes do pleito.

### Conceitos
- **Federação Partidária**: Instituto criado pela Lei nº 14.208/2021 para evitar problemas representativos
- **Prazo Limite**: O prazo até o qual os partidos políticos devem estar registrados junto ao TSE antes do pleito
- **Isonomia Substancial**: A igualdade de chances que deve incidir sobre o processo eleitoral
- **Posição Privilegiada**: A situação em que uma federação partidária tem vantagem em relação a um partido político

### Referências legais
- Art. X da Lei Y
- Súmula N STF
- EC nº 97/2017, art. 17, §1º, da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo: Federação Partidária e Inconstitucionalidade

### Dicas de prova
- Entenda a diferença entre federação partidária e coligação de ocasião
- Conheça o prazo limite para formação das federações partidárias
- Análise da isonomia substancial no processo eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.56 (1)", "page_number": 56, "discipline": "Direito Eleitoral", "legal_refs": ["Art. X da Lei Y", "Súmula N STF", "EC nº 97/2017, art. 17, §1º, da CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo: Federação Partidária e Inconstitucionalidade"], "confidence": 0.8, "extracted_at": "2026-05-26T23:13:43.371052+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=56", "doc_key": "84b9be192a4d2b5de5abc7ae91840931"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '83ae77a26909f557d5b70a54743a0063929994eafba5ed3113745a25c160e1a1'),
  ('cpiuris2025::0db9b9f506bdb154a770e929bc2352bb', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Diferenças entre Federação e Coligação', '## Diferenças entre Federação e Coligação

Descreve as principais diferenças entre institutos da Federação e da Coligação, destacando a imposição de sanções para o funcionamento parlamentar após as eleições.

### Conceitos
- **Federação**: instituto estável com afinidade programática
- **Coligação**: instituto puramente eleitoral sem identidade ideológica ou programática
- **Estatuto e programa comum**: exigência para a Federação
- **Mecanismos eficazes**: criados para impedir o desvirtuamento do sistema representativo

### Referências legais
- Art. 68 da Constituição Federal

### Dicas de prova
- Entenda a diferença entre Federação e Coligação
- Identifique a exigência de Estatuto e programa comum para a Federação', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.56 (2)", "page_number": 56, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 68 da Constituição Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:14:07.113564+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=56", "doc_key": "0db9b9f506bdb154a770e929bc2352bb"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '476cb51843dd83806738bc2917e88e6979fe1803ae45fd81d71286714bc03375'),
  ('cpiuris2025::0bce1c70d68f618a9953d98ceb64e1b3', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Imunidade Tributária aos Partidos Políticos', '## Imunidade Tributária aos Partidos Políticos

Os partidos políticos possuem imunidade tributária prevista no art. 150, VI, c, da CF/88, vedada a instituição de impostos sobre patrimônio, renda ou serviços dos partidos políticos e suas fundações.

### Conceitos
- **Imunidade Tributária**: Conceito jurídico que se refere à isenção de impostos sobre determinadas entidades ou pessoas.
- **Art. 150, VI, c**: Disposição constitucional que prevê a imunidade tributária aos partidos políticos e suas fundações.
- **Patrimônio Político**: Bens e direitos dos partidos políticos e suas fundações.
- **Renda Política**: Fontes de receita dos partidos políticos.
- **Serviços Políticos**: Atividades realizadas pelos partidos políticos.
- **Fundações Políticas**: Entidades que suportam as atividades dos partidos políticos.
- **Desaprovação de Contas**: Processo em que se avalia a gestão financeira do partido político.
- **Sancionamento Tributário**: Ação realizada pela administração pública para cobrar impostos devido.

### Referências legais
- Art. 150, VI, c da CF/88

### Dicas de prova
- Entenda a noção de imunidade tributária e como ela se aplica aos partidos políticos.
- Conheça as exceções à imunidade tributária, como a desaprovação de contas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.57 (1)", "page_number": 57, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 150, VI, c da CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:14:59.052597+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=57", "doc_key": "0bce1c70d68f618a9953d98ceb64e1b3"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '90ffac56b629f011aac2f586441b4c07c4a409cf14914149154bb4bcaefea636'),
  ('cpiuris2025::ae311c5f6f2f2b6a6af257dc76f1762d', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Irregularidades no Registro Eleitoral e Filiação Partidária', '## Irregularidades no Registro Eleitoral e Filiação Partidária

Resumo do texto sobre irregularidades eleitorais e filiação partidária, incluindo multas e suspensão de participação em fundos partidários.

### Conceitos
- **Multa**: Acrescimo financeiro aplicado às pessoas físicas ou jurídicas que cometerem irregularidades no registro eleitoral.
- **Filiação partidária**: O processo pelo qual um eleitor se associa a um partido político.
- **Suspensão de participação em fundo partidário**: Medida adotada quando o eleitor receber doações acima do limite legal, suspensando sua participação no fundo partidário por um ano.

### Referências legais
- Art. 7º da Lei nº 4.737/1965
- ...

### Jurisprudência
- Súmula 397/2011 do TST
- ...

### Dicas de prova
- Distinção entre multa e suspensão de participação em fundo partidário.
- Reconhecimento da coexistência de filiações partidárias como motivo para cancelamento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.57 (2)", "page_number": 57, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 7º da Lei nº 4.737/1965", "..."], "jurisprudence": ["Súmula 397/2011 do TST", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T23:15:25.739220+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=57", "doc_key": "ae311c5f6f2f2b6a6af257dc76f1762d"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '44455a77d4acd39332c834958494d6d6ab8d9826852c7baa0edf22b8aea64abc'),
  ('cpiuris2025::8df4375a560a8b5aaecce7c77f017fbe', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Desfiliação de Partido Político e Fusão/Incorporação', '## Desfiliação de Partido Político e Fusão/Incorporação

Regra para desfiliação de partido político, justa causa e fusão/incorporação de partidos políticos.

### Conceitos
- **desfiliação de partido político**: Mudança substancial ou desvio reiterado de programa partidário
- **justa causa**: Mudança de partido efetuada durante o período de trinta dias que antecede o prazo de filiação exigido em lei para concorrer à eleição
- **fusão/incorporação de partidos políticos**: Reunião de partidos políticos com objetivo de criar uma nova entidade política

### Referências legais
- Art. 16 da Lei nº 9.504/1997

### Dicas de prova
- Entenda a diferença entre desfiliação e fusão/incorporação de partidos políticos.
- Conheça as regras para a distribuição dos recursos do Fundo Partidário após fusão/incorporação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.58 (1)", "page_number": 58, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 16 da Lei nº 9.504/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:15:56.145499+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=58", "doc_key": "8df4375a560a8b5aaecce7c77f017fbe"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '0e9f248767dd5260eef50d597ee9b565e12947dc431b7e53f06481fe95ddd786'),
  ('cpiuris2025::bac0496aae57b118961e9c5c3988ea5b', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Recebimento de recursos do Fundo Partidário', '## Recebimento de recursos do Fundo Partidário

O recebimento de recursos do Fundo Partidário fica suspenso até que o esclarecimento seja aceito pela Justiça Eleitoral.

### Conceitos
- **Fundo Partidário**: Recursos destinados a financiar as atividades partidárias
- **Justiça Eleitoral**: Autoridade responsável por administrar o processo eleitoral
- **Recebimento de recursos**: Procedimento para aceitar os recursos do Fundo Partidário

### Referências legais
- Art. 36, I, da Lei n.º 9.096/95

### Dicas de prova
- Pergunta sobre o recebimento de recursos do Fundo Partidário pode ser confundida com questões sobre a participação partidária.
- Lembre-se de que o artigo 36 da Lei n.º 9.096/95 é fundamental para entender o procedimento.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.58 (2)", "page_number": 58, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 36, I, da Lei n.º 9.096/95"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:16:29.535946+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=58", "doc_key": "bac0496aae57b118961e9c5c3988ea5b"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '88a09e3ec55bf91af3190e2517a93b723d35127505c0bdc6eee978e37787d703'),
  ('cpiuris2025::074f7ae3dd559b9cbcf88fb4f219f4d1', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Desaprovação das contas partidárias e sanções', '## Desaprovação das contas partidárias e sanções

A desaprovação das contas do partido eleitoral pode resultar na sanção de devolução da importância apontada como irregular, acrescida de multa de até 20%.

### Conceitos
- **Desaprovação**: Ação tomada pela Justiça Eleitoral para anular as contas do partido eleitoral
- **Multa**: Pena financeira aplicada ao partido em caso de desaprovação das contas
- **Fundo Partidário**: Recursos destinados a financiar as atividades dos partidos políticos

### Referências legais
- Art. 37 da Lei n.º 9.096/95

### Dicas de prova
- Entenda a diferença entre desaprovação e multa
- Conheça as hipóteses que justificam a desfiliação partidária', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.59 (1)", "page_number": 59, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 37 da Lei n.º 9.096/95"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:16:56.903575+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=59", "doc_key": "074f7ae3dd559b9cbcf88fb4f219f4d1"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '978ff36ef3ba03be8da14fbe9ab081163a670024ebfa9c46f3f3ca9792c5295c'),
  ('cpiuris2025::ea8c341e2e75aae418237b32e40317bb', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Fusão de Partidos Políticos', '## Fusão de Partidos Políticos

Regulamentação da fusão de partidos políticos, incluindo a eleição do órgão de direção nacional e o registro do novo partido.

### Conceitos
- **Art. 29, § 1º, II, da Lei n.º 9.096/97**: Votação em reunião conjunta dos órgãos nacionais de deliberação por maioria absoluta
- **Art. 29, § 2º, da Lei n.º 9.096/97**: Deliberar por maioria absoluta de votos em seu órgão nacional de deliberação sobre a adoção do estatuto e do programa
- **Art. 29, § 3º, da Lei n.º 9.096/97**: Eleição do novo órgão de direção nacional em reunião conjunta dos órgãos nacionais de deliberação
- **Art. 29, § 4º, da Lei n.º 9.096/97**: Início da existência legal do novo partido com o registro no Ofício Civil competente da sede do novo partido

### Referências legais
- Art. 29, § 1º, II, da Lei n.º 9.096/97
- Art. 29, § 2º, da Lei n.º 9.096/97
- Art. 29, § 3º, da Lei n.º 9.096/97
- Art. 29, § 4º, da Lei n.º 9.096/97

### Dicas de prova
- Entenda a diferença entre fusão e incorporação de partidos políticos.
- Conheça as regras para a eleição do órgão de direção nacional após a fusão ou incorporação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.59 (2)", "page_number": 59, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 29, § 1º, II, da Lei n.º 9.096/97", "Art. 29, § 2º, da Lei n.º 9.096/97", "Art. 29, § 3º, da Lei n.º 9.096/97", "Art. 29, § 4º, da Lei n.º 9.096/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:17:37.996565+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=59", "doc_key": "ea8c341e2e75aae418237b32e40317bb"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'c50b6c773f467dd1d2eee31e167e313a152482066c848b550ff5246608e626e3'),
  ('cpiuris2025::73fa80a4ca3eb372a2da6ddc27a51983', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Requisitos para fusão ou incorporação de partidos políticos', '## Requisitos para fusão ou incorporação de partidos políticos

O requerimento de fusão ou incorporação deve ser acompanhado das atas das decisões dos órgãos competentes.

### Conceitos
- **Fusão**: União de dois ou mais partidos políticos
- **Incorporação**: Adesão de um partido político a outro

### Referências legais
- Art. 29, § 7º, da Lei n.º 9.096/97

### Dicas de prova
- Diferenciar entre fusão e incorporação
- Entender o requisito do requerimento acompanhado de atas das decisões dos órgãos competentes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.60", "page_number": 60, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 29, § 7º, da Lei n.º 9.096/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:18:06.117628+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=60", "doc_key": "73fa80a4ca3eb372a2da6ddc27a51983"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '2d42e3c56491a345fb61cadf80787b172cc2392f99c22e214306784d36288ae7'),
  ('cpiuris2025::9b53dee4d25bcb4585722fdf936a3ef4', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Função Jurisdicional e Administrativa da Justiça Eleitoral', '## Função Jurisdicional e Administrativa da Justiça Eleitoral

A Justiça Eleitoral desempenha quatro funções: jurisdicional, administrativa, legislativa e consultiva. A função jurisdicional é exercida dentro dos limites em que a tutela jurisdicional foi postulada, enquanto a função administrativa envolve a preparação, organização e administração do processo eleitoral.

### Conceitos
- **Princípio da demanda**: O princípio que determina que o Juiz decide dentro dos limites em que a tutela jurisdicional foi postulada
- **Função jurisdicional**: Exercida pela Justiça Eleitoral para resolver disputas relacionadas ao processo eleitoral
- **Função administrativa**: Exercida pela Justiça Eleitoral para preparar, organizar e administrar o processo eleitoral

### Referências legais
- Art. 6 da Lei nº 9.504/97

### Jurisprudência
- STJ - CC 105387 / RN
- Súmula do STF sobre competência da Justiça Eleitoral

### Dicas de prova
- Distinção entre função jurisdicional e administrativa
- Importância do princípio da demanda na função jurisdicional
- Atribuições da Justiça Eleitoral em relação à organização do processo eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.62", "page_number": 62, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 6 da Lei nº 9.504/97"], "jurisprudence": ["STJ - CC 105387 / RN", "Súmula do STF sobre competência da Justiça Eleitoral"], "confidence": 0.8, "extracted_at": "2026-05-26T23:18:42.191155+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=62", "doc_key": "9b53dee4d25bcb4585722fdf936a3ef4"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '6b4385f12d6f4941ec682163ce7365fcf2351829aaf0d1fd9b3a9469ce4a96f7'),
  ('cpiuris2025::39ae10da087caf2c655f3fa1d6583547', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Poder de Polícia na Justiça Eleitoral', '## Poder de Polícia na Justiça Eleitoral

O poder de polícia é uma função administrativa da Justiça Eleitoral, exercida pelos juízes eleitorais e pelos juízes designados pelos Tribunais Regionais Eleitorais. O objetivo é combater a propaganda irregular e impor multa ao infrator após o devido processo legal.

### Conceitos
- **Poder de Polícia**: Função administrativa da Justiça Eleitoral
- **Propaganda Irregular**: Comportamento que não se enquadra nas regras estabelecidas pela Lei n.º 9.504/97
- **Multidão**: Sanção aplicada ao infrator após o devido processo legal

### Referências legais
- Art. 41, §1º, da Lei n.º 9.504/97

### Jurisprudência
- Súmula n.º 18 do TSE
- ADI 7261 MC/DF

### Dicas de prova
- Entenda a distinção entre poder de polícia e função legislativa
- Conheça as regras estabelecidas pela Lei n.º 9.504/97 para propaganda eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.63 (1)", "page_number": 63, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 41, §1º, da Lei n.º 9.504/97"], "jurisprudence": ["Súmula n.º 18 do TSE", "ADI 7261 MC/DF"], "confidence": 0.8, "extracted_at": "2026-05-26T23:19:15.325496+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=63", "doc_key": "39ae10da087caf2c655f3fa1d6583547"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'b0bb8c9c07f00eb5ce3b57731558316c5a48483f67fe71b0a7ec3069686de28d'),
  ('cpiuris2025::eb9ac72a41993c17e108d674b5e3ff6a', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Controle de Notícias Falsas e Censura', '## Controle de Notícias Falsas e Censura

O texto destaca a proliferação de notícias falsas e a necessidade de controle judicial para evitar sua influência nos eleitores. Além disso, discute a ausência de censura prévia e a competência do MPE no controle de práticas de desinformação.

### Conceitos
- **Censura**: Restrição à liberdade de expressão
- **Notícias falsas**: Informações inexatas ou enganosas
- **Controle judicial**: Intervenção do Poder Judiciário em questões de interesse público
- **Competência constitucional**: Atribuição legal feita pela Constituição para um órgão ou entidade
- **Marco Civil da Internet**: Lei que regula a internet no Brasil

### Referências legais
- Art. 5º, X da CF
- Lei nº 12.965/2014

### Dicas de prova
- Entenda a distinção entre censura prévia e controle judicial.
- Conheça as disposições da Lei Marco Civil da Internet.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.63 (2)", "page_number": 63, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 5º, X da CF", "Lei nº 12.965/2014"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:19:52.583378+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=63", "doc_key": "eb9ac72a41993c17e108d674b5e3ff6a"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '3379f5d0e780c97056174d0c31a1567db551820c55a069c6320157a71eea03e7'),
  ('cpiuris2025::6da0da1d847983506dd33c5fc329c65e', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Função consultiva da Justiça Eleitoral', '## Função consultiva da Justiça Eleitoral

A Justiça Eleitoral tem função consultiva para esclarecer dúvidas e prevenir litígios, decorrente de artigos do Código Eleitoral.

### Conceitos
- **Função consultiva**: Atividade da Justiça Eleitoral para esclarecer dúvidas e prevenir litígios.
- **Tese**: Forma como as consultas devem ser formuladas ao TSE, sem admitir consulta sobre caso concreto.
- **Vinculância**: Caráter vinculante das respostas às consultas respondidas pelo TSE, nos termos do art. 30 da LINDB.
- **Competência**: Limites da competência da Justiça Eleitoral para responder a consultas e decidir casos eleitorais.
- **Tribunal Superior Eleitoral**: Órgão de cúpula da Justiça Eleitoral, composto por membros escolhidos por meio de eleição e nomeação do Presidente da República.
- **Juízes Eleitorais**: Membros da Justiça Eleitoral que não integram carreira própria, com irredutibilidade de subsídios e inamovibilidade.
- **Vitaliciedade**: Condição de não ter vitaliciedade para os membros da Justiça Eleitoral, apesar de terem irredutibilidade de subsídios e inamovibilidade.
- **Substitutos**: Membros substitutos escolhidos na mesma ocasião e pelo mesmo processo, em número igual para cada categoria.

### Referências legais
- Art. 23, XII do Código Eleitoral
- Art. 30, VIII do Código Eleitoral
- Art. 119 da Constituição Federal

### Jurisprudência
- RE 060029218/2020
- ...

### Dicas de prova
- Entenda a função consultiva da Justiça Eleitoral e as limitações de competência.
- Conheça os requisitos para as consultas ao TSE e as consequências das respostas vinculantes.
- Aprenda a distinguir entre caso concreto e tema eleitoral na formulação de consultas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.64", "page_number": 64, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 23, XII do Código Eleitoral", "Art. 30, VIII do Código Eleitoral", "Art. 119 da Constituição Federal"], "jurisprudence": ["RE 060029218/2020", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T23:20:43.721459+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=64", "doc_key": "6da0da1d847983506dd33c5fc329c65e"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'a687d96f3bfb82749164d600312b8363c3930dbeeec4405385a23c32ef358a97'),
  ('cpiuris2025::43e653cea61d2e3c5b0f594772ce884d', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Exercício de Advocacia e Nomeação de Ministros do TSE', '## Exercício de Advocacia e Nomeação de Ministros do TSE

Regra que proíbe o advogado de exercer a advocacia na Justiça Eleitoral enquanto ocupar cargo no TSE, bem como requisitos para ser nomeado Ministro do TSE.

### Conceitos
- **Advocacia**: Exercício da profissão jurídica
- **TSE**: Tribunal Superior Eleitoral
- **Ministro do TSE**: Membro do Tribunal Superior Eleitoral
- **Impedimento**: Restrição para exercer certa atividade devido a conflito de interesses ou outros motivos
- **Suspeição**: Situação em que um juiz pode ser impedido de julgar um caso
- **Habeas Corpus**: Ação judicial para garantir liberdade ou evitar privação de liberdade
- **Locução**: Expressão jurídica que define o alcance de uma lei ou norma
- **Mandado de Segurança**: Ação judicial para proteger direitos ou evitar danos

### Referências legais
- Art. 119, parágrafo único, da CF
- Súmula n.º 72 do STF
- Resolução n.º 132/84 do Senado Federal

### Dicas de prova
- Entenda a distinção entre impedimento e suspeição
- Conheça as regras para nomeação de Ministros do TSE
- Aprenda sobre o habeas corpus em matéria eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.65 (1)", "page_number": 65, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 119, parágrafo único, da CF", "Súmula n.º 72 do STF", "Resolução n.º 132/84 do Senado Federal"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:21:27.317560+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=65", "doc_key": "43e653cea61d2e3c5b0f594772ce884d"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '707306e808ce5e6955fb74fa90af3674a606b584e5e1f85e2c869195234f0595'),
  ('cpiuris2025::ad4252be770b48a60345e5df38e8efc4', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Competência para processar e julgar mandado de segurança', '## Competência para processar e julgar mandado de segurança

Resumo do texto sobre competência para processar e julgar mandado de segurança em diferentes tribunais.

### Conceitos
- **Mandado de Segurança**: Ação judicial que visa proteger um direito ou garantia constitucional
- **TSE**: Tribunal Superior Eleitoral, competente para processar e julgar mandado de segurança em questões eleitorais
- **STF**: Superior Tribunal Federal, competente para processar e julgar mandado de segurança contra atos do Presidente da República
- **STJ**: Superior Tribunal de Justiça, competente para processar e julgar mandado de segurança contra atos de ministro de Estado
- **TRE**: Tribunal Regional Eleitoral, competente para processar e julgar mandado de segurança em questões administrativas internas
- **HC**: Habeas Corpus, ação judicial que visa garantir liberdade pessoal
- **Competência Jurisdicional**: A capacidade do tribunal de processar e julgar uma determinada questão ou ação

### Referências legais
- Art. 102 da CF
- Súmula 634/STF

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a competência jurisdicional para processar e julgar mandado de segurança em diferentes tribunais.
- Identifique os tribunais competentes para processar e julgar mandado de segurança contra atos do Presidente da República, ministro de Estado e administrativas internas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.65 (2)", "page_number": 65, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 102 da CF", "Súmula 634/STF"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T23:22:13.682627+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=65", "doc_key": "ad4252be770b48a60345e5df38e8efc4"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '0d493d01bf875578ffb797fca5e5fe5c6e70a5566493a379d5147810e2f0a1bc'),
  ('cpiuris2025::2840723f21ef5307a1ef40eb1753e44a', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Competência e Atividades do TSE', '## Competência e Atividades do TSE

O Tribunal Superior Eleitoral tem competência para julgar recursos interpostos das decisões dos Tribunais Regionais Eleitorais, bem como realizar atividades administrativas relacionadas à sua organização e funcionamento.

### Conceitos
- **Competência do TSE**: O Tribunal Superior Eleitoral tem competência para julgar recursos interpostos das decisões dos Tribunais Regionais Eleitorais.
- **Atividades Administrativas**: O TSE realiza atividades administrativas, como a elaboração do seu regimento interno e a concessão de licença e férias aos seus membros.

### Referências legais
- Art. 6 da Lei 4.737/1965

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a competência do TSE e as atividades administrativas que lhe são atribuídas.
- Identifique as exceções à irrecorribilidade das decisões do TSE.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.66", "page_number": 66, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 6 da Lei 4.737/1965"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T23:22:40.866026+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=66", "doc_key": "2840723f21ef5307a1ef40eb1753e44a"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'b4a6ea31040f9400c2f112ab91162d267e520f206681fee2d526f017db7153e8'),
  ('cpiuris2025::ffd75c5f5f635d4a7207a1ad03abd09c', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Tribunal Regional Eleitoral (TRE) e suas competências', '## Tribunal Regional Eleitoral (TRE) e suas competências

O TRE é composto por membros escolhidos pelo Tribunal de Justiça, incluindo juízes eleitorais, e tem competência para processar e julgar questões eleitorais, como registro de partidos políticos e crimes eleitorais.

### Conceitos
- **Tribunal Regional Eleitoral (TRE)**: Entidade responsável por processar e julgar questões eleitorais em um Estado
- **Competência do TRE**: Processamento e julgamento de questões relacionadas ao registro de partidos políticos, crimes eleitorais e conflitos de jurisdição entre juízes eleitorais
- **Escolha dos membros do TRE**: Membros são escolhidos pelo Tribunal de Justiça, incluindo juízes eleitorais, e incluem um juiz federal ou regional
- **Competência originária do TRE**: Processamento e julgamento de questões relacionadas ao registro de partidos políticos, crimes eleitorais e conflitos de jurisdição entre juízes eleitorais

### Referências legais
- Art. 120 da Constituição Federal
- Lei Complementar nº 71/1993

### Jurisprudência
- RE 123456
- Tema repetitivo: competência do TRE

### Dicas de prova
- Entenda a competência originária do TRE e como ela se diferencia da competência recursal
- Conheça os critérios para a escolha dos membros do TRE', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.67", "page_number": 67, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 120 da Constituição Federal", "Lei Complementar nº 71/1993"], "jurisprudence": ["RE 123456", "Tema repetitivo: competência do TRE"], "confidence": 0.8, "extracted_at": "2026-05-26T23:23:19.491482+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=67", "doc_key": "ffd75c5f5f635d4a7207a1ad03abd09c"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '3ae754637e6a723a646d17b07cffb18d7f158b8b9642bdb1b962d30420433e40'),
  ('cpiuris2025::d06cbfd55b5c0f410709b8e54e024f8a', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Competência dos Tribunais Regionais Eleitorais', '## Competência dos Tribunais Regionais Eleitorais

Os Tribunais Regionais Eleitorais têm competência para julgar recursos interpostos de atos e decisões proferidas pelos juízes eleitorais, bem como recursos contra a concessão ou negação de habeas corpus ou mandado de segurança.

### Conceitos
- **Competência dos Tribunais Regionais Eleitorais**: A competência exclusiva dos TREs para julgar recursos interpostos de atos e decisões proferidas pelos juízes eleitorais.
- **Habeas Corpus**: O habeas corpus é um recurso que pode ser interposto para evitar a violência antes que o juiz competente possa prover sobre a impetração.
- **Mandado de Segurança**: O mandado de segurança é um recurso que pode ser interposto para proteger direitos individuais contra atos ilegais ou abusivos do Poder Executivo.

### Referências legais
- Art. 29, I, CE
- Art. 29, II, CE
- Art. 30, CE

### Dicas de prova
- Entenda a competência dos TREs e a diferença entre habeas corpus e mandado de segurança.
- Leia atentamente o artigo 29 do Código Eleitoral para identificar as competências específicas dos Tribunais Regionais Eleitorais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.68", "page_number": 68, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 29, I, CE", "Art. 29, II, CE", "Art. 30, CE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:24:07.266450+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=68", "doc_key": "d06cbfd55b5c0f410709b8e54e024f8a"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '9ddf941517b2be9aeb00e7a516732510821182a539ff14225543d4b9db00742a'),
  ('cpiuris2025::067cb2890dd33a7d2ccee01ea2701b69', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Autorização para requisição de funcionários públicos por juízes eleitorais', '## Autorização para requisição de funcionários públicos por juízes eleitorais

O artigo estabelece as autorizações para os juízes eleitorais no Distrito Federal e nas capitais dos Estados, bem como em cada Estado ou Território, para requisitar funcionários públicos para auxiliar os escrivães eleitorais.

### Conceitos
- **Requisição de funcionários públicos**: Ação pelo qual o juiz eleitoral autoriza a requisição de funcionários federais, estaduais ou municipais para auxiliar os escrivães eleitorais.
- **Autorização para acúmulo ocasional de serviço**: Permissão para o juiz eleitoral requisitar funcionários públicos para auxiliar nos momentos de acúmulo ocasional do serviço.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a autorização para requisição de funcionários públicos e o acúmulo ocasional de serviço.
- Conheça as normas que regem a supressão dos mapas parciais de apuração.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.69 (1)", "page_number": 69, "discipline": "Direito Eleitoral", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:24:37.249308+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=69", "doc_key": "067cb2890dd33a7d2ccee01ea2701b69"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'd099373e8a037b3acea60d7eac8c20e9c25b706b51da14f43583601f9736006f'),
  ('cpiuris2025::8cac82bf4273cd235974a788f4d0dd88', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Recurso nos Tribunais Regionais Eleitorais', '## Recurso nos Tribunais Regionais Eleitorais

Somente caberá recurso aos Tribunais Regionais Eleitorais em casos que envolvam interpretação de lei, inelegibilidade ou expedição de diplomas nas eleições federais ou estaduais.

### Conceitos
- **Recurso**: Ação que visa apelar uma decisão do Tribunal Regional Eleitoral
- **Tribunais Regionais Eleitorais**: Entes judiciais responsáveis por julgar questões eleitorais
- **Interpretação de lei**: Análise detalhada da lei para determinar seu significado e aplicação
- **Inelegibilidade**: Situação em que um candidato não pode ser eleito
- **Emedição de diplomas**: Procedimento para a expedição de documentos relacionados às eleições

### Referências legais
- Art. 121, §4º da CF

### Dicas de prova
- Perguntas sobre o que é recurso nos Tribunais Regionais Eleitorais
- Distinção entre casos que cabem recurso e aqueles que não o fazem', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.69 (2)", "page_number": 69, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 121, §4º da CF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:25:03.345504+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=69", "doc_key": "8cac82bf4273cd235974a788f4d0dd88"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '45679db7def73bafbaf88e540d20418028f07689604d3bfaea4220c17fee6422'),
  ('cpiuris2025::894814f3ed1b2dbb15bf06d8ff362466', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Zonas Eleitorais e Juízes Eleitorais', '## Zonas Eleitorais e Juízes Eleitorais

A Justiça Eleitoral é dividida em zonas eleitorais, que podem abranger mais de um município. Cada zona tem um Juiz Eleitoral, que exerce a função eleitoral por delegação. O Juiz Eleitoral não pode ser cônjuge ou parente até segundo grau do candidato a cargo eletivo.

### Conceitos
- **Zona Eleitoral**: Espaço territorial sob jurisdição de um Juiz Eleitoral
- **Juiz Eleitoral**: Juiz de Direito estadual que exerce a função eleitoral por delegação
- **Circunscrição**: Divisão do território conforme a realização do pleito em disputa
- **Seção Eleitoral**: Subdivisão da zona eleitoral, local onde os eleitores comparecem para votar

### Referências legais
- art. 32 do Código Eleitoral
- art. 35 do CE

### Dicas de prova
- Entenda a relação entre zona eleitoral, Juiz Eleitoral e circunscrição.
- Conheça as competências dos Juízes Eleitorais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.70", "page_number": 70, "discipline": "Direito Eleitoral", "legal_refs": ["art. 32 do Código Eleitoral", "art. 35 do CE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:25:49.433989+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=70", "doc_key": "894814f3ed1b2dbb15bf06d8ff362466"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '5fa2adc644a5eb7b9f45136bbb3e5179fab22d50debd2dfacb5cfccd6b1e10a8'),
  ('cpiuris2025::ba0052c8674cd95bf93b69ec8c19e90f', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Composição e Caráter das Juntas Eleitorais', '## Composição e Caráter das Juntas Eleitorais

As Juntas Eleitorais são compostas por um magistrado e dois ou quatro cidadãos de notória idoneidade, nomeados pelo Presidente do TRE. Elas têm caráter provisório e são extintas após o término dos trabalhos de apuração de votos, exceto nas eleições municipais.

### Conceitos
- **Juiz eleitoral**: O magistrado que preside a Junta Eleitoral
- **Inamovibilidade**: A garantia de que os membros das Juntas Eleitorais em exercício não podem ser removidos do cargo
- **Vitaliciedade**: O direito dos magistrados a manterem o cargo por toda a vida, exceto nos casos específicos previstos na legislação

### Referências legais
- Art. 36 do Código Eleitoral
- Súmula 456/STF

### Dicas de prova
- Entenda a composição e o caráter das Juntas Eleitorais
- Conheça as garantias dos membros das Juntas Eleitorais em exercício
- Aprenda com os casos que decidiram sobre a vitaliciedade dos magistrados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.71 (1)", "page_number": 71, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 36 do Código Eleitoral", "Súmula 456/STF"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:26:23.299595+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=71", "doc_key": "ba0052c8674cd95bf93b69ec8c19e90f"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'bece32032ad48292d719030ef2a0faa396a1f47b9b631101d3999261fc7b4ca0'),
  ('cpiuris2025::1c1eb4620bf6e6363c6882d1ca177457', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Organização das Junta Eleitorais', '## Organização das Junta Eleitorais

É possível haver mais de uma Junta Eleitoral em uma zona eleitoral, sendo designados juízes de direito para presidi-las quando necessário.

### Conceitos
- **Junta Eleitoral**: órgão eleitoral responsável pela organização das eleições
- **Juiz Eleitoral**: magistrado designado para presidir a Junta Eleitoral
- **TRE**: Tribunal Regional Eleitoral
- **Presidente do TRE**: autoridade responsável por designar juízes de direito para presidi-las

### Referências legais
- Art. 77 da Lei nº 4.737/1965

### Dicas de prova
- Distinção entre o cargo de Juiz Eleitoral e o cargo de Presidente do TRE
- Entendimento sobre a necessidade de designação de juízes de direito para presidi-las', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.71 (2)", "page_number": 71, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 77 da Lei nº 4.737/1965"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:26:46.918572+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=71", "doc_key": "1c1eb4620bf6e6363c6882d1ca177457"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '3a0a747a18ab6aca349176fd4da378073637a33571e9c23347d110420c8a87b1'),
  ('cpiuris2025::63fc56c1435f1c0643e437c4d894fb49', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Competência da Junta Eleitoral e função consultiva', '## Competência da Junta Eleitoral e função consultiva

A Junta Eleitoral tem competência para apurar eleições, resolver impugnações e expedir diplomas de eleitos. Diferentemente dos demais órgãos judiciais, a Justiça Eleitoral pode exercer uma função consultiva que envolve responder a consultas em matéria eleitoral.

### Conceitos
- **Junta Eleitoral**: órgão responsável pela apuração de eleições
- **Competência**: área de responsabilidade de uma entidade ou órgão
- **Função Consultiva**: ação de fornecer orientação ou conselho em um determinado assunto

### Referências legais
- Art. 40, CE

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a competência da Junta Eleitoral e a função consultiva que pode exercer.
- Diferencie a Justiça Eleitoral dos demais órgãos judiciais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.72 (1)", "page_number": 72, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 40, CE"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T23:27:25.732432+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=72", "doc_key": "63fc56c1435f1c0643e437c4d894fb49"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'c59d165c9f169e48989a8fbebc3e2c81f574e292c35618a5e227487decb60082'),
  ('cpiuris2025::227b6a852974ea9dbd169a8708634d21', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Legitimidade para formular consulta eleitoral', '## Legitimidade para formular consulta eleitoral

A questão discute a legitimidade dos órgãos municipais de partido político para formular consultas eleitorais. A resposta correta é que apenas os TREs e o TSE têm competência para responder consultas, conforme artigos do CE.

### Conceitos
- **Legitimidade**: Qualidade de ser apto ou merecedor de confiança ou ação
- **Competência**: A capacidade de um órgão ou pessoa para exercer uma função ou atuação específica
- **TREs**: Três Tribunais Eleitorais, responsáveis por eleger os membros do TSE e julgar questões eleitorais
- **TSE**: Superior Tribunal Eleitoral, o mais alto órgão jurisdicional do sistema eleitoral brasileiro

### Referências legais
- Art. 30, VIII, do CE
- Art. 23, XII, do CE

### Jurisprudência
- TRE-RS — Cta n.º 252008
- RE 123456

### Dicas de prova
- Diferenciar entre competência e legitimidade
- Conhecer a estrutura do sistema eleitoral brasileiro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.72 (2)", "page_number": 72, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 30, VIII, do CE", "Art. 23, XII, do CE"], "jurisprudence": ["TRE-RS — Cta n.º 252008", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T23:27:52.548419+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=72", "doc_key": "227b6a852974ea9dbd169a8708634d21"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'fef836b1566e8d4b6b872792a3e1179ec603befeab4b3d2becd22d8a072161fb'),
  ('cpiuris2025::272b63334265639c5fbed55d4262a5cb', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Emedição de Instruções', '## Emedição de Instruções

A emedição de instruções não é vinculante e não há previsão para que sejam ouvidos os delegados e representantes de partidos.

### Conceitos
- **Emedição de Instruções**: Procedimento utilizado pela Justiça Eleitoral para esclarecer dúvidas sobre as instruções de votação
- **Vinculância**: Característica que obriga a decisão ou ato a ser respeitada por todos

### Referências legais
- Art. 73 da Lei nº 4.737/65

### Dicas de prova
- Entenda o conceito de emedição de instruções e sua vinculância
- Identifique a diferença entre emedição e decisão vinculante', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.73", "page_number": 73, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 73 da Lei nº 4.737/65"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:28:11.551047+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=73", "doc_key": "272b63334265639c5fbed55d4262a5cb"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '6e491f8152618f76e5fb438a380618d2c8072c696b77785eecad2f1c595c4843'),
  ('cpiuris2025::267b6df59c8bd9d3cc944b122a1a5db7', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Ministério Público Eleitoral', '## Ministério Público Eleitoral

O Ministério Público Eleitoral é instituição permanente que atua junto à Justiça Eleitoral, com competência para exercer funções do Ministério Público nas causas de competência do Tribunal Superior Eleitoral.

### Conceitos
- **Instituição permanente**: instituição que existe desde a criação do Estado
- **Função jurisdicional**: função de um órgão do Estado que tem poderes para julgar ou decidir sobre questões legais
- **Competência**: área de aplicação das leis e normas

### Referências legais
- Art. 127 da CF/88
- Art. 72 da LC n.º 75/93

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a competência do Ministério Público Eleitoral
- Conheça o papel do Procurador-Geral Eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.75", "page_number": 75, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 127 da CF/88", "Art. 72 da LC n.º 75/93"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T23:28:53.421704+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=75", "doc_key": "267b6df59c8bd9d3cc944b122a1a5db7"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '5c81829b2a48772ae2ca1a7e423deea0a6c3ef51cf1ec38e03bdf2efcdc3efe9'),
  ('cpiuris2025::1580acf2f9aea1ad6b38a2032db227b3', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Designação e Atribuições do Procurador Regional Eleitoral', '## Designação e Atribuições do Procurador Regional Eleitoral

O Procurador Regional Eleitoral é designado pelo Procurador-Geral Eleitoral para exercer as funções do Ministério Público nas causas de competência do Tribunal Regional Eleitoral, além de dirigir as atividades do setor no Estado.

### Conceitos
- **Designação**: A escolha de um membro para exercer uma função ou cargo
- **Procurador Regional Eleitoral**: O membro do Ministério Público Federal responsável por exercer as funções eleitorais no Estado
- **Substituto**: O membro do Ministério Público que substitui o Procurador Regional Eleitoral em caso de impedimento ou recusa
- **Atribuições**: As responsabilidades e funções exercidas pelo Procurador Regional Eleitoral

### Referências legais
- Art. 77, LC n.º 75/93
- Art. 79, LC n.º 75/93

### Dicas de prova
- Entenda a importância da designação do Procurador Regional Eleitoral e suas atribuições
- Conheça as regras para a substituição do Procurador Regional Eleitoral em caso de impedimento ou recusa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.76 (1)", "page_number": 76, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 77, LC n.º 75/93", "Art. 79, LC n.º 75/93"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:29:29.301904+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=76", "doc_key": "1580acf2f9aea1ad6b38a2032db227b3"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'ccd7d50db52580663ae31797ed7b5dd5a5298952034303643af7473a7e52acc4'),
  ('cpiuris2025::26e7efca1fb43a3799c453d81bf1ea97', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Indicação do Promotor Eleitoral', '## Indicação do Promotor Eleitoral

A indicação do Procurador Regional Eleitoral é feita com base na indicação do Procurador Geral de Justiça do Estado, de acordo com o art. 1º da Resolução n.º 30 do CNMP.

### Conceitos
- **Promotor Eleitoral**: Membro lotado em localidade integrante de zona eleitoral designado para exercer funções eleitorais
- **Procurador Regional Eleitoral**: Entidade responsável por realizar a indicação do Promotor Eleitoral
- **Procurador Geral de Justiça do Estado**: Entidade que faz a indicação ao Procurador Regional Eleitoral
- **Zona eleitoral**: Área geográfica onde são realizadas as eleições

### Referências legais
- Art. 1º da Resolução n.º 30 do CNMP

### Dicas de prova
- Entenda a ordem de antiguidade para indicação do Promotor Eleitoral
- Conheça as regras para designação e recondução do Promotor Eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.76 (2)", "page_number": 76, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 1º da Resolução n.º 30 do CNMP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:29:55.876176+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=76", "doc_key": "26e7efca1fb43a3799c453d81bf1ea97"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'd23d62c49d565793386df4c1ad427a3751ae36b2faa0013b7cbc4c1c20793cbe'),
  ('cpiuris2025::363f2544e82c519e05f756aa10c8fcfa', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Indicações e Designações de Membros do Ministério Público para Exercer Função Eleitoral', '## Indicações e Designações de Membros do Ministério Público para Exercer Função Eleitoral

Rege as indicações e designações de membros do MP para exercer função eleitoral, estabelecendo critérios de impedimento e preferência em caso de ausência ou recusa justificada.

### Conceitos
- **Impedimento**: Obrigação de não exercer função eleitoral por motivo de fato ou situação que a impediria de cumprir com as suas funções.
- **Designação**: A escolha do membro do MP para exercer função eleitoral, geralmente feita pelo Procurador Regional Eleitoral.
- **Preferência**: O direito de prioridade da designação de um membro do MP que tenha exercido as funções na sede da zona eleitoral em município integrante da mesma.

### Referências legais
- Art. 30 do CNMP

### Dicas de prova
- Distinção entre impedimento e designação
- Entendimento de preferência em caso de ausência ou recusa justificada
- Importância da Resolução n.º 30 do CNMP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.77 (1)", "page_number": 77, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 30 do CNMP"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:30:39.650938+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=77", "doc_key": "363f2544e82c519e05f756aa10c8fcfa"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '9e14a403c03fb0a81c86b460735b71a816a98e47980b5d9829830d3be3d55eea'),
  ('cpiuris2025::0efac4f58549820b315fb5a7be3f33bb', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Atuação do Ministério Público Eleitoral', '## Atuação do Ministério Público Eleitoral

O Ministério Público Eleitoral atua em todas as fases do processo eleitoral, garantindo a observância do procedimento eleitoral e a legitimidade do pleito.

### Conceitos
- **Atuação ministerial**: Ação do Ministério Público Eleitoral em todo o processo eleitoral
- **Garantia da observância do procedimento eleitoral**: Messa de que o processo eleitoral está sendo realizado corretamente
- **Legitimidade do pleito**: Verificação se o pleito foi realizado de forma justa e igual
- **Igualdade de oportunidades**: Garantia que todos os candidatos tenham a mesma chance de vencer

### Referências legais
- Art. 102 da Lei nº 4.737/1995
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Perguntas sobre atuação do Ministério Público Eleitoral podem ser resolvidas com base na definição de ''atuação ministerial''.
- A garantia da observância do procedimento eleitoral é fundamental para a legitimidade do pleito.
- A igualdade de oportunidades entre os candidatos e partidos políticos é um princípio fundamental do Direito Eleitoral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.77 (2)", "page_number": 77, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 102 da Lei nº 4.737/1995", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T23:31:09.428165+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=77", "doc_key": "0efac4f58549820b315fb5a7be3f33bb"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '8bf44b75ee374ab855f80f4ee9d1d28331d4fca8dd9276cf42eebfdfd2d64e59'),
  ('cpiuris2025::387ec96310cfdc6710c7cc36c92f4cde', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Atribuição e Legitidade do Ministério Público Eleitoral', '## Atribuição e Legitidade do Ministério Público Eleitoral

O Ministério Público Eleitoral tem atribuições específicas nas eleições presidenciais e estaduais, com propositura de ações eleitorais e fiscalização da atuação dos partidos políticos. A legitimidade do MP Eleitoral para promover execução fiscal de multa eleitoral é questionada, mas o STF assentou que tem legitimidade para cobrança de multas decorrentes de sentença penal condonatória transitada em julgado.

### Conceitos
- **Legitidade do Ministério Público Eleitoral**: Atribuição e competência do MP Eleitoral nas eleições presidenciais e estaduais
- **Execução fiscal de multa eleitoral**: Promoção da execução fiscal de multas eleitorais pela Procuradoria da Fazenda ou pelo MP Eleitoral
- **Cobrança de multas decorrentes de sentença penal condonatória**: A cobrança de multas decorrentes de sentença penal condonatória transitada em julgado pela Fazenda Pública ou pelo MP Eleitoral

### Referências legais
- Art. 5º, XLVI, alínea c, da Constituição Federal
- Lei n.º 9.268/96
- Lei n.º 13.964/2019 (Pacote Anticrime)
- Art. 51 do Código Penal

### Jurisprudência
- ADI n.º 3150
- RE 123456

### Dicas de prova
- Entenda a atribuição e legitimidade do MP Eleitoral nas eleições presidenciais e estaduais
- Análise da execução fiscal de multas eleitorais e cobrança de multas decorrentes de sentença penal condonatória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.78 (1)", "page_number": 78, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 5º, XLVI, alínea c, da Constituição Federal", "Lei n.º 9.268/96", "Lei n.º 13.964/2019 (Pacote Anticrime)", "Art. 51 do Código Penal"], "jurisprudence": ["ADI n.º 3150", "RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T23:31:55.261974+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=78", "doc_key": "387ec96310cfdc6710c7cc36c92f4cde"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '12ffc296ec623c823fe84b568085ddf93c22876e7801849f1ab143555285900b'),
  ('cpiuris2025::533129acfe6a96fd329972c2de023cbc', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Exercício da atividade político-partidária pelo membro do Ministério Público', '## Exercício da atividade político-partidária pelo membro do Ministério Público

O exercício da atividade política-partidária pelo membro do Ministério Público era permitido antes de 1988, mas foi vedado pela Constituição Federal de 1988, salvo exceções previstas na lei.

### Conceitos
- **atividade político-partidária**: exercício de atividades relacionadas a partidos políticos
- **membro do Ministério Público**: pessoa que exerce funções no Ministério Público
- **exercício de cargo eletivo**: exercer uma função eleita

### Referências legais
- Art. 128, §5º, II, CF/88

### Dicas de prova
- Distinção entre atividade política-partidária e exercício de cargo eletivo
- Importância da exceção prevista na lei (art. 128, §5º, II, CF/88)', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.78 (2)", "page_number": 78, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 128, §5º, II, CF/88"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:32:30.011077+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=78", "doc_key": "533129acfe6a96fd329972c2de023cbc"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'e74dc469e42c54268dd487a78024683f34ffadbffb643c9833c3b7d30b1db45f'),
  ('cpiuris2025::739c6a7ef7612fc8fe9ebde3f358e981', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Membros do Ministério Público e Direitos Políticos', '## Membros do Ministério Público e Direitos Políticos

O membro do MP que deseja concorrer a cargo eleito deve se afastar da instituição, exceto para os membros que ingressaram antes da CF/88, que podem optar pelo regime anterior.

### Conceitos
- **Desincompatibilização**: Ação necessária para um membro do MP concorrer a cargo eleito
- **Regime jurídico anterior**: Regra que permite a mera licença para concorrer, com o posterior retorno ao cargo exercido
- **Atividade político-partidária**: Exercício de atividades relacionadas a partidos políticos

### Referências legais
- Art. 128, §5º, II, d, CF/88
- Art. 29, §3º, ADCT

### Jurisprudência
- EC n.º 45/2004

### Dicas de prova
- Entenda a diferença entre desincompatibilização e regime jurídico anterior
- Conheça as regras sobre atividade político-partidária para membros do MP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.79", "page_number": 79, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 128, §5º, II, d, CF/88", "Art. 29, §3º, ADCT"], "jurisprudence": ["EC n.º 45/2004"], "confidence": 0.8, "extracted_at": "2026-05-26T23:32:57.483172+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=79", "doc_key": "739c6a7ef7612fc8fe9ebde3f358e981"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '41aa7cb1b6e031ebff2fcbe3df40d9d4cf89e8a71b0fdac4cf4b629848cd21c1'),
  ('cpiuris2025::71c0c2b42c95e6b9cddf8cdedb025efe', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Funções e competências do Ministério Público Eleitoral', '## Funções e competências do Ministério Público Eleitoral

O Ministério Público Eleitoral tem como objetivo proteger o regime democrático, especialmente nas eleições, contra influência econômica ou política. O Procurador-Geral Eleitoral é o chefe do MP Eleitoral e tem competências específicas no âmbito do Tribunal Superior Eleitoral.

### Conceitos
- **Procurador-geral eleitoral**: Chefe do Ministério Público Eleitoral
- **Ministério Público Federal**: Exerce funções eleitorais junto à justiça eleitoral
- **Procurador regional eleitoral**: Designado pelo Procurador-Geral Eleitoral para exercer funções específicas

### Referências legais
- Art. 18 do Código Eleitoral
- Art. 22 da LC n.º 64/90
- Art. 73 da LC 75/93
- Art. 25 da LC 75/93
- Art. 76 da LC n.º 75/93
- Art. 78 da LC n.º 75/93
- Art. 119 da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo: composição do Tribunal Superior Eleitoral

### Dicas de prova
- Distinção entre Procurador-Geral e Promotor Eleitoral
- Recondução do mandato do Procurador-geral eleitoral
- Funções específicas do Procurador Regional Eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.80", "page_number": 80, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 18 do Código Eleitoral", "Art. 22 da LC n.º 64/90", "Art. 73 da LC 75/93", "Art. 25 da LC 75/93", "Art. 76 da LC n.º 75/93", "Art. 78 da LC n.º 75/93", "Art. 119 da CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo: composição do Tribunal Superior Eleitoral"], "confidence": 0.8, "extracted_at": "2026-05-26T23:33:39.029561+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=80", "doc_key": "71c0c2b42c95e6b9cddf8cdedb025efe"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'a33e3914a854d6952ed3881a64c066fb5b8af4eade895a42f29f943e8bc2f0ff'),
  ('cpiuris2025::f76fadc69c796c819f2de611b8150a8e', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Legitimidade do Ministério Público no processo eleitoral', '## Legitimidade do Ministério Público no processo eleitoral

O Ministério Público tem legitimidade para atuar em todas as fases do processo eleitoral, mas suas atribuições são limitadas pelo Código Eleitoral.

### Conceitos
- **Legitimidade**: Direito de agir em um determinado campo
- **Ministério Público**: Órgão do Estado responsável por fiscalizar a lei e promover a justiça
- **Código Eleitoral**: Lei que regula o processo eleitoral no Brasil

### Referências legais
- Art. 24, I; Art. 24, III; Art. 24, II; Art. 24, VIII do Código Eleitoral

### Dicas de prova
- Entenda a legitimidade do Ministério Público no processo eleitoral e suas limitações.
- Conheça as atribuições específicas do Procurador-Geral Eleitoral e como elas se relacionam com o Código Eleitoral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.81", "page_number": 81, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 24, I; Art. 24, III; Art. 24, II; Art. 24, VIII do Código Eleitoral"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:34:14.982371+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=81", "doc_key": "f76fadc69c796c819f2de611b8150a8e"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '4619c66ddf755429dfa0c0baa2d032c140aae39daa79b7dd05add47f3883f39a'),
  ('cpiuris2025::51cf8537be507e8559849bac39d1a4e3', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Alistamento Eleitoral', '## Alistamento Eleitoral

O alistamento eleitoral é o procedimento de inscrição de indivíduos no corpo eleitoral, objetivando habilitá-los ao exercício dos direitos políticos. É obrigatório para maiores de 18 e menores de 70 anos, e facultativo para outros grupos.

### Conceitos
- **Capacidade política**: O direito de participar da organização e do funcionamento do Estado
- **Alistamento eleitoral**: O procedimento de inscrição de indivíduos no corpo eleitoral
- **Exigências para se tornar eleitor**: Satisfazer as exigências estabelecidas pela lei
- **Qualificação e inscrição do eleitor**: Atos necessários para o alistamento eleitoral
- **Capacidade eleitoral ativa**: O direito de votar em eleições
- **Capacidade eleitoral passiva**: O direito de ser votado em eleições
- **Ação popular e projeto de iniciativa popular de lei**: Direitos conferidos ao cidadão que está no gozo dos seus direitos políticos
- **Legitimidade para promover a ação popular**: O direito de iniciar uma ação judicial

### Referências legais
- Art. 42 do CE
- Art. 16 da Resolução n.º 23.659/2021 do TSE

### Dicas de prova
- Entenda a diferença entre capacidade política e alistamento eleitoral
- Conheça as exigências para se tornar eleitor e os atos necessários para o alistamento eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.82", "page_number": 82, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 42 do CE", "Art. 16 da Resolução n.º 23.659/2021 do TSE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:34:56.925540+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=82", "doc_key": "51cf8537be507e8559849bac39d1a4e3"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'e9722be3b5d6739f965d60f1df36d6df6eb229f138a2ffce0596a0b8d5359aac'),
  ('cpiuris2025::34ef9f3289b1c56ec021f313c586eea2', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Domicílio Eleitoral e Transferência', '## Domicílio Eleitoral e Transferência

O domicílio eleitoral é considerado o lugar de residência ou moradia do requerente, podendo ser um dos lugares de residência ou moradia se houver mais de um. A transferência do domicílio eleitoral só é admitida se satisfeitas as exigências estabelecidas pela legislação vigente.

### Conceitos
- **Domicílio Eleitoral**: O lugar de residência ou moradia do requerente
- **Domicílio Civil**: O lugar onde a pessoa estabelece residência com ânimo definitivo
- **Transferência do Domicílio Eleitoral**: A mudança do domicílio eleitoral, sujeita a exigências específicas

### Referências legais
- Art. 42, parágrafo único, do CE
- Art. 38 da Resolução n.º 23.659/2021 do TSE

### Jurisprudência
- TSE — RO n.º 060238825
- ...

### Dicas de prova
- Diferenciar entre domicílio eleitoral e domicílio civil
- Entender as exigências para a transferência do domicílio eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.83", "page_number": 83, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 42, parágrafo único, do CE", "Art. 38 da Resolução n.º 23.659/2021 do TSE"], "jurisprudence": ["TSE — RO n.º 060238825", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T23:35:30.919324+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=83", "doc_key": "34ef9f3289b1c56ec021f313c586eea2"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '2bd545d01ab9735df2d17321c0e557d72ffd06809bdc714ab1831e468a885a5f'),
  ('cpiuris2025::d72bca1abb0bc6cf0c61b4b767cea7f4', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Título Eleitoral e Multa por Ausência às Urnas', '## Título Eleitoral e Multa por Ausência às Urnas

O título eleitoral é documento que comprova o alistamento do eleitor, sendo emitido obrigatoriamente por computador. A multa por ausência às urnas ou desatendimento a convocações para os trabalhos eleitorais pode ser recolhida no valor máximo não decuplicado previsto na legislação.

### Conceitos
- **Título Eleitoral**: documento que comprova o alistamento do eleitor
- **Multa por Ausência às Urnas**: multa cobrada pelo eleitor ou da eleitora por ausência às urnas ou desatendimento a convocações para os trabalhos eleitorais

### Referências legais
- Art. 38, §3º, Resolução n.º 23.659/2021

### Dicas de prova
- Diferenciar entre o título eleitoral e a multa por ausência às urnas
- Conhecer as normas de acessibilidade para os títulos eleitorais digitais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.84", "page_number": 84, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 38, §3º, Resolução n.º 23.659/2021"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:36:11.348081+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=84", "doc_key": "d72bca1abb0bc6cf0c61b4b767cea7f4"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '8691c28c04c206f1145596c66a83d65272a1e6fe68e8d20530e792d2ab4e8a3f'),
  ('cpiuris2025::7932a36c02c8f2cc39a78a8f820bad42', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Alistamento Eleitoral', '## Alistamento Eleitoral

Rege-se a obtenção da via digital do documento de identificação com exigência de coincidência dos dados informados pelo eleitor ou pela eleitora com os constantes do Cadastro Eleitoral.

### Conceitos
- **Alistamento Eleitoral**: O processo de registro de eleitores no Tribunal Superior Eleitoral
- **Via Digital do Título de Eleitor**: Um documento digital que comprova a identidade e o alistamento do eleitor
- **Cadastro Eleitoral**: O registro dos eleitores no Tribunal Superior Eleitoral
- **Biometria**: A utilização de características físicas, como impressões digitais ou reconhecimento facial, para identificação
- **Justiça Eleitoral**: O órgão responsável pela organização e supervisão do processo eleitoral

### Referências legais
- Art. 70
- Art. 71
- Art. 72
- Art. 73
- Art. 74
- Art. 91
- Lei n.º 9.504/97

### Dicas de prova
- Entenda a importância da coincidência dos dados informados pelo eleitor com os constantes do Cadastro Eleitoral
- Conheça as condições para a obtenção da via digital do título de eleitor', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.85 (1)", "page_number": 85, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 70", "Art. 71", "Art. 72", "Art. 73", "Art. 74", "Art. 91", "Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:36:45.803725+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=85", "doc_key": "7932a36c02c8f2cc39a78a8f820bad42"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '4e59e8ab177e10513bee2aec0644a567dc3557a40f4fb55bb494a837ebdbc3d8'),
  ('cpiuris2025::5631809e5350efb0f9b60011fa35e490', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Exclusão do Direito de Voto', '## Exclusão do Direito de Voto

A exclusão do direito de voto ocorre por infrações específicas, incluindo a suspensão ou perda dos direitos políticos, pluralidade de inscrição, falecimento do eleitor e deixar de votar em três eleições consecutivas.

### Conceitos
- **Cancelamento da inscrição**: Ação tomada quando o eleitor está privado dos direitos políticos temporariamente ou definitivamente.
- **Art. 5º, III do CE**: Regula os casos em que os direitos políticos são suspensos ou perdidos.
- **Art. 42 do CE**: Prevê o alistamento fora do domicílio eleitoral como causa de cancelamento da inscrição.
- **Voto obrigatório**: Não mais é um direito, mas uma obrigação para os eleitores.
- **Direitos políticos**: Incluem o voto, a participação em assembleias e a participação em processos eleitorais.

### Referências legais
- Art. 5º, III do CE
- Art. 42 do CE

### Dicas de prova
- Entenda que o cancelamento da inscrição é uma ação específica
- Conheça as restrições do voto para analfabetos e expressão em língua nacional
- Aprenda com o art. 42 do CE', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.85 (2)", "page_number": 85, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 5º, III do CE", "Art. 42 do CE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:37:18.017770+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=85", "doc_key": "5631809e5350efb0f9b60011fa35e490"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '1246340277b45d257085058b6afeb22552e9f868f2a5788b1d76608d0f410cc3'),
  ('cpiuris2025::4e7ca80f7ef95799ea4c2af3a3328ccc', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Suspensão e cancelamento de inscrição eleitoral', '## Suspensão e cancelamento de inscrição eleitoral

A suspensão dos direitos políticos não é cancelamento de inscrição, mas sim uma suspensão temporária do exercício dos direitos políticos. O cancelamento da inscrição ocorre após a exclusão do eleitor do cadastro, que pode ser feita ex officio ou a requerimento de delegado de partido.

### Conceitos
- **Suspensão**: Impossibilidade temporária do exercício dos direitos políticos
- **Cancelamento de inscrição**: Exclusão do eleitor do cadastro
- **Inscrição mais recente**: A inscrição que foi efetuada contrariamente às instruções em vigor
- **Domicílio eleitoral**: O endereço onde o eleitor deve estar para poder votar

### Referências legais
- Art. 87 da Resolução TSE n.º 23.659/2021
- Art. 77 do Código Eleitoral
- Art. 72 do Código Eleitoral
- Art. 71, §1º, do Código Eleitoral

### Jurisprudência
- RE 123456

### Dicas de prova
- Diferenciar entre suspensão e cancelamento de inscrição eleitoral
- Entender a ordem de prioridade para o cancelamento da inscrição
- Conhecer as causas que levam à exclusão do eleitor do cadastro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.86 (1)", "page_number": 86, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 87 da Resolução TSE n.º 23.659/2021", "Art. 77 do Código Eleitoral", "Art. 72 do Código Eleitoral", "Art. 71, §1º, do Código Eleitoral"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T23:38:06.724128+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=86", "doc_key": "4e7ca80f7ef95799ea4c2af3a3328ccc"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '5b964dc6f47f429173f27deefa9616344234f4424552c3388a080cffc425bd48'),
  ('cpiuris2025::411cd927b4f97ba507ed6d4307084cd8', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Revisão do Eleitorado', '## Revisão do Eleitorado

O procedimento administrativo de revisão do eleitorado é realizado pelo TSE, que verifica se os eleitores estão efetivamente domiciliados na zona eleitoral. A revisão é necessária quando o número de transferências for superior a 10% do ano anterior.

### Conceitos
- **Revisão do Eleitorado**: procedimento administrativo para verificar se os eleitores estão efetivamente domiciliados na zona eleitoral
- **TSE**: Tribunal Superior Eleitoral, responsável por realizar a revisão do eleitorado
- **Transferências**: mudanças de residência dos eleitores
- **Domicílio**: local onde o eleitor reside

### Referências legais
- Art. 92 da Lei n.º 9.504/97

### Dicas de prova
- Entenda a importância da revisão do eleitorado e como ela é realizada pelo TSE.
- Conheça as condições que desencadeiam a revisão do eleitorado, como o número de transferências.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.86 (2)", "page_number": 86, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 92 da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:38:32.571311+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=86", "doc_key": "411cd927b4f97ba507ed6d4307084cd8"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '054c7bc15c310875a2f7730194ade12362f18b6af8796e04fb287b70a0fa32c9'),
  ('cpiuris2025::c41d124477c53bf74ed30ddbeeee7190', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Revisão do Eleitorado e Perda/Suspensão dos Direitos Políticos', '## Revisão do Eleitorado e Perda/Suspensão dos Direitos Políticos

A revisão do eleitorado é realizada quando houver denúncia de fraude no alistamento, sendo presidida pelo juiz eleitoral da zona. A perda ou suspensão dos direitos políticos é vedada pela Constituição Federal, permitindo apenas a perda (prazo indeterminado) ou suspensão (prazo determinado).

### Conceitos
- **Alistamento Eleitoral**: O processo de inscrição dos eleitores no rol eleitoral
- **Revisão do Eleitorado**: A revisão do eleitorado é realizada quando houver denúncia de fraude no alistamento
- **Perda dos Direitos Políticos**: A perda dos direitos políticos é vedada pela Constituição Federal, permitindo apenas a perda (prazo indeterminado) ou suspensão (prazo determinado)
- **Suspensão dos Direitos Políticos**: A suspensão dos direitos políticos é uma medida temporária
- **Cancelamento da Naturalização**: O cancelamento da naturalização é uma hipótese de perda dos direitos políticos
- **Incapacidade Civil Absoluta**: A incapacidade civil absoluta é outra hipótese de perda dos direitos políticos

### Referências legais
- Art. 71, §4º, do CE
- Art. 92 da Lei n.º 9504/97
- Art. 15 da Constituição Federal

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre perda e suspensão dos direitos políticos
- Conheça as hipóteses de perda dos direitos políticos
- Aprenda com o art. 71, §4º, do CE e sua aplicação prática', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.87", "page_number": 87, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 71, §4º, do CE", "Art. 92 da Lei n.º 9504/97", "Art. 15 da Constituição Federal"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T23:39:21.293053+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=87", "doc_key": "c41d124477c53bf74ed30ddbeeee7190"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'c02f18a720435a89db913faa893420f83bdf194c1865b8ca78a1bdb10b412c37'),
  ('cpiuris2025::fa560188045d6498fdb7ec350ba678c8', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Suspensão dos Direitos Políticos', '## Suspensão dos Direitos Políticos

A suspensão dos direitos políticos é regulada por lei e não pode ser instituída por meio de legislação infraconstitucional. As pessoas com deficiência têm garantido o direito ao exercício da sua capacidade legal em igualdade de condições com as demais pessoas.

### Conceitos
- **incapacidade civil**: estado jurídico que impede a pessoa de exercer os atos da vida civil
- **deficiência**: condição física ou mental que afeta a capacidade de uma pessoa
- **direito político**: direito de participar das eleições e de exercer funções públicas
- **legislação infraconstitucional**: leis que não são parte da Constituição

### Referências legais
- Art. 15, II, da CF/88
- Lei n.º 13.146/2015

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre incapacidade civil e deficiência
- Conheça as garantias para pessoas com deficiência no Estatuto da Pessoa com Deficiência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.88", "page_number": 88, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 15, II, da CF/88", "Lei n.º 13.146/2015"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-26T23:40:05.485462+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=88", "doc_key": "fa560188045d6498fdb7ec350ba678c8"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '542cbac449790374c46aeb88776af15d9889bc7644f7f6d7ed483b6d3c2f9b7e'),
  ('cpiuris2025::aea384d77eef9fe9b20538e99cadb480', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Suspensão de direitos políticos', '## Suspensão de direitos políticos

A suspensão de direitos políticos decorrente de condenação criminal transitada em julgado cessa com o cumprimento ou a extinção da pena, independentemente de reabilitação ou de prova de reparação dos danos.

### Conceitos
- **Condenação criminal transitada em julgado**: Condenação que já passou pelo processo judicial
- **Suspensão de direitos políticos**: Interdição temporária do exercício dos direitos políticos
- **Pena privativa de liberdade**: Pena que envolve a privação da liberdade
- **Reabilitação**: Restauração dos direitos perdidos

### Referências legais
- Art. 15, § 3º da Lei nº 9.507/1998
- Súmula n.º 9 do TSE

### Jurisprudência
- RE 601182
- RESPE n.º 13293

### Dicas de prova
- Distinção entre condenação criminal e contravenção penal
- Importância da suspensão de direitos políticos em relação à pena privativa de liberdade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.89", "page_number": 89, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 15, § 3º da Lei nº 9.507/1998", "Súmula n.º 9 do TSE"], "jurisprudence": ["RE 601182", "RESPE n.º 13293"], "confidence": 0.8, "extracted_at": "2026-05-26T23:40:32.275780+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=89", "doc_key": "aea384d77eef9fe9b20538e99cadb480"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '37898a8a31e14d1267b5dae6d02dc7dfd9c988cd5a33e4553973c1a95fbeab0e'),
  ('cpiuris2025::0e6d691d5e0bca6d6ed12b4a321df6a7', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Convenções Partidárias e Registros de Candidaturas', '## Convenções Partidárias e Registros de Candidaturas

As normas sobre as convenções partidárias para escolha de candidatos estão previstas na Lei n.º 9.504/97, estabelecendo regras para a escolha, substituição e formação de coligações.

### Conceitos
- **Convenção Partidária**: Reunião do partido político para definir os candidatos
- **Coligação**: União de partidos políticos para lançar candidatos em eleições
- **Estatuto do Partido**: Documento que estabelece as regras internas do partido político
- **Domicílio Eleitoral**: Local onde o eleitor tem residência permanente
- **Filiação Partidária**: Processo pelo qual o candidato se junta ao partido político

### Referências legais
- Art. 7º da Lei n.º 9.504/97
- Art. 8º da Lei n.º 9.504/97
- Lei n.º 13.165/2015

### Dicas de prova
- Entenda a importância das convenções partidárias e como elas afetam a escolha de candidatos
- Conheça as regras para a formação de coligações e o papel do estatuto do partido', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.91", "page_number": 91, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 7º da Lei n.º 9.504/97", "Art. 8º da Lei n.º 9.504/97", "Lei n.º 13.165/2015"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:41:09.527951+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=91", "doc_key": "0e6d691d5e0bca6d6ed12b4a321df6a7"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'fab2c343f62179ebffc4a927d9cc339a5fb393489fb2fe7aa3b541ab67cc478f'),
  ('cpiuris2025::7b9751c5b7b917f1482509d608c81002', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Convenções Partidárias e Registros de Candidaturas', '## Convenções Partidárias e Registros de Candidaturas

Regulamentam a escolha de candidatos por partidos políticos para cargos eleitos, incluindo a reserva de vagas para cada sexo.

### Conceitos
- **Convenção Partidária**: Reunião do partido político para escolher candidatos
- **Candidatura**: Candidato a cargo eleito
- **Reserva de Vagas**: Percentual mínimo e máximo de vagas reservadas para cada sexo
- **DRAP**: Demonstrativo de Regularidade dos Atos Partidários
- **Falsidade Ideológica Eleitoral**: Prática de alteração do registro partidário

### Referências legais
- Art. 10 da Lei n.º 9.504/97

### Dicas de prova
- Entenda a importância das convenções partidárias e a reserva de vagas para cada sexo.
- Conheça o DRAP e as consequências de não regularizar a situação nos prazos estabelecidos.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.92 (1)", "page_number": 92, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 10 da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:41:50.106709+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=92", "doc_key": "7b9751c5b7b917f1482509d608c81002"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '48bdda89a584f90c1d69dad2272df985bc9b9b72270ce8e1c44a610178d6b11f'),
  ('cpiuris2025::cca7383c15a7760f055e4dd833b9306b', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Despesas eleitorais e fraude', '## Despesas eleitorais e fraude

O texto destaca que despesas eleitorais contabilizadas não são motivo de perda do diploma, mas a fraude pode comprometer a disputa. Além disso, o TSE decidiu que a ausência de propaganda eleitoral em prol da candidata também não é motivo de perda.

### Conceitos
- **Despesas eleitorais**: gastos autorizados pela lei para a campanha eleitoral
- **Fraude eleitoral**: ato ilegal ou irregular que visa prejudicar o processo eleitoral

### Referências legais
- Art. 74 da Lei 9.504/1997

### Jurisprudência
- RESPE n.º 1939212
- TSE — RESPE n.º 19392

### Dicas de prova
- Pergunte sobre a natureza das despesas eleitorais e como elas são contabilizadas.
- Entenda o conceito de fraude eleitoral e como ela pode afetar a disputa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.92 (2)", "page_number": 92, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 74 da Lei 9.504/1997"], "jurisprudence": ["RESPE n.º 1939212", "TSE — RESPE n.º 19392"], "confidence": 0.8, "extracted_at": "2026-05-26T23:42:13.606249+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=92", "doc_key": "cca7383c15a7760f055e4dd833b9306b"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '74b775ccb6f1c837d82da828bf601d1e1abab5656f46d9d7f0d8f084404c7089'),
  ('cpiuris2025::9fce9cc97198c968a3ffaaa3bc7e3ed5', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Convênções partidárias e registros de candidaturas', '## Convênções partidárias e registros de candidaturas

A AIJE pode ser utilizada para apurar fraude à cota de gênero, com a cassação de diplomas ou mandatos de candidatos envolvidos na fraude.

### Conceitos
- **AIJE**: Ação de Investigação Judicial Eleitoral
- **Abuso de poder**: Conduzido que se constitui em tipo de abuso de poder, com consequências como cassação de mandatos e diplomas
- **Cota de gênero**: Percentual mínimo de candidaturas femininas necessárias para a validade do registro

### Referências legais
- Art. 10, § 3º, da Lei n. 9.504/97

### Jurisprudência
- ADI 6338/DF
- Súmula 73 do TSE

### Dicas de prova
- Entenda a diferença entre abuso de poder e fraude à cota de gênero
- Conheça o artigo 10, § 3º, da Lei n. 9.504/97
- Aprenda a aplicar a AIJE para apurar fraude à cota de gênero', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.93 (1)", "page_number": 93, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 10, § 3º, da Lei n. 9.504/97"], "jurisprudence": ["ADI 6338/DF", "Súmula 73 do TSE"], "confidence": 0.8, "extracted_at": "2026-05-26T23:42:45.759309+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=93", "doc_key": "9fce9cc97198c968a3ffaaa3bc7e3ed5"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '9f79d4a946cb610fc6c4df0b03978a37fe1328a553cc2074f15699d07dc7e6d3'),
  ('cpiuris2025::0fe0e3d87b9e6a12b8b483794349eec2', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Reconhecimento de ilícito eleitoral e suas consequências', '## Reconhecimento de ilícito eleitoral e suas consequências

O reconhecimento do ilícito acarreta a cassação do Drap, inelegibilidade dos envolvidos e nulidade dos votos.

### Conceitos
- **votação zerada**: voto não expresso ou nulo
- **prestação de contas zerada**: ausência de movimentação financeira relevante
- **atos efetivos de campanha**: ações realizadas para divulgar a candidatura

### Referências legais
- art. 222 do Código Eleitoral

### Dicas de prova
- Distinção entre participação direta e indireta na fraude
- Reconhecimento do ilícito e suas consequências', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.93 (2)", "page_number": 93, "discipline": "Direito Eleitoral", "legal_refs": ["art. 222 do Código Eleitoral"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:43:17.262691+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=93", "doc_key": "0fe0e3d87b9e6a12b8b483794349eec2"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '558978c3ce2239bd177882ba736264a7552712f7f63c63aae59ee05a1b3c4952'),
  ('cpiuris2025::245b47b285ddff621b2482a58dc48fdb', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Convenções partidárias e registros de candidaturas', '## Convenções partidárias e registros de candidaturas

A ADI do Partido Solidariedade foi improcedente, pois a cassação das candidaturas apenas dos responsáveis pela fraude não afetaria o quociente partidário e estimularia a manutenção da conduta violadora.

### Conceitos
- **cota de gênero**: obrigação de observância à igualdade entre homens e mulheres em candidaturas
- **teoria do impacto desproporcional**: teoria que afirma que a exclusão de candidatos por razões de gênero pode ter consequências negativas para o sistema eleitoral
- **princípio da proporcionalidade**: princípio que exige que as medidas tomadas sejam proporcionais às finalidades perseguidas
- **fiscalização do DRAP**: obrigação de fiscalizar a regularidade formal e material das convenções partidárias

### Referências legais
- Art. 10, §3°, da Lei 9504/97
- Art. 22, XIV, da CRFB

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a teoria do impacto desproporcional e o princípio da proporcionalidade
- Conheça a cota de gênero e sua importância na eleitoral
- Avalie a necessidade de fiscalização do DRAP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.94 (1)", "page_number": 94, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 10, §3°, da Lei 9504/97", "Art. 22, XIV, da CRFB"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T23:43:52.118119+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=94", "doc_key": "245b47b285ddff621b2482a58dc48fdb"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'b32abfe212a08a32b83c2ad5a17f8af62976d57832e8312b89c73db29a6cdabf'),
  ('cpiuris2025::8dacb7c8ae67e2d1effde08aaeea3b62', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Análise da Regularidade do DRAP e Percentual Feminino', '## Análise da Regularidade do DRAP e Percentual Feminino

O texto destaca a importância da análise do DRAP para validação de candidaturas e o percentual mínimo de candidaturas femininas, que deve ser distribuído proporcionalmente ao número de candidatas por gênero.

### Conceitos
- **DRAP**: ato antecedente ao registro de candidatura
- **Percentual Feminino**: mínimo de recursos do Fundo Partidário a ser destinado às candidaturas femininas

### Referências legais
- Art. 9º da Lei nº 13.165/2015
- Súmula 5617/DF STF

### Jurisprudência
- ADI 5617/DF

### Dicas de prova
- Entenda a importância do DRAP e o percentual mínimo de candidaturas femininas
- Conheça a interpretação da STF sobre o art. 9º da Lei nº 13.165/2015', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.94 (2)", "page_number": 94, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 9º da Lei nº 13.165/2015", "Súmula 5617/DF STF"], "jurisprudence": ["ADI 5617/DF"], "confidence": 0.8, "extracted_at": "2026-05-26T23:44:18.417667+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=94", "doc_key": "8dacb7c8ae67e2d1effde08aaeea3b62"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '6312ccb95d3e27e1b4751c477c78f66641e31603763f257043702ffbf842a732'),
  ('cpiuris2025::c720c8a0f564c52138a92a81e95eabb8', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Cota Gênero e Distribuição do Fundo Partidário', '## Cota Gênero e Distribuição do Fundo Partidário

A lei estabelece a distribuição equitativa do fundo partidário entre as candidaturas de gênero, com o objetivo de viabilizar o percentual mínimo de 30% de candidaturas por gênero. A Suprema Corte declarou a inconstitucionalidade da expressão e manteve a regra de distribuição equitativa.

### Conceitos
- **Cota Gênero**: Distribuição do fundo partidário entre as candidaturas de gênero
- **Distribuição Equitativa**: Método de distribuição do fundo partidário entre as candidaturas de gênero
- **Fundo Partidário**: Recursos destinados a financiar as campanhas eleitorais
- **Autonomia Partidária**: Direito dos partidos políticos de tomar suas próprias decisões

### Referências legais
- Art. 10, §3º, da Lei nº 9.504/97
- ADI 5617
- EC n.º 117/2022

### Jurisprudência
- RE 123456
- Tema repetitivo sobre cota gênero e distribuição do fundo partidário

### Dicas de prova
- Entenda a importância da cota gênero na distribuição do fundo partidário
- Conheça o conceito de autonomia partidária e como ela se relaciona com a distribuição do fundo partidário', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.95 (1)", "page_number": 95, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 10, §3º, da Lei nº 9.504/97", "ADI 5617", "EC n.º 117/2022"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre cota gênero e distribuição do fundo partidário"], "confidence": 0.8, "extracted_at": "2026-05-26T23:45:06.230079+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=95", "doc_key": "c720c8a0f564c52138a92a81e95eabb8"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '238de6ce968a4a1e471c8962310a2037c87ad1bb1b87dbea5873323eab556862'),
  ('cpiuris2025::0d8698abd53120f989e79e1965a66642', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Cotas Raciais em Campanhas Eleitorais', '## Cotas Raciais em Campanhas Eleitorais

A Emenda Constitucional n. 133/2024 incluiu um §9º no art. 17 da CF/88, que obriga partidos políticos a aplicar 30% dos recursos públicos em candidaturas de pessoas pretas e pardas nas circunscrições que melhor atendam aos interesses e às estratégias partidárias.

### Conceitos
- **Cotas Raciais**: obrigação legal para a distribuição de recursos públicos em campanhas eleitorais
- **Fundos Especial e Partidário**: recursos públicos destinados às campanhas eleitorais
- **Poder Legislativo**: instituição que decide sobre a criação de cotas raciais

### Referências legais
- Art. 17 da CF/88
- §9º do Art. 17 da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo: Cotas Raciais em Campanhas Eleitorais

### Dicas de prova
- Entenda a diferença entre distribuição de recursos públicos e registro de candidatura
- Conheça as implicações da Emenda Constitucional n. 133/2024', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.95 (2)", "page_number": 95, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 17 da CF/88", "§9º do Art. 17 da CF/88"], "jurisprudence": ["RE 123456", "Tema repetitivo: Cotas Raciais em Campanhas Eleitorais"], "confidence": 0.8, "extracted_at": "2026-05-26T23:45:35.435010+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=95", "doc_key": "0d8698abd53120f989e79e1965a66642"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'fd592d3a60f1eef59f3fe434fabedea594112333d31b134c772a9a914bf3ba2a'),
  ('cpiuris2025::cc88bc11542327b765d7ca191180da0f', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Convenções Partidárias e Registros de Candidaturas', '## Convenções Partidárias e Registros de Candidaturas

O texto destaca a importância da aplicação de recursos para pessoas pretas e pardas nas eleições, com um percentual mínimo de 30%. Além disso, é apresentada a procedimento para o pedido de registro de candidatura, incluindo o Demonstrativo de Regularidade de Atos Partidários (DRAP).

### Conceitos
- **Convenção partidária**: Reunião do partido político para escolher o candidato
- **Demonstrativo de Regularidade de Atos Partidários (DRAP)**: Documento que comprova a regularidade dos atos partidários
- **Registro de candidatura**: Procedimento para inscrever um candidato nas eleições

### Referências legais
- Art. 3º da EC n. 133/2024
- Parágrafo único do mesmo artigo

### Dicas de prova
- Entenda a importância da aplicação de recursos para pessoas pretas e pardas nas eleições
- Conheça o procedimento para o pedido de registro de candidatura, incluindo o DRAP', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.96 (1)", "page_number": 96, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 3º da EC n. 133/2024", "Parágrafo único do mesmo artigo"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:46:06.349203+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=96", "doc_key": "cc88bc11542327b765d7ca191180da0f"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'e71217fd62222a7bdfc2bd4161b2f401e0c63c3543108d33da690eb100f4f34e'),
  ('cpiuris2025::0114f0401ce47e5a910c7010996bf1c5', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Registro de Candidatura', '## Registro de Candidatura

O registro de candidatura é obrigatório e deve ser solicitado à Justiça Eleitoral até o dia 15 de agosto do ano das eleições. O processo tem prioridade sobre outros processos.

### Conceitos
- **DRAP**: Delegação de Regulação da Partidária
- **Convenção partidária**: Reunião oficial do partido para escolher candidatos e definir direções
- **Registro de candidatura**: Obrigatório pedido à Justiça Eleitoral para inscrição de candidato em eleição

### Referências legais
- Art. 11, §1º, da Lei n.º 9.504/97

### Dicas de prova
- Perguntas sobre o DRAP e a convenção partidária podem ser difíceis.
- O registro de candidatura é obrigatório e deve ser solicitado à Justiça Eleitoral com os documentos certificados.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.96 (2)", "page_number": 96, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 11, §1º, da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:46:39.782104+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=96", "doc_key": "0114f0401ce47e5a910c7010996bf1c5"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '4809299d1d8eb950eabdad0e7c68089101e4daf19f002eab25c1bcb29407a34f'),
  ('cpiuris2025::0f37e481aea76db531b63455c90481eb', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Convenções Partidárias e Registros de Candidaturas', '## Convenções Partidárias e Registros de Candidaturas

O texto discute as exigências para a inscrição de candidatos nas eleições, incluindo provas de filiação partidária, declarações de bens e certidões eleitorais.

### Conceitos
- **Convenção Partidária**: Acordo entre o partido e o candidato para a inscrição nas eleições
- **Registro de Candidatura**: Processo formalizado pela Justiça Eleitoral para a inscrição do candidato nas eleições
- **Certidão de Quitação Eleitoral**: Documento que comprova o exercício regular dos direitos políticos e a não existência de multas aplicadas pela Justiça Eleitoral

### Referências legais
- Art. 7º da Lei das Eleições
- Súmula 437/STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Registros de Candidaturas

### Dicas de prova
- Entenda a importância das convenções partidárias e os requisitos para o registro de candidaturas
- Conheça as diferentes formas de certidão de quitação eleitoral e suas implicações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.97 (1)", "page_number": 97, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 7º da Lei das Eleições", "Súmula 437/STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Registros de Candidaturas"], "confidence": 0.8, "extracted_at": "2026-05-26T23:47:12.170852+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=97", "doc_key": "0f37e481aea76db531b63455c90481eb"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '576198b5828470d3dd494385c3dbed982f93b565f799691de719ac26d832e149'),
  ('cpiuris2025::bb2bfac2169025512b149d7026b516ac', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Parcelamento das multas eleitorais', '## Parcelamento das multas eleitorais

Os cidadãos e pessoas jurídicas têm direito a parcelar as multas eleitorais, dentro de um prazo de até 60 meses, com limites de 5% da renda mensal para cidadãos e 2% do faturamento para pessoas jurídicas.

### Conceitos
- **Responsabilidade Solidária**: Exclusão de responsabilidade solidária em parcelamento de multas
- **Parcelamento das Multas**: Direito dos cidadãos e pessoas jurídicas a dividir as multas em parcelas
- **Limites de Parcelamento**: 5% da renda mensal para cidadãos, 2% do faturamento para pessoas jurídicas

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a diferença entre responsabilidade solidária e parcelamento de multas
- Leia atentamente as limites de parcelamento para cidadãos e pessoas jurídicas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.97 (2)", "page_number": 97, "discipline": "Direito Eleitoral", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:47:36.669463+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=97", "doc_key": "bb2bfac2169025512b149d7026b516ac"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '7c960a4e6b8c0c183274f5b01ea8c27bbc7673eefa6ac3641ce82e972721d206'),
  ('cpiuris2025::85607552d6e7459ad853ccb7f95dbe35', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Parcelamento de multas eleitorais e registro de candidaturas avulsas', '## Parcelamento de multas eleitorais e registro de candidaturas avulsas

O parcelamento de multas eleitorais é garantido a partidos políticos em até 60 meses, com limite de 2% do repasse mensal do Fundo Partidário. Além disso, o registro de candidatura avulsa está vedado, mesmo que o requerente tenha filiação partidária.

### Conceitos
- **Parcelamento de multas eleitorais**: Garantia a partidos políticos em até 60 meses
- **Registro de candidatura avulsa**: Vedado, mesmo que o requerente tenha filiação partidária
- **Fundo Partidário**: Fonte de financiamento para partidos políticos
- **Quitação eleitoral**: Certificado que indica a regularidade do gozo dos direitos políticos e do exercício do voto

### Referências legais
- Art. 14, §3º, V da Constituição Federal
- Lei n.º 9504/97, art. 11, §7º
- Lei n. 12.034/2009

### Jurisprudência
- RE 1.238.853 (STF)

### Dicas de prova
- Entenda a diferença entre parcelamento de multas eleitorais e registro de candidatura avulsa
- Conheça as regras para a quitação eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.98 (1)", "page_number": 98, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 14, §3º, V da Constituição Federal", "Lei n.º 9504/97, art. 11, §7º", "Lei n. 12.034/2009"], "jurisprudence": ["RE 1.238.853 (STF)"], "confidence": 0.8, "extracted_at": "2026-05-26T23:48:25.358688+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=98", "doc_key": "85607552d6e7459ad853ccb7f95dbe35"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '916c5c51e0ecf7c6988f018024e80a2c566ce4bd1ae343a8b69f1907ffc0e287'),
  ('cpiuris2025::0e4c61cc10f4b722863a4d12bdf952e7', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Quitação Eleitoral e Inelegibilidade', '## Quitação Eleitoral e Inelegibilidade

A desaprovação das contas não obsta a obtenção de quitação eleitoral, desde que apresentadas tempestivamente. A inelegibilidade é aferida no momento da formalização do pedido de registro da candidatura, ressalvando alterações supervenientes.

### Conceitos
- **Quitação Eleitoral**: obtenção de certidão após apresentação das contas de campanha
- **Inelegibilidade**: condição ou causa que impede alguém de ser eleito

### Referências legais
- Art. 11, §10 da Lei nº 9.504/97

### Jurisprudência
- Súmula 70 do TSE
- STF. Plenário. ADI 7.197/DF, Rel. Min. Carmen Lúcia, julgado em 25/11/2023 - info 1118

### Dicas de prova
- Distinção entre desaprovação e quitação eleitoral
- Entendimento da Súmula 70 do TSE', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.98 (2)", "page_number": 98, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 11, §10 da Lei nº 9.504/97"], "jurisprudence": ["Súmula 70 do TSE", "STF. Plenário. ADI 7.197/DF, Rel. Min. Carmen Lúcia, julgado em 25/11/2023 - info 1118"], "confidence": 0.9, "extracted_at": "2026-05-26T23:48:51.198365+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=98", "doc_key": "0e4c61cc10f4b722863a4d12bdf952e7"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '3b9a9f50653cb1f9218356e560867880cd08db7f5596f6860cdecd1bf5a99f36'),
  ('cpiuris2025::a6b5fd467cd8657dd7eb68240696559d', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Prazo para afastamento da inelegibilidade', '## Prazo para afastamento da inelegibilidade

O Supremo Tribunal Federal considera que o prazo máximo para afastamento da inelegibilidade é a data das eleições, não a data da diplomação.

### Conceitos
- **inelegibilidade**: Habilidade do candidato de se candidatar às eleições
- **prazo máximo**: Prazo estabelecido para o afastamento da inelegibilidade
- **data das eleições**: Data até a qual se considera o prazo máximo para afastamento da inelegibilidade

### Referências legais
- Art. 16-A da Lei nº 9.504/97
- Súmula 729/STF

### Jurisprudência
- ADI 7197/DF
- Tema repetitivo: prazo para afastamento da inelegibilidade

### Dicas de prova
- Entenda a diferença entre data da diplomação e data das eleições
- Conheça o princípio in dubio pro voto', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.99 (1)", "page_number": 99, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 16-A da Lei nº 9.504/97", "Súmula 729/STF"], "jurisprudence": ["ADI 7197/DF", "Tema repetitivo: prazo para afastamento da inelegibilidade"], "confidence": 0.8, "extracted_at": "2026-05-26T23:49:20.228923+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=99", "doc_key": "a6b5fd467cd8657dd7eb68240696559d"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '6b85d32ae13029ac5649e45cccc9ef99543ca2923599238387564aedd7c1c8d9'),
  ('cpiuris2025::539d3f16ab5deff64dab3e15091b1eaa', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Garantia de direitos das candidaturas indeferidas', '## Garantia de direitos das candidaturas indeferidas

A Justiça Eleitoral não garante o direito de realizar atos de campanha e manutenção do nome na urna para candidaturas deferidas com recurso pendente ou ainda não apreciadas.

### Conceitos
- **Direitos das candidaturas**: Direitos garantidos às candidaturas que foram indeferidas
- **Sistema proporcional**: Método de distribuição dos votos em sistema proporcional
- **Candidatura deferida**: Candidatura que foi aprovada após recurso pendente
- **Sub judice**: Candidatura que permanece sob julgamento

### Referências legais
- Art. 16-A da Lei 9504/97
- Súmula 499 do TSE

### Jurisprudência
- ADI 4.513/DF
- ADI 4.542/DF
- ADPF 223/DF

### Dicas de prova
- Entenda a diferença entre sistema proporcional e outros métodos de distribuição dos votos
- Conheça as implicações da sub judice para candidaturas indeferidas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.99 (2)", "page_number": 99, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 16-A da Lei 9504/97", "Súmula 499 do TSE"], "jurisprudence": ["ADI 4.513/DF", "ADI 4.542/DF", "ADPF 223/DF"], "confidence": 0.8, "extracted_at": "2026-05-26T23:49:58.740809+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=99", "doc_key": "539d3f16ab5deff64dab3e15091b1eaa"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'fa2ee51eea44c7d6699e25ada2121c66e031664de16e74f4bb6b6717c8cc4199'),
  ('cpiuris2025::8fc67313a558c615bbbea83c4b45f2b2', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Convenções partidárias e registros de candidaturas', '## Convenções partidárias e registros de candidaturas

A interpretação restritiva das convenções partidárias exige a preservação da vontade manifestada nas urnas, apenas aplicável às eleições proporcionais. O partido pode utilizar os votos obtidos para definir as cadeiras, mesmo que o candidato não possa se beneficiar diretamente.

### Conceitos
- **interpretação restritiva**: Interpretação que preserva a vontade manifestada nas urnas
- **eleições proporcionais**: Eleições em que os votos influem diretamente no cálculo do quociente partidário
- **interpretação ampla**: Não aplicável às eleições proporcionais
- **vontade manifestada nas urnas**: Vota dos eleitores que deve ser preservado

### Referências legais
- Art. 12 da Lei n.º 9504/97

### Dicas de prova
- Entenda a diferença entre interpretação restritiva e ampla
- Conheça as regras para os registros de candidaturas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.100 (1)", "page_number": 100, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 12 da Lei n.º 9504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:50:30.469171+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=100", "doc_key": "8fc67313a558c615bbbea83c4b45f2b2"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '0a93a4beea6b1777f07a88d867dde70a161e62fe2e673365369b6d1a7615889f'),
  ('cpiuris2025::bb9399377cf81a53cc4ca2c4d426ca01', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Registro de Candidatos com Dados Nominativos', '## Registro de Candidatos com Dados Nominativos

O registro de candidatos é deferido se não houver outro candidato com nome idêntico que esteja exercendo mandato eletivo ou tenha se candidatado com o mesmo nome. Em caso de impasse, a Justiça Eleitoral notifica os candidatos para que acordem sobre os nomes.

### Conceitos
- **Registro de Candidatos**: O processo pelo qual um candidato é inscrito no eleitoral
- **Dada Nome**: Um nome utilizado por um candidato para se identificar
- **Variação Nominal**: Uma alteração do nome de um candidato, como sobrenome ou inicial
- **Preferência**: A ordem em que os nomes são priorizados para registro

### Referências legais
- Art. 14 da Lei nº 4.737/1965
- ...

### Jurisprudência
- Súmula n.º 4 do TSE

### Dicas de prova
- Entenda a noção de variação nominal e preferência
- Conheça a Súmula n.º 4 do TSE', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.100 (2)", "page_number": 100, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 14 da Lei nº 4.737/1965", "..."], "jurisprudence": ["Súmula n.º 4 do TSE"], "confidence": 0.8, "extracted_at": "2026-05-26T23:50:56.895411+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=100", "doc_key": "bb9399377cf81a53cc4ca2c4d426ca01"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'b37cdb2b8982de2aea5f595f10ceb03d97a86f1b65bb67d1fb025ac245ca4220'),
  ('cpiuris2025::912e417be69d6e88de3b89575dd211e8', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Substituição de candidatos após o término do prazo de registro das candidaturas', '## Substituição de candidatos após o término do prazo de registro das candidaturas

Rege a substituição de candidatos que se tornam inelegíveis, renunciam ou falecem após o termo final do prazo do registro. O partido pode substituir o candidato com escolha conforme as normas do estatuto do partido.

### Conceitos
- **Substituição de candidatos**: Ação realizada por um partido para substituir um candidato que se tornou inelegível, renunciou ou faleceu após o termo final do prazo do registro.
- **Inelegibilidade**: Situação em que um candidato não pode ser eleito devido a uma causa legal
- **Renúncia**: Ação pelo qual um candidato se retira da corrida eleitoral
- **Falecimento**: Morte de um candidato antes do pleito

### Referências legais
- Art. 13 da Lei n.º 9.504/97

### Dicas de prova
- Entenda a diferença entre substituição e renúncia de candidato.
- Conheça as regras para a escolha do novo candidato em caso de substituição.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.101 (1)", "page_number": 101, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 13 da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-26T23:51:40.783095+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=101", "doc_key": "912e417be69d6e88de3b89575dd211e8"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'c708840793fb04f1944358d6a82f1d13d5c29144de9acefef3699a70dbfb214c'),
