O diplomação do candidato é meramente declaratório, enquanto os constitutivos são evidenciados pelo resultado das urnas. Os candidatos que forem expulsos do partido até a data da eleição podem ter seu registro cancelado.

### Conceitos
- **Diplomação**: Ato de declarar um candidato eleito
- **Registro do candidato**: O processo pelo qual o candidato é inscrito para a eleição
- **Cancelamento do registro**: Ato que elimina o registro do candidato da eleição

### Referências legais
- Art. 14 da Lei n.º 9.504/97

### Jurisprudência
- TSE — CTA n.º 1204

### Dicas de prova
- Entenda a diferença entre diplomação e registro do candidato
