  ('cpiuris2025::3c9c5e15d47080449827520eabeb4b60', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Convenções partidárias e registros de candidaturas', '## Convenções partidárias e registros de candidaturas

A expulsão do partido é matéria interna corporis, enquanto o cancelamento do registro é da competência da Justiça Eleitoral. O cancelamento será solicitado pelo partido e decidido pela Justiça Eleitoral.

### Conceitos
- **expulsão**: matéria interna corporis do partido político
- **cancelamento de registro**: competência da Justiça Eleitoral
- **partido político**: organização política com estrutura e regras internas

### Referências legais
- Art. 16 da Lei n.º 9.504/97

