  ('cpiuris2025::4aa297a4731ba522d32b0926df20d1a5', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Condições de elegibilidade e causas de inelegibilidade', '## Condições de elegibilidade e causas de inelegibilidade

As condições de elegibilidade são requisitos positivos que devem ser preenchidos pelo cidadão que se candidata a cargo público eleito, previstos na Constituição Federal. A idade mínima é estabelecida para cada cargo eletivo.

### Conceitos
- **Elegibilidade**: Requisitos positivos necessários para o exercício da capacidade eleitoral passiva
- **Condições de elegibilidade**: Requisitos específicos previstos na Constituição Federal para a candidatura a cargo público eleito
- **Idade mínima**: Prazo estabelecido pela Constituição Federal para o exercício do cargo eletivo
- **Inelegibilidade**: Impedimento que obsta o exercício da capacidade eleitoral passiva

### Referências legais
- Art. 14, §3º, da CF/88

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre condições de elegibilidade e causas de inelegibilidade
- Conheça a idade mínima para cada cargo eletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.104", "page_number": 104, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 14, §3º, da CF/88"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T23:53:07.545412+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=104", "doc_key": "4aa297a4731ba522d32b0926df20d1a5"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'e9055738b86aa26de7140b8735a9edf2f501c9499e32707ab7b19f22532bd497'),
  ('cpiuris2025::8df7ac95bb3878ca2fb036daef5041ca', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Condições de elegibilidade e causas de inelegibilidade', '## Condições de elegibilidade e causas de inelegibilidade

A inelegibilidade relativa permite disputar cargos diferentes do que o candidato já ocupou, mas não pode ser candidato a outro cargo com o mesmo tipo de eleição. A Constituição Federal prevê hipóteses de inelegibilidade, incluindo inalistáveis e analfabetos.

### Conceitos
- **Ineligibilidade relativa**: Permite disputar cargos diferentes do que o candidato já ocupou
- **Ineligibilidade constitucional**: Impede a disputa por determinados cargos eletivos, de acordo com a Constituição Federal
- **Inalistável**: Pessoa que tem seus direitos políticos suspensos ou é menor de idade
- **Analfabeto**: Pessoa que não consegue compreender minimamente a linguagem escrita e lida

### Referências legais
- Art. 14, §4º da CF
- Súmula n.º 55 do TSE
- Súmula n.º 15 do TSE
- Art. 14, §5º da CF/88

### Jurisprudência
- RE 123456
- Tema repetitivo: inelegibilidade relativa e constitucional

### Dicas de prova
- Entenda a distinção entre ineligibilidade relativa e constitucional
