  ('cpiuris2025::4c856c5ca0114b70724939ecd7464384', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Reeleição de autoridades eleitorais', '## Reeleição de autoridades eleitorais

Autoriza a reeleição de autoridades eleitorais para um único período subsequente, após substituição no curso dos mandatos, alterada pela EC n.º 16/97.

### Conceitos
- **Reeleição**: Período subsequente de exercício de cargo por uma pessoa que já o ocupou
- **Substituição**: Mudança do titular de um cargo eleitoral para outro
- **Ineligibilidade**: Impossibilidade de exercer cargo ou função por tempo determinado

### Referências legais
- EC n.º 16/97

### Jurisprudência
- TSE - Recurso Ordinário n.º 060247518

### Dicas de prova
- Distinção entre reeleição e substituição
