  ('cpiuris2025::4bcfe0aedd5d58c0595f6d0a652dd361', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Condições de elegibilidade e causas de inelegibilidade', '## Condições de elegibilidade e causas de inelegibilidade

A proibição da segunda reeleição é absoluta e torna inelegível o candidato que já exerceu dois mandatos consecutivos em cargo da mesma natureza, independentemente do município.

### Conceitos
- **Releação**: Proibição da segunda eleição para um mesmo cargo
- **Mandato Consecutivo**: Exercício de dois mandatos consecutivos em cargo da mesma natureza
- **Desincompatibilização**: Renúncia ao mandato para concorrer a outros cargos
- **Terceira Inelegibilidade**: Proibição de concorrer a cargo após ter renunciado ao mandato anterior

### Referências legais
- Art. 14, § 5º da Constituição
- Súmula 0600162/96

### Jurisprudência
- RE 637.485

