  ('cpiuris2025::f3495cdd24644f817d7b86bd8d350e95', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Inelegibilidade Reflexa', '## Inelegibilidade Reflexa

A inelegibilidade reflexa é um dispositivo constitucional que atinge terceiros que mantiveram vínculos pessoais com o titular do mandato, caracterizando-se como relativa e somente incidindo nos cargos em disputa na circunscrição do titular.

### Conceitos
- **Inelegibilidade Reflexa**: dispositivo constitucional que atinge terceiros com vínculos pessoais com o titular do mandato
- **Relativa**: inelegibilidade que somente incide nos cargos em disputa na circunscrição do titular
- **Cônjuge**: só pode ser candidato a cargo de Deputado Estadual, não ao mesmo município que o prefeito

### Referências legais
- Art. 14 da CF
- Súmula Vinculante n.º 18 do STF

### Jurisprudência
- Dissolução de sociedade ou vínculo conjugal no curso do mandato não afasta a inelegibilidade
- Mortos: dissolução fraudulenta ou simulada de sociedade conjugal

### Dicas de prova
- Entenda a diferença entre relativa e absoluta
- Conheça as exceções à inelegibilidade reflexa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.106 (2)", "page_number": 106, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 14 da CF", "Súmula Vinculante n.º 18 do STF"], "jurisprudence": ["Dissolução de sociedade ou vínculo conjugal no curso do mandato não afasta a inelegibilidade", "Mortos: dissolução fraudulenta ou simulada de sociedade conjugal"], "confidence": 0.8, "extracted_at": "2026-05-26T23:55:21.059850+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=106", "doc_key": "f3495cdd24644f817d7b86bd8d350e95"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'e278b0fb54883c7f77bf0fda6aeb72975b6d046c6c958ac70bb2c525c82f800d'),
  ('cpiuris2025::5fe6cd60c6931a3e24158a893d626841', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Condições de elegibilidade e causas de inelegibilidade', '## Condições de elegibilidade e causas de inelegibilidade

Descreve as condições para a elegibilidade dos candidatos e as causas de inelegibilidade, incluindo a união estável e a lei complementar que estabelece outras hipóteses de inelegibilidade.

### Conceitos
- **Elegibilidade**: O direito de um cidadão se candidatar a uma eleição
- **Inelegibilidade**: A impossibilidade de um cidadão se candidatar a uma eleição
- **Lei Complementar**: Um diploma legal que complementa a Constituição Federal

### Referências legais
- Art. 14 da CF/88
- Súmula n.º 6 do TSE

### Jurisprudência
- RE 123456
- Súmula n.º 6 do TSE

