  ('cpiuris2025::5de3630ac9e9549a6dedd0e5f16f5522', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Aumento dos prazos para registro de candidatura e sua relação com a coisa julgada', '## Aumento dos prazos para registro de candidatura e sua relação com a coisa julgada

A maioria do STF entende que o aumento dos prazos não é ofensivo à coisa julgada, já que a inelegibilidade não tem caráter punitivo. A minoria discorda, entendendo que a inelegibilidade é sanção cuja eficácia retroativa seria excepcional.

### Conceitos
- **Cosa julgada**: Conceito jurídico que se refere à ideia de que uma decisão judicial é definitiva e não pode ser alterada ou apagada
- **Inelegibilidade**: Sanção aplicada ao candidato que não atende aos requisitos legais para a eleição
- **Prazo de registro de candidatura**: Prazo estabelecido pela lei para que os candidatos se registrem e se qualifiquem para a eleição

### Referências legais
- Art. 102, § 3º da CF/1988

### Jurisprudência
- {''term'': ''RE 758461'', ''definition'': ''Acórdão do STF que decidiu sobre a inelegibilidade de um candidato''}
- {''term'': ''Agravo Regimental em Recurso Especial Eleitoral n.º 20143'', ''definition'': ''Acórdão do TSE que decidiu sobre a inelegibilidade de outro candidato''}

### Dicas de prova
- Entenda o conceito de coisa julgada e sua relação com a inelegibilidade.
