  ('cpiuris2025::127e995b5755ed64e5a2d2b09c611584', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Condições de elegibilidade e causas de inelegibilidade', '## Condições de elegibilidade e causas de inelegibilidade

A eleição de um candidato é afetada por condições de elegibilidade e causas de inelegibilidade, definidas pela Lei Complementar n.º 64/90.

### Conceitos
- **Abuso de poder econômico ou político**: Ação de investigação judicial eleitoral que pode atrair a incidência da inelegibilidade
- **Lei Complementar n.º 64/90**: Legislação que define as condições de elegibilidade e causas de inelegibilidade para os candidatos
- **Inelegibilidade do art. 1º, inciso I, alínea d**: Condição que exclui o candidato que foi condenado por abuso de poder econômico ou político em ação de investigação judicial eleitoral
- **Reserva legal proporcional**: Princípio que exige que as causas de inelegibilidade sejam interpretadas restritivamente para evitar restrições excessivas aos direitos políticos

### Referências legais
- Art. 1º, inciso I, alínea d, da LC n.º 64/90
- Súmula N do TSE

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a distinção entre abuso de poder econômico e político
- Conheça as causas de inelegibilidade definidas pela Lei Complementar n.º 64/90', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.108 (1)", "page_number": 108, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 1º, inciso I, alínea d, da LC n.º 64/90", "Súmula N do TSE"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-26T23:57:19.790951+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=108", "doc_key": "127e995b5755ed64e5a2d2b09c611584"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '64896f9c7cb857fce9a7c2f1ea8f32754d891b3f6981f0eda2f4e96ae83c660e'),
  ('cpiuris2025::07f2be45d72e1b2983a3c67989f33919', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Exigências para a elegibilidade dos candidatos', '## Exigências para a elegibilidade dos candidatos

Candidatos devem ser proprietários ou controladores de empresa que tenham contrato com pessoa jurídica de direito público, ocupar cargo remunerado em pessoas jurídicas públicas, patrocinar causa de interesse público ou detener mais de um mandato público eletivo.

### Conceitos
- **Elegibilidade**: Requisito para que alguém possa ser eleito
- **Contrato com pessoa jurídica de direito público**: Exigência para a elegibilidade dos candidatos
- **Cargo remunerado em pessoas jurídicas públicas**: Exigência para a elegibilidade dos candidatos
- **Patrocínio de causa de interesse público**: Exigência para a elegibilidade dos candidatos
- **Mandato público eletivo**: Requisito para que alguém possa ser eleito

### Referências legais
- Art. 299, § 3º da Lei nº 9.504/1997
- Súmula 537 do STF

### Jurisprudência
- RE 929670
- ...

### Dicas de prova
- Distinção entre propriedade e controle de empresa
