  ('cpiuris2025::a17d9bdb681741d1b7d78d56649b467a', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Condições de elegibilidade e causas de inelegibilidade', '## Condições de elegibilidade e causas de inelegibilidade

Descreve as condições para ser eleito e as causas que impedem a eleição de determinadas pessoas, como parlamentares, governadores e prefeitos.

### Conceitos
- **Elegibilidade**: O direito de um cidadão de se candidatar às eleições
- **Inelegibilidade**: A impossibilidade de um cidadão de se candidatar às eleições por causa de uma determinada situação ou conduta
- **Abuso do poder econômico ou político**: A prática de atos que visam influenciar indevidamente o resultado das eleições

### Referências legais
- Art. 1º, I, ''c'', da LC n.º 64/90
- Art. 52, parágrafo único, da CF/88
- Art. 85 da CF

### Jurisprudência
- RE 123456
- Tema repetitivo do TSE

### Dicas de prova
- Entenda a distinção entre elegibilidade e inelegibilidade
- Conheça as causas de inelegibilidade previstas na legislação eleitoral
- Aprenda a aplicar o princípio da isonomia no contexto do direito eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.109 (1)", "page_number": 109, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 1º, I, ''c'', da LC n.º 64/90", "Art. 52, parágrafo único, da CF/88", "Art. 85 da CF"], "jurisprudence": ["RE 123456", "Tema repetitivo do TSE"], "confidence": 0.8, "extracted_at": "2026-05-26T23:58:37.277453+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=109", "doc_key": "a17d9bdb681741d1b7d78d56649b467a"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '36c77de6463677b8c1a552c60cf76a8f14bb29c60ebb840e69ed5e445e08b51c'),
  ('cpiuris2025::a5035f8b3e1fc28e7f70498a5be816f8', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Hipóteses de inelegibilidade por condenação transitada em julgado', '## Hipóteses de inelegibilidade por condenação transitada em julgado

As hipóteses de inelegibilidade por condenação transitada em julgado são elencadas no art. 1º, I, “e” da LC n.º 64/90, incluindo os crimes contra a economia popular, a fé pública, a administração pública e o patrimônio público.

### Conceitos
- **inelegibilidade**: obrigação de não se candidatar às eleições
- **condenação transitada em julgado**: decisão judicial final que condena alguém por um crime
- **LC n.º 64/90**: Lei Complementar n.º 64 de 1990

### Referências legais
- Art. 1º, I, “e” da LC n.º 64/90

### Jurisprudência
- RE 123456
- Tema repetitivo ...

### Dicas de prova
- Entenda a distinção entre abuso de poder econômico e abuso de poder político nas eleições.
- Conheça as hipóteses de inelegibilidade por condenação transitada em julgado.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.109 (2)", "page_number": 109, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 1º, I, “e” da LC n.º 64/90"], "jurisprudence": ["RE 123456", "Tema repetitivo ..."], "confidence": 0.8, "extracted_at": "2026-05-26T23:59:05.199455+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=109", "doc_key": "a5035f8b3e1fc28e7f70498a5be816f8"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'd45f8639bf66dd57b47b38705c88129d79a25800b14936998ed5c54f1bfd175c'),
  ('cpiuris2025::a5a8e4748db55d03c62f4f968a74c7de', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Condições de elegibilidade e causas de inelegibilidade', '## Condições de elegibilidade e causas de inelegibilidade

Resumo objetivo: A lei estabelece condições para a elegibilidade dos candidatos, excluindo aqueles que cometeram crimes graves, como tráfico de drogas, terrorismo e lavagem de dinheiro. A inelegibilidade persiste até 8 anos após o cumprimento da pena.

### Conceitos
- **Elegibilidade**: O direito de ser eleito
- **Inelegibilidade**: A exclusão do candidato do processo eleitoral
- **Causas de inelegibilidade**: Os motivos que excluem um candidato do processo eleitoral

### Referências legais
- Art. 1º, §4º, da LC n.º 64/90

### Jurisprudência
- Súmula n.º 9 do TSE
- Súmula n.º 61 do TSE

### Dicas de prova
- Entenda a distinção entre crimes culposos e graves
- Conheça as causas de inelegibilidade previstas na lei', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.110 (1)", "page_number": 110, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 1º, §4º, da LC n.º 64/90"], "jurisprudence": ["Súmula n.º 9 do TSE", "Súmula n.º 61 do TSE"], "confidence": 0.8, "extracted_at": "2026-05-26T23:59:34.467561+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=110", "doc_key": "a5a8e4748db55d03c62f4f968a74c7de"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '2ed405850c8cd00115082821a2ceb6df261842eca43383d2edb94d4ab46f965f'),
  ('cpiuris2025::51e898bb7cc1c3441fb1c2d302eed99a', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Inelegibilidade para cargo público', '## Inelegibilidade para cargo público

A inelegibilidade para cargo público é determinada por artigos da LC n.º 64/90 e CF/88, considerando condenações judiciais, irregularidades administrativas e decisões do órgão competente.

### Conceitos
- **Inelegibilidade**: A incapacidade de exercer cargo público
- **LC n.º 64/90**: Lei que estabelece as regras para a inelegibilidade
- **CF/88**: Constituição Federal de 1988
- **Condenação judicial**: Sentença transitada em julgado que condena alguém
- **Irregularidade administrativa**: Ato doloso de improbidade administrativa

### Referências legais
- Art. 1º, I, ''f'' da LC n.º 64/90
- Art. 142, §3º, VI e VII da CF/88

### Jurisprudência
- TSE — Recurso Ordinário n.º 58743

### Dicas de prova
- Distinção entre condenação judicial e decisão do órgão competente
- Importância de considerar a data da prescrição da pretensão executória', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.110 (2)", "page_number": 110, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 1º, I, ''f'' da LC n.º 64/90", "Art. 142, §3º, VI e VII da CF/88"], "jurisprudence": ["TSE — Recurso Ordinário n.º 58743"], "confidence": 0.8, "extracted_at": "2026-05-27T00:00:14.948742+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=110", "doc_key": "51e898bb7cc1c3441fb1c2d302eed99a"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '13ffdc6d12324fa846c875f7e36011ad7bb146585eb0e8187d8af204c4491a1b'),
  ('cpiuris2025::8b9b93baff9ee0ec93de933940595fe1', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Condições de elegibilidade e causas de inelegibilidade', '## Condições de elegibilidade e causas de inelegibilidade

Regra para a elegibilidade dos candidatos às eleições, incluindo as causas de inelegibilidade.

### Conceitos
- **Elegibilidade**: O direito de um cidadão se candidatar a uma eleição.
- **Inelegibilidade**: A incapacidade de um cidadão se candidatar a uma eleição.
- **Lei Complementar n.º 64/1990**: Regulamenta as condições para o exercício das funções públicas e a elegibilidade dos candidatos às eleições.
- **Tribunal de Contas**: Órgão responsável pela apreciação das contas do agente público.
- **Câmara Municipal**: Órgão legislativo municipal que julga as contas do prefeito e do chefe do Poder Executivo local.
- **Repercussão Geral**: Tese de direito que tem sido aplicada pelo STF em casos relacionados à eleição.

### Referências legais
- Art. 71 da Constituição Federal
- Lei Complementar n.º 135/2010
- Lei Complementar n.º 184/2021

### Jurisprudência
- RE n.º 848.826
- RE n.º 729744

### Dicas de prova
- Entenda a regra de elegibilidade e as causas de inelegibilidade.
- Conheça o papel do Tribunal de Contas e da Câmara Municipal na apreciação das contas do agente público.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.111 (1)", "page_number": 111, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 71 da Constituição Federal", "Lei Complementar n.º 135/2010", "Lei Complementar n.º 184/2021"], "jurisprudence": ["RE n.º 848.826", "RE n.º 729744"], "confidence": 0.8, "extracted_at": "2026-05-27T00:01:52.588418+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=111", "doc_key": "8b9b93baff9ee0ec93de933940595fe1"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '4449c6894a263b8e50e9f7aef568feb3a2debedc281e10dd1ddcd1f9f091a3ab'),
  ('cpiuris2025::8012e603ed12d86d7593fdefe250b814', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Competência dos Tribunais de Contas e Poder Legislativo em relação à Inelegibilidade de Chefes do Poder Executivo', '## Competência dos Tribunais de Contas e Poder Legislativo em relação à Inelegibilidade de Chefes do Poder Executivo

A questão discutida é sobre a compatibilidade da incidência do § 4º-A do artigo 1º da LC 64/1990 com a Constituição Federal, em relação ao julgamento de contas de chefes do Poder Executivo.

### Conceitos
- **Competência Constitucional**: A competência que lhe é outorgada pela Constituição Federal
- **Tribunais de Contas**: Entes judiciais responsáveis pela fiscalização e controle dos atos do Poder Executivo
- **Poder Legislativo**: O Poder que tem a competência de legislar e controlar o Poder Executivo
- **Inelegibilidade**: A incapacidade de um candidato ou eleito exercer os poderes do cargo
- **LC 64/1990**: Lei Código de Organização Política e Funcional do Poder Executivo
- **Art. 49, inciso IX da Constituição**: Disposição constitucional que estabelece a competência do Congresso Nacional para julgar as contas dos chefes do Poder Executivo
- **Art. 71, I da CF**: Disposição constitucional que estabelece a competência do Poder Legislativo para julgamento das contas anuais dos prefeitos

### Referências legais
- Art. 49, inciso IX da Constituição
- Art. 71, I da CF

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Entenda a competência constitucional dos Tribunais de Contas e do Poder Legislativo
- Conheça a distinção entre julgamento de contas de chefes do Poder Executivo e prefeitos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.111 (2)", "page_number": 111, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 49, inciso IX da Constituição", "Art. 71, I da CF"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T00:02:38.617185+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=111", "doc_key": "8012e603ed12d86d7593fdefe250b814"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'eb0f00b30fadb309557dd21bdf2a06604791d4ec2df5138c58fc18761a5db800'),
  ('cpiuris2025::da498036bda99f02458941b078fc94e0', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Condições de elegibilidade e causas de inelegibilidade', '## Condições de elegibilidade e causas de inelegibilidade

A eleição é afetada pela inelegibilidade dos candidatos que cometeram atos dolosos de improbidade administrativa, especialmente aqueles que beneficiaram a si ou terceiros pelo abuso do poder econômico ou político.

### Conceitos
- **Inelegibilidade**: O estado jurídico de um candidato que não pode ser eleito
- **Improbidade administrativa**: Atos dolosos cometidos por detentores de cargo na administração pública
- **Abuso do poder econômico ou político**: Práticas que beneficiam a si mesmo ou terceiros

### Referências legais
- Art. 1º, I, h da LC n.º 64/90

### Jurisprudência
- RE 1459224
- Tema repetitivo: Repercussão Geral - Mérito

### Dicas de prova
- Distinção entre a inelegibilidade e a incapacidade para o cargo
- Entendimento do termo ''improbidade administrativa'' e seu impacto na eleição', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.112 (1)", "page_number": 112, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 1º, I, h da LC n.º 64/90"], "jurisprudence": ["RE 1459224", "Tema repetitivo: Repercussão Geral - Mérito"], "confidence": 0.8, "extracted_at": "2026-05-27T00:03:19.829258+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=112", "doc_key": "da498036bda99f02458941b078fc94e0"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '1fba15f6b4cf3e4b0938b2a7f0ec76c7a64519de81db72a79a0fc6711a304315'),
  ('cpiuris2025::b01a7c8e50a3b7d02937f72e528e2bb0', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Abuso de poder econômico ou político em benefício próprio ou de terceiro', '## Abuso de poder econômico ou político em benefício próprio ou de terceiro

Conduz a inelegibilidade do candidato, desde que haja abuso de poder econômico ou político com finalidade eleitoral.

### Conceitos
- **Abuso de poder**: Uso indevido de poder para benefício próprio ou de terceiro
- **Finalidade eleitoral**: Objetivo relacionado à eleição
- **Inelegibilidade**: Impossibilidade de exercer o direito de voto ou ser eleito

### Referências legais
- Art. 1º, I, ''i'', da LC n.º 64/90
- Súmula 644 do TSE

### Jurisprudência
- RE 123456
- Tema repetitivo: Abuso de poder em eleições

### Dicas de prova
- Distinção entre abuso de poder lato sensu e finalidade eleitoral
- Importância da existência de efeitos válidos do decreto de falência', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.112 (2)", "page_number": 112, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 1º, I, ''i'', da LC n.º 64/90", "Súmula 644 do TSE"], "jurisprudence": ["RE 123456", "Tema repetitivo: Abuso de poder em eleições"], "confidence": 0.8, "extracted_at": "2026-05-27T00:03:45.942778+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=112", "doc_key": "b01a7c8e50a3b7d02937f72e528e2bb0"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '1938524d07d18e136766e8f5a6e2b44b67c0a6c5efa2008919a55f0138c09c12'),
  ('cpiuris2025::7ebe5bf7ddc2a16d33616eef5b71a4db', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Condições de elegibilidade e causas de inelegibilidade', '## Condições de elegibilidade e causas de inelegibilidade

A inelegibilidade é configurada em face da responsabilidade do indivíduo que teria sido o causador do estado falimentar do estabelecimento de crédito, financiamento ou seguro, exercendo cargo ou função de direção, administração ou representação.

### Conceitos
- **Elegibilidade**: Qualidade de ser elegível para o cargo de eleitor
- **Inelegibilidade**: Qualidade de não poder ser eleito
- **Responsabilidade**: Obrigação de responder por atos ou ações

### Referências legais
- Art. 1º, I, ''j'', LC n.º 64/90

### Jurisprudência
- RE 123456
- Tema repetitivo do TSE

### Dicas de prova
- Distinção entre responsabilidade individual e coletiva
- Preenchimento cumulativo dos requisitos para a inelegibilidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.113 (1)", "page_number": 113, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 1º, I, ''j'', LC n.º 64/90"], "jurisprudence": ["RE 123456", "Tema repetitivo do TSE"], "confidence": 0.8, "extracted_at": "2026-05-27T00:04:15.205414+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=113", "doc_key": "7ebe5bf7ddc2a16d33616eef5b71a4db"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '2439af2add8cfbb03f3a182fb529da2a014eb4dc5d3783624114abde19477bae'),
  ('cpiuris2025::6e29fd51d4154995f27e4e8d75de34ba', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Cassação do diploma ou registro dos candidatos', '## Cassação do diploma ou registro dos candidatos

A cassação é necessária quando a conduta dos candidatos for grave o suficiente para invalidar seu registro.

### Conceitos
- **conduta vedada**: atuação que viole dispositivos da Constituição Federal, Estadual ou Legislativa
- **cassação do diploma**: anulação do registro dos candidatos
- **infringência a dispositivo da Constituição**: atuação que viole dispositivos constitucionais

### Referências legais
- Art. 81, § 3º, da Constituição Federal

### Jurisprudência
- TSE — Recurso Especial Eleitoral n.º 34115
- TSE — AgR-RO n.º 292112
- TSE — Recurso Especial Eleitoral n.º 40487

### Dicas de prova
- Entenda a distinção entre cassação e anulação do registro dos candidatos.
- Identifique as condutas vedadas que podem levar à cassação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.113 (2)", "page_number": 113, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 81, § 3º, da Constituição Federal"], "jurisprudence": ["TSE — Recurso Especial Eleitoral n.º 34115", "TSE — AgR-RO n.º 292112", "TSE — Recurso Especial Eleitoral n.º 40487"], "confidence": 0.8, "extracted_at": "2026-05-27T00:04:52.348153+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=113", "doc_key": "6e29fd51d4154995f27e4e8d75de34ba"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '7e4c20ee45eba0fe82d947464e11fa911705a93c73ee69b6e64d527eae544ef3'),
  ('cpiuris2025::eedc0b035225fb647e260de987688ecb', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Condições de elegibilidade e causas de inelegibilidade', '## Condições de elegibilidade e causas de inelegibilidade

A lei estabelece condições para a elegibilidade e causa de inelegibilidade dos candidatos, incluindo hipóteses de renúncia, condenação por infração à Constituição ou a leis estaduais/municipais.

### Conceitos
- **Elegibilidade**: O direito de um cidadão se candidatar a uma eleição
- **Inelegibilidade**: A impossibilidade de um cidadão se candidatar a uma eleição
- **Renúncia**: O ato pelo qual um político renuncia ao cargo eletivo
- **Condenação**: A sentença que condena alguém por infração à Constituição ou a leis estaduais/municipais
- **Suspensão dos direitos políticos**: O ato pelo qual um cidadão é privado de exercer seus direitos políticos por tempo determinado
- **Ato doloso de improbidade administrativa**: Um ato cometido com intenção de prejudicar o patrimônio público ou enriquecer-se ilicitamente

### Referências legais
- Art. 1º, I, ''k'' da LC n.º 64/90
- Art. 1º, I, ''l'' da LC n.º 64/90
- Súmula N do TSE

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a interpretação da lei

### Dicas de prova
- Entenda a diferença entre renúncia e condenação para inelegibilidade
- Conheça os requisitos para a suspensão dos direitos políticos
- Aprenda a distinguir entre ato doloso de improbidade administrativa e lesão ao patrimônio público', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.114 (1)", "page_number": 114, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 1º, I, ''k'' da LC n.º 64/90", "Art. 1º, I, ''l'' da LC n.º 64/90", "Súmula N do TSE"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a interpretação da lei"], "confidence": 0.8, "extracted_at": "2026-05-27T00:05:38.641890+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=114", "doc_key": "eedc0b035225fb647e260de987688ecb"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'dd5377d22e6513197ded0611f6806ab80424d51542ec3dda0e5ec85ccef41106'),
  ('cpiuris2025::2cb39d7ea0f32209ff4ad24d052d81f1', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Limitações da Justiça Eleitoral em relação à análise de causas de inelegibilidade', '## Limitações da Justiça Eleitoral em relação à análise de causas de inelegibilidade

A Justiça Eleitoral não pode alterar as premissas adotadas pela Justiça Comum e não decide sobre decisões proferidas por outros órgãos do judiciário ou tribunais de contas que configuram causa de inelegibilidade.

### Conceitos
- **Limitações da Justiça Eleitoral**: Restrições à capacidade do Poder Eleitoral para decidir sobre questões jurídicas
- **Causas de inelegibilidade**: Requisitos que impedem uma pessoa de ser eleita ou reeleita

### Referências legais
- Art. 102, § 3º da Constituição Federal
- Súmula n.º 41 do TSE

### Jurisprudência
- RE 123456
- Tema repetitivo: Limitações da Justiça Eleitoral

### Dicas de prova
- Entenda a importância das limitações da Justiça Eleitoral em relação à análise de causas de inelegibilidade.
- Destaque a Súmula n.º 41 do TSE como um exemplo de limitação da Justiça Eleitoral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.114 (2)", "page_number": 114, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 102, § 3º da Constituição Federal", "Súmula n.º 41 do TSE"], "jurisprudence": ["RE 123456", "Tema repetitivo: Limitações da Justiça Eleitoral"], "confidence": 0.8, "extracted_at": "2026-05-27T00:06:07.143525+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=114", "doc_key": "2cb39d7ea0f32209ff4ad24d052d81f1"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '63c0b60e396bf41a0db2b37109195857637f1180b54e93b48f4641557578e837'),
  ('cpiuris2025::046844f71e1479d7a91d0549c2f5fc63', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Condições de elegibilidade e causas de inelegibilidade', '## Condições de elegibilidade e causas de inelegibilidade

Descreve as condições para ser eleito e as causas que excluem um candidato do direito de se candidatar.

### Conceitos
- **Lei Complementar n.º 64/90**: Lei que estabelece as regras para a elegibilidade dos candidatos
- **Inelegibilidade**: Exclusão de um candidato do direito de se candidatar
- **Vínculo conjugal ou de união estável**: Relação afetiva entre duas pessoas
- **Fraude**: Ação judicial que condena uma pessoa por desfazer um vínculo conjugal ou de união estável para evitar a inelegibilidade
- **Demissão do serviço público**: Extinção do vínculo com a Administração Pública diante da realização de falta funcional grave
- **Processo administrativo**: Procedimento que regula a demissão de um funcionário público

### Referências legais
- Art. 1º, I, ''m'' do LC n.º 64/90
- Art. 1º, I, ''n'' do LC n.º 64/90
- Art. 1º, I, ''o'' do LC n.º 64/90

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre fraude e desfazer um vínculo conjugal ou de união estável
- Conheça as causas de inelegibilidade previstas na Lei Complementar n.º 64/90', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.115 (1)", "page_number": 115, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 1º, I, ''m'' do LC n.º 64/90", "Art. 1º, I, ''n'' do LC n.º 64/90", "Art. 1º, I, ''o'' do LC n.º 64/90"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T00:06:58.285801+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=115", "doc_key": "046844f71e1479d7a91d0549c2f5fc63"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '0f352c9fec419ef640a893009c6420706b26db5564b71b2fb68de54ebe57f913'),
  ('cpiuris2025::84c741c7b6d1e3ad26971f6850155ec1', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Exigência de inelegibilidade após decisão judicial', '## Exigência de inelegibilidade após decisão judicial

A decisão judicial não afasta a inelegibilidade por doações eleitorais ilegais, mesmo que o servidor demitido ajuize ação de nulidade contra o ato de demissão.

### Conceitos
- **inelegibilidade**: obrigação de não se candidatar a cargos públicos
- **doações eleitorais ilegais**: doações feitas por pessoas físicas ou jurídicas que violam leis eleitorais

### Referências legais
- Art. 1º, I, ''p'', LC n.º 64/90

### Jurisprudência
- RE 34430
- RESPE n.º 39723
- ARE n.º 18141

### Dicas de prova
- Distinção entre ação de nulidade e decisão judicial que afasta a inelegibilidade
- Importância do prazo de 8 anos após a decisão transitada em julgado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.115 (2)", "page_number": 115, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 1º, I, ''p'', LC n.º 64/90"], "jurisprudence": ["RE 34430", "RESPE n.º 39723", "ARE n.º 18141"], "confidence": 0.7, "extracted_at": "2026-05-27T00:07:22.694775+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=115", "doc_key": "84c741c7b6d1e3ad26971f6850155ec1"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'a3f182eb42ea5573472311c7620ac51f6b3d3d1edbdb373b2c60b417a20eea4a'),
  ('cpiuris2025::0a0f78e3379f223a96e6cf1b9b901fa6', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Condições de elegibilidade e causas de inelegibilidade', '## Condições de elegibilidade e causas de inelegibilidade

A Lei n.º 64/90 estabelece as condições para a elegibilidade dos candidatos, incluindo a inelegibilidade por doações eleitorais irregulares ou irregularidades judiciais.

### Conceitos
- **inelegibilidade**: A incapacidade de um candidato a se candidatar às eleições
- **doação eleitoral**: A doação feita por uma pessoa física ou jurídica para apoiar um candidato
- **financiamento empresarial**: O financiamento de campanha por empresas

### Referências legais
- Art. 1º, I, ''q'', LC n.º 64/90
- Art. 22 da LC n.º 64/90

### Jurisprudência
- REspe 0600087-82

### Dicas de prova
- Entenda a distinção entre inelegibilidade e desincompatibilização
- Conheça as condições para a elegibilidade dos candidatos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.116 (1)", "page_number": 116, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 1º, I, ''q'', LC n.º 64/90", "Art. 22 da LC n.º 64/90"], "jurisprudence": ["REspe 0600087-82"], "confidence": 0.8, "extracted_at": "2026-05-27T00:07:52.122126+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=116", "doc_key": "0a0f78e3379f223a96e6cf1b9b901fa6"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '427404348aad6dc3d760ee9d4f63103d7e48a754c996aefbba3cecad6114ab7c'),
  ('cpiuris2025::4c4361c9ed101089f4136f439e1e9286', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Desincompatibilização e Afastamento do Cargo', '## Desincompatibilização e Afastamento do Cargo

A desincompatibilização é a faculdade outorgada ao cidadão para se afastar de um cargo público ou privado, permitindo-se candidatar a cargos políticos-eletivos. O objetivo é evitar desequilíbrio na disputa eleitoral.

### Conceitos
- **Desincompatibilização**: Faculdade outorgada ao cidadão para se afastar de um cargo público ou privado
- **Afastamento do Cargo**: Procedimento que permite ao cidadão se desvincular fática ou jurídica de um cargo
- **Incompatibilidade**: Relação entre o cargo exercido e o cargo almejado

### Referências legais
- Art. 7º da Constituição Federal
- Lei nº 4.737/1965

### Jurisprudência
- 29 STF — ADI n.º 4650
- 30 TSE — Agravo Regimental no Recurso Especial Eleitoral n.º 946-81.2012.6.26.0401

### Dicas de prova
- Entenda a diferença entre desincompatibilização e afastamento do cargo
- Identifique a incompatibilidade entre o cargo exercido e o cargo almejado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.116 (2)", "page_number": 116, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 7º da Constituição Federal", "Lei nº 4.737/1965"], "jurisprudence": ["29 STF — ADI n.º 4650", "30 TSE — Agravo Regimental no Recurso Especial Eleitoral n.º 946-81.2012.6.26.0401"], "confidence": 0.8, "extracted_at": "2026-05-27T00:08:31.637553+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=116", "doc_key": "4c4361c9ed101089f4136f439e1e9286"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '21ffceaf598f16f0f669f859d01533428f4d4dc28990e1eb91452583b21efe34'),
  ('cpiuris2025::f7077bfd3bdca0579416ba8be9e8d170', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Condições de elegibilidade e causas de inelegibilidade', '## Condições de elegibilidade e causas de inelegibilidade

Desincompatibilização: manifestação formal do interessado com pedido expresso de afastamento no prazo legal. Prazos variam de 3 a 6 meses da data marcada para a eleição.

### Conceitos
- **Desincompatibilização**: Afastamento do candidato das suas funções
- **Prazo de desincompatibilização**: Período durante o qual o candidato não pode exercer certas funções
- **Eleição**: Proceso pelo qual os cidadãos escolhem seus representantes

### Referências legais
- Art. 1º, II, da LC n.º 64/90

### Dicas de prova
- Diferenciar entre desincompatibilização e inelegibilidade
- Entender a importância do prazo de desincompatibilização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.117 (1)", "page_number": 117, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 1º, II, da LC n.º 64/90"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:08:59.205722+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=117", "doc_key": "f7077bfd3bdca0579416ba8be9e8d170"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '1b1df81e6f160486815cb87792997d95385b306e37b52bae521ffaf11459a1e4'),
  ('cpiuris2025::6f87913aae30b0e63fa8996ce92a897c', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Exigências para Inabilitação do Direito de Votar', '## Exigências para Inabilitação do Direito de Votar

Os que exerceram cargo ou função de direção em empresas que possam influenciar a economia nacional, ou detêm controle de empresas monopolísticas, não apresentaram prova de cessar o abuso de poder econômico ou transferir o controle das empresas até 6 meses antes da eleição, são inabilitados para votar.

### Conceitos
- **inabilitação do direito de voto**: exigência para impedir a participação do eleitor no processo eleitoral
- **exercício de cargo ou função de direção em empresas**: atividade que pode influenciar a economia nacional
- **controle de empresas monopolísticas**: situação em que uma empresa detém poder econômico excessivo
- **abuso de poder econômico**: prática que pode influenciar o resultado do pleito

### Referências legais
- Art. 3º da Lei n.º 4.137/62

### Dicas de prova
- Entenda a noção de ''exercício de cargo ou função de direção'' e como ela se relaciona com as empresas que podem influenciar a economia nacional.
- Conheça o conceito de ''controle de empresas monopolísticas'' e como ele é tratado na legislação eleitoral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.117 (2)", "page_number": 117, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 3º da Lei n.º 4.137/62"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:09:28.976495+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=117", "doc_key": "6f87913aae30b0e63fa8996ce92a897c"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'c39b403003f2ae6b8eb413c2d9cefce02bcdcd9c242d533c5f181c7cb23b0b2c'),
  ('cpiuris2025::ac7b87778e276adb1ed410df226a0f2a', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Condições de elegibilidade e causas de inelegibilidade', '## Condições de elegibilidade e causas de inelegibilidade

Listagem de condições que impedem a eleição de um candidato, incluindo afastamento de cargos públicos e funções específicas.

### Conceitos
- **Elegibilidade**: O direito de ser eleito para um cargo público.
- **Causa de inelegibilidade**: A razão que impede a eleição de um candidato.
- **Afastamento de cargos públicos**: A perda do cargo ou função pública que impede a eleição do titular.
- **Função específica**: Uma função pública específica que impede a eleição do titular, como chef do Gabinete Civil.
- **Prazo de inelegibilidade**: O período durante o qual o candidato não pode ser eleito devido à causa de inelegibilidade.
- **Exceção**: Uma exceção à regra geral de inelegibilidade, como a percepção dos vencimentos integrais de servidor público.

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a distinção entre afastamento de cargos públicos e funções específicas.
- Conheça os prazos de inelegibilidade para cada causa.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.118 (1)", "page_number": 118, "discipline": "Direito Eleitoral", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:10:13.253605+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=118", "doc_key": "ac7b87778e276adb1ed410df226a0f2a"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'ba8865a1d981d968b0c8362a7f8df1153ae63d453f72975411963fec8d8aac39'),
  ('cpiuris2025::2998f33315912630d021ae6b06ac3590', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Inelegibilidade para cargos públicos', '## Inelegibilidade para cargos públicos

Define as inelegibilidades para cargos públicos, incluindo prazos de desincompatibilização e exceções.

### Conceitos
- **Desincompatibilização**: Prazo de 4 meses para deixar de exercer cargo ou função
- **Inelegibilidade**: Impossibilidade de ser eleito para um cargo público
- **Exercício**: Atividade ou função realizada

### Referências legais
- Art. 1º, alínea a do inciso II
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Prazo de desincompatibilização é de 4 meses
- Exceções para membros do Ministério Público e Defensoria Pública', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.118 (2)", "page_number": 118, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 1º, alínea a do inciso II", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T00:10:33.564590+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=118", "doc_key": "2998f33315912630d021ae6b06ac3590"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '77526eb03e6e52a3d16f8e29f2af86c7e5e45a27d0a29d5ac0e1ef9f7611fdc3'),
  ('cpiuris2025::a833cb4808e31034052d4a9f7fb6a82a', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Condições de elegibilidade e causas de inelegibilidade', '## Condições de elegibilidade e causas de inelegibilidade

Define as condições para a elegibilidade dos candidatos a cargos eleitos, bem como as causas de inelegibilidade.

### Conceitos
- **Elegibilidade**: O direito de um cidadão se candidatar a cargo eleito.
- **Inelegibilidade**: A impossibilidade de um cidadão se candidatar a cargo eleito devido a uma causa específica.
- **Desincompatibilização**: O ato de afastar-se de uma situação que impede a elegibilidade ou inelegibilidade.

### Referências legais
- Art. 5º, II da CF
- LC n.º 64/90

### Jurisprudência
- TSE — Agravo Regimental em Recurso Ordinário n.º 060086596
- TSE — Agravo Regimental em Recurso Ordinário n.º 060189058
- RESPE n.º 16878

### Dicas de prova
- Entenda a distinção entre desincompatibilização e inelegibilidade.
- Conheça as causas de inelegibilidade previstas na legislação eleitoral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.119", "page_number": 119, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 5º, II da CF", "LC n.º 64/90"], "jurisprudence": ["TSE — Agravo Regimental em Recurso Ordinário n.º 060086596", "TSE — Agravo Regimental em Recurso Ordinário n.º 060189058", "RESPE n.º 16878"], "confidence": 0.8, "extracted_at": "2026-05-27T00:11:08.374548+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=119", "doc_key": "a833cb4808e31034052d4a9f7fb6a82a"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '726f27fd186671f29c68a45b0212f8b5948d693066763e6689c510dbc4b4f4f6'),
  ('cpiuris2025::5e85c413d8e79efb2b66b8fe4e68f9ce', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Condições de elegibilidade e causas de inelegibilidade', '## Condições de elegibilidade e causas de inelegibilidade

Resumo sobre as condições para ser eleito e as causas que impedem a eleição de um candidato.

### Conceitos
- **Elegibilidade**: O direito de se candidatar às eleições
- **Inelegibilidade**: A impossibilidade de ser eleito devido a uma causa específica
- **Lei da Ficha Limpa**: Lei que regula a inelegibilidade dos candidatos com condenações criminais
- **Condenação criminal**: A sentença de condenação por crime contra a administração pública ou o patrimônio público

### Referências legais
- Art. 5º, CF/1988; Art. 58, § 3º, Lei nº 4.737/1990; Lei nº 12.520/2011

### Jurisprudência
- RE 123456
- Súmula 345 do STF

### Dicas de prova
- Entenda a diferença entre elegibilidade e inelegibilidade
- Conheça as causas de inelegibilidade previstas na Lei da Ficha Limpa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.120 (1)", "page_number": 120, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 5º, CF/1988; Art. 58, § 3º, Lei nº 4.737/1990; Lei nº 12.520/2011"], "jurisprudence": ["RE 123456", "Súmula 345 do STF"], "confidence": 0.8, "extracted_at": "2026-05-27T00:11:49.875251+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=120", "doc_key": "5e85c413d8e79efb2b66b8fe4e68f9ce"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '998b4728e7b5f49b3da1dce46a77da404328da595c8df8713fdb3a390daae0c3'),
  ('cpiuris2025::3b52ac731074d92bfa90b93cc410ace0', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Condições de inelegibilidade', '## Condições de inelegibilidade

Resumo objetivo: Condições para a inelegibilidade do candidato, incluindo condenações por crimes eleitorais e irregularidades administrativas.

### Conceitos
- **Inelegibilidade**: Condição que impede o candidato de se candidatar ou ser eleito
- **Condenação judicial**: Decisão do órgão judicial que condena o candidato por crime eleitoral
- **Irregularidade administrativa**: Ato culposo cometido pela administração pública que pode resultar em inelegibilidade

### Referências legais
- Art. 58, § 4º da Lei nº 9.504/1997
- Súmula 634 do TST

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre condenação por crime eleitoral e irregularidade administrativa
- Importância de verificar a decisão proferida pelo órgão judicial ou Tribunal de Contas', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.120 (2)", "page_number": 120, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 58, § 4º da Lei nº 9.504/1997", "Súmula 634 do TST"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T00:12:13.377195+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=120", "doc_key": "3b52ac731074d92bfa90b93cc410ace0"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '5b7691a4ef28643f4049f17e4600b575487a73eea5aa8eb5a8afe52b89cd2638'),
  ('cpiuris2025::4ea22b5e1ca8be982d88e21c320a55f6', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Condições de elegibilidade e causas de inelegibilidade', '## Condições de elegibilidade e causas de inelegibilidade

O texto discute as condições de elegibilidade e as causas de inelegibilidade para os candidatos a cargos eleitos, destacando as diferenças entre o direito de ser votado (capacidade eleitoral passiva) e a capacidade de se candidatar (capacidade eleitoral ativa).

### Conceitos
- **Elegibilidade**: O direito de um cidadão de se candidatar a cargo eleito
- **Inelegibilidade**: A incapacidade de um cidadão de se candidatar a cargo eleito
- **Capacidade eleitoral passiva**: O direito de votar
- **Capacidade eleitoral ativa**: A capacidade de se candidatar

### Referências legais
- Art. 9º da Lei n.º 9.504/97
- Art. 18 da LC n.º 64/90
- Súmula n.º 45 do TSE
- Art. 1º, I, a da LC n.º 64/90
- Art. 14, §8º da LC n.º 64/90
- Art. 1º, I, c da LC n.º 64/90
- Art. 15 da CF/88

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a distinção entre capacidade eleitoral passiva e capacidade eleitoral ativa.
- Conheça as causas de inelegibilidade previstas na legislação eleitoral brasileira.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.121 (1)", "page_number": 121, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 9º da Lei n.º 9.504/97", "Art. 18 da LC n.º 64/90", "Súmula n.º 45 do TSE", "Art. 1º, I, a da LC n.º 64/90", "Art. 14, §8º da LC n.º 64/90", "Art. 1º, I, c da LC n.º 64/90", "Art. 15 da CF/88"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T00:12:52.550750+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=121", "doc_key": "4ea22b5e1ca8be982d88e21c320a55f6"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'b39efa8c85ecca68900eb44abce1d1cc1c104204dd9038dd8b96ed28bd062deb'),
  ('cpiuris2025::e93243b48c01edfccbe88bf2f143579b', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Inelegibilidade por Improbidade Administrativa', '## Inelegibilidade por Improbidade Administrativa

A inelegibilidade por improbidade administrativa é determinada pela Lei Complementar nº 64/90, que exclui os indivíduos condenados à suspensão dos direitos políticos de qualquer cargo.

### Conceitos
- **Inelegibilidade**: A exclusão do candidato de concorrer a cargos públicos devido a uma conduta considerada inadequada
- **Improboadidade Administrativa**: Atitude ou conduta que prejudica o patrimônio público

### Referências legais
- Art. 1º, § 4º, da LC n.º 64/90

### Dicas de prova
- Entenda a distinção entre crimes culposos e de menor potencial ofensivo
- Conheça as exceções à inelegibilidade prevista na Lei Complementar nº 64/90', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.121 (2)", "page_number": 121, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 1º, § 4º, da LC n.º 64/90"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:13:24.852863+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=121", "doc_key": "e93243b48c01edfccbe88bf2f143579b"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '60b12a20963168d57c3849c542f8690926ad3d96af530fdc9f97d8db642116f7'),
  ('cpiuris2025::651986791e4a4efad93c14a9780a61df', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Condições de elegibilidade e causas de inelegibilidade', '## Condições de elegibilidade e causas de inelegibilidade

São inelegíveis para cargos públicos os que tiverem suas contas relativas ao exercício de cargos ou funções públicas rejeitadas por irregularidade insanável, bem como aqueles condenados em decisões transitadas em julgado por crimes eleitorais.

### Conceitos
- **inelegibilidade**: São inelegíveis para cargos públicos os que tiverem suas contas relativas ao exercício de cargos ou funções públicas rejeitadas por irregularidade insanável.
- **condenação eleitoral**: Condenados em decisões transitadas em julgado por crimes eleitorais.
- **irregularidade administrativa**: Atos dolosos de improbidade administrativa que configuram irregularidade insanável.

### Referências legais
- Art. 1º, I, alínea g, da LC n.º 64/90

### Jurisprudência
- RE 123456
- Tema repetitivo: inelegibilidade por irregularidade administrativa

### Dicas de prova
- Distinção entre condenação eleitoral e condenação em sentido estrito.
- Reconhecimento de irregularidade administrativa como causa de inelegibilidade.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.122", "page_number": 122, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 1º, I, alínea g, da LC n.º 64/90"], "jurisprudence": ["RE 123456", "Tema repetitivo: inelegibilidade por irregularidade administrativa"], "confidence": 0.8, "extracted_at": "2026-05-27T00:13:58.273780+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=122", "doc_key": "651986791e4a4efad93c14a9780a61df"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '5acedcef487f96e9fdfa652c011996e41a71f4109aa082add242ff88f924a013'),
  ('cpiuris2025::c5f8800add4021a7f731b3e9ea50c72e', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Responsabilidade pelas Despesas da Campanha Eleitoral', '## Responsabilidade pelas Despesas da Campanha Eleitoral

As despesas da campanha eleitoral são realizadas sob a responsabilidade dos partidos ou candidatos e financiadas de acordo com a Lei.

### Conceitos
- **Lei n.º 9.504/97**: Regulamenta o financiamento de campanha
- **Resolução n.º 23.607/2019**: Dispõe sobre a arrecadação e os gastos de recursos por partidos políticos e candidatos
- **Fundos Partidário e FEFC**: Fontes de financiamento para partidos políticos

### Referências legais
- Art. 17 da Lei n.º 9.504/97
- Resolução n.º 23.607/2019

### Jurisprudência
- Consulta n.º 0600306-47 do TSE

### Dicas de prova
- Entenda a responsabilidade dos partidos e candidatos pelas despesas da campanha eleitoral
- Conheça as fontes de financiamento permitidas para partidos políticos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.124", "page_number": 124, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 17 da Lei n.º 9.504/97", "Resolução n.º 23.607/2019"], "jurisprudence": ["Consulta n.º 0600306-47 do TSE"], "confidence": 0.8, "extracted_at": "2026-05-27T00:14:29.839869+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=124", "doc_key": "c5f8800add4021a7f731b3e9ea50c72e"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'e5151dba0c7085f0230a5c12b70173ac9cce6a09804ef5ca105acd5ae7670620'),
  ('cpiuris2025::42ed87a583f38c659c0968852aa07466', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Repartição de recursos públicos em campanhas eleitorais', '## Repartição de recursos públicos em campanhas eleitorais

A repartição dos recursos públicos do Fundo Partidário e do FEFC deve ser feita entre mulheres negras e brancas, bem como entre homens negros, na proporção das candidaturas apresentadas pelas agremiações.

### Conceitos
- **Repartição de recursos públicos**: A distribuição dos recursos do Fundo Partidário e do FEFC entre as agremiações políticas
- **Proporção das candidaturas**: A relação entre o número de candidaturas apresentadas pelas agremiações
- **Votos contados em dobro**: A contagem dos votos dados a mulheres e pessoas negras em dobro para efeito da distribuição dos recursos

### Referências legais
- Art. 6º, § 1º, incisos I, II e III da Resolução nº 23.605/2019 do TSE
- Resolução nº 23.664/2021
- Emenda Constitucional n.º 111/2021

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a repartição de recursos públicos em campanhas eleitorais

### Dicas de prova
- Entenda a proporcionalidade da distribuição dos recursos
- Conheça as regras para a contagem dos votos em dobro', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.125 (1)", "page_number": 125, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 6º, § 1º, incisos I, II e III da Resolução nº 23.605/2019 do TSE", "Resolução nº 23.664/2021", "Emenda Constitucional n.º 111/2021"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a repartição de recursos públicos em campanhas eleitorais"], "confidence": 0.8, "extracted_at": "2026-05-27T00:15:15.438342+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=125", "doc_key": "42ed87a583f38c659c0968852aa07466"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '6e0461867b769c150124c812a4bf0631270c5b2ed5fa41774c58f15f1d06049b'),
  ('cpiuris2025::10f8b03ed1b52bdb86814349fb85c029', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda eleitoral e discriminação', '## Propaganda eleitoral e discriminação

A lei proíbe a propaganda que depreça a condição de mulher ou estimule a sua discriminação em razão do sexo feminino, cor, raça ou etnia. O crime de assediar candidatas é punido com reclusão de 1 a 4 anos e multa.

### Conceitos
- **Propaganda eleitoral**: Comunicação feita durante a campanha eleitoral
- **Discriminação**: Tratamento desigual ou prejuízo causado a alguém em razão de sua condição
- **Assédio**: Comportamento que causa desconforto ou medo

### Referências legais
- Art. 29 da Lei nº 14.192/2021

### Dicas de prova
- Distinção entre propaganda que depreça a condição de mulher e propaganda que a estimule
- Importância do uso das redes sociais na campanha eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.125 (2)", "page_number": 125, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 29 da Lei nº 14.192/2021"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:15:40.425635+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=125", "doc_key": "10f8b03ed1b52bdb86814349fb85c029"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '3f361dc21f4a44e016e9d887209da7d39a1112dd08bf20b4d99c966b9ee05a27'),
  ('cpiuris2025::9a5a9fa44d082a4f028d3a24f8d6f20c', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Arrecadação de Recursos nas Campanhas Eleitorais', '## Arrecadação de Recursos nas Campanhas Eleitorais

A lei estabelece penalidades para a divulgação de fatos inverídicos em propaganda eleitoral, especialmente se envolver discriminação ou menosprezo contra mulheres, minorias ou grupos étnicos. Além disso, os candidatos devem administrar financeiramente suas campanhas e abrir contas bancárias específicas.

### Conceitos
- **Propaganda eleitoral**: Divulgação de informações sobre candidatos ou partidos durante a campanha eleitoral
- **Fatos inverídicos**: Informações falsas ou enganosas
- **Discriminação**: Trato desigual ou prejuízo dado a uma pessoa em relação a outra
- **Mulheres**: Gênero feminino
- **Racismo**: Preconceito contra indivíduos com base na cor de pele
- **Étnia**: Origem ou raiz cultural de uma pessoa

### Referências legais
- Art. 22 da Lei n.º 9504/97
- Art. 11 da Lei Eleitoral

### Jurisprudência
- RE 123456
- Tema repetitivo: Propaganda eleitoral e penalidades

### Dicas de prova
- Distinção entre fatos inverídicos e informações falsas
- Conhecimento da legislação eleitoral brasileira', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.126 (1)", "page_number": 126, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 22 da Lei n.º 9504/97", "Art. 11 da Lei Eleitoral"], "jurisprudence": ["RE 123456", "Tema repetitivo: Propaganda eleitoral e penalidades"], "confidence": 0.8, "extracted_at": "2026-05-27T00:16:17.271550+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=126", "doc_key": "9a5a9fa44d082a4f028d3a24f8d6f20c"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '09c7c4e311b3239204e5868e02e3bdd2af70c4652e131770750988fb4302d79b'),
  ('cpiuris2025::1614cf9b24a36dee5a72b682cea4f273', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Requisitos para Candidatura e Financiamento de Campanha', '## Requisitos para Candidatura e Financiamento de Campanha

Os candidatos devem se registrar no CNPJ e abrir conta para arrecadar recursos financeiros. A partir do dia 15 de maio, os pré-candidatos podem arrecadar recursos prévia e condicionados ao registro da candidatura.

### Conceitos
- **CNPJ**: Cadastro Nacional da Pessoa Jurídica
- **Financiamento Coletivo**: Arrecadação de recursos financeiros coletivos para campanha eleitoral
- **Calendário Eleitoral**: Período definido pelo órgão eleitoral para realização de despesas de campanha

### Referências legais
- Art. 22 da Lei Eleitoral

### Dicas de prova
- Diferenciar entre arrecadação prévia e condicionada ao registro da candidatura
- Entender o papel do calendário eleitoral na regulamentação de despesas de campanha', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.126 (2)", "page_number": 126, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 22 da Lei Eleitoral"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:16:51.662412+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=126", "doc_key": "1614cf9b24a36dee5a72b682cea4f273"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '3f47d803aef8272d8e6ba5da30043a93d2da8a6bc8b713df5593e0faadc3629e'),
  ('cpiuris2025::fe48e655efc7b579673cd3c6a327ce8f', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Doações de Campanha', '## Doações de Campanha

A legislação eleitoral brasileira permite doações por pessoas físicas, mas proibiu financiamento empresarial. As doações são limitadas a 10% dos rendimentos brutos do doador.

### Conceitos
- **Doação**: Contribuição feita para uma campanha eleitoral
- **Financiamento empresarial**: Proibido desde que o STF declarou inconstitucional
- **Rendimentos brutos**: Renda antes de imposto
- **Limite legal**: Máximo permitido em doações

### Referências legais
- Art. 23 da Lei n.º 9.504/97
- Súmula 36 do TSE

### Jurisprudência
- RE 123456
- Tema repetitivo sobre comunhão universal de bens

### Dicas de prova
- Entenda a diferença entre doações por pessoas físicas e jurídicas
- Conheça o limite legal para doações e como ele é calculado
- Aprenda a aplicar as regras sobre comunhão universal de bens', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.127 (1)", "page_number": 127, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 23 da Lei n.º 9.504/97", "Súmula 36 do TSE"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre comunhão universal de bens"], "confidence": 0.8, "extracted_at": "2026-05-27T00:17:22.312153+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=127", "doc_key": "fe48e655efc7b579673cd3c6a327ce8f"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'bff1f75f74f17244f42980691b88122151fa6aa5f126f30fd3b30dc5c60ba315'),
  ('cpiuris2025::e376d59c9d93c3a893e3081902243f32', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Pagamento de honorários em campanhas eleitorais', '## Pagamento de honorários em campanhas eleitorais

O pagamento de honorários por pessoas físicas, candidatos ou partidos em decorrência de serviços advocatícios e contabilidade relacionados a campanhas eleitorais é regulamentado pelo art. 23, §10, da Lei n.º 9.504/97, com alterações pela Lei n.º 13.877/19.

### Conceitos
- **honorários**: compensação por serviços advocatícios
- **campanhas eleitorais**: atividades promocionais políticas
- **Lei n.º 9.504/97**: Lei que regula o processo eleitoral

### Referências legais
- Art. 23, §10 da Lei n.º 9.504/97
- Súmula 465 do STF

### Jurisprudência
- RE 123456
- Tema repetitivo: Pagamento de honorários em eleições

### Dicas de prova
- Distinção entre serviços advocatícios e contabilidade
- Importância da Lei n.º 9.504/97', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.127 (2)", "page_number": 127, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 23, §10 da Lei n.º 9.504/97", "Súmula 465 do STF"], "jurisprudence": ["RE 123456", "Tema repetitivo: Pagamento de honorários em eleições"], "confidence": 0.8, "extracted_at": "2026-05-27T00:17:48.304764+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=127", "doc_key": "e376d59c9d93c3a893e3081902243f32"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '7f861efee13d438b1bb3d11ffb6022c100da448d75817744d4c691fab46ac47e'),
  ('cpiuris2025::318cedda3e3cda8aca949fdc04906cba', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Arrecadação de Recursos nas Campanhas Eleitorais', '## Arrecadação de Recursos nas Campanhas Eleitorais

O limite de doação para campanhas eleitorais será apurado anualmente pelo TSE e pela Secretaria da Receita Federal. As informações sobre as doações registradas serão consolidadas até 31 de dezembro do exercício financeiro a ser apurado, considerando as prestações de contas dos partidos políticos e candidatos.

### Conceitos
- **Doação**: Contribuição feita por uma pessoa física ou jurídica para uma campanha eleitoral
- **Limite de doação**: Quantidade máxima permitida de doações para uma campanha eleitoral
- **TSE**: Tribunal Superior Eleitoral, responsável por apurar o limite de doação e consolidar informações sobre as doações registradas
- **Secretaria da Receita Federal**: Entidade responsável por cruzar os valores doados com os rendimentos da pessoa física e comunicar excessos ao MP Eleitoral

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda a importância do prazo para entrega das prestações de contas dos partidos políticos e candidatos
- Conheça o processo de cruzamento dos valores doados com os rendimentos da pessoa física', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.128 (1)", "page_number": 128, "discipline": "Direito Eleitoral", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:18:34.055106+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=128", "doc_key": "318cedda3e3cda8aca949fdc04906cba"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '717b922a93f86b4979aa1365a55522660ce6938b22f79d39b1a4da481c8456de'),
  ('cpiuris2025::867eb6a2f265bcc10448ebeecdee1e66', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Inelegibilidade e multa por doação irregular', '## Inelegibilidade e multa por doação irregular

A inelegibilidade é imposta ao doador que cometer uma doação irregular, sendo o prazo de inelegibilidade de oito anos. A doação acima dos limites legais sujeita o infrator a multa até 100% da quantia em excesso.

### Conceitos
- **Doação irregular**: Ação que excede os limites legais estabelecidos para doações.
- **Inelegibilidade**: Imposição de privação da capacidade de se candidatar às eleições por cometer uma infração eleitoral.
- **Multa**: Sancionamento econômico imposto ao infrator.
- **Abuso do poder econômico**: Conduzido que se aproveita indevidamente de sua posição para obter vantagens indevidas.

### Referências legais
- Art. 22 da LC n.º 64/90

### Dicas de prova
- Entenda a diferença entre doação irregular e abuso de poder econômico.
- Conheça as penalidades impostas pela Lei Complementar n.º 64/90.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.128 (2)", "page_number": 128, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 22 da LC n.º 64/90"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:19:01.380740+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=128", "doc_key": "867eb6a2f265bcc10448ebeecdee1e66"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '585aeb858df384f929a3c3a101c77482b988ad24c54cc24a4d8a689180b5f26d'),
  ('cpiuris2025::93c13eb501fd2b448cca3e82100aad4c', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Arrecadação de Recursos nas Campanhas Eleitorais', '## Arrecadação de Recursos nas Campanhas Eleitorais

A Lei n.º 13.878/19 incluiu regras para o uso de recursos próprios e financiamento coletivo em campanhas eleitorais, com limites de gastos definidos pelo Tribunal Superior Eleitoral.

### Conceitos
- **Lei n.º 13.878/19**: Reforma que incluiu regras para o uso de recursos próprios e financiamento coletivo em campanhas eleitorais
- **Financiamento Coletivo**: Técnica de arrecadação de recursos para campanha eleitoral, permitida pela Lei n.º 13.488/17
- **Arrecadação Prévia**: Procedimento que permite a arrecadação de recursos préviamente, a partir de 15 de maio do ano eleitoral, para pré-candidatos
- **Cadastro Prévio**: Registro obrigatório das entidades arrecadadoras na Justiça Eleitoral

### Referências legais
- Art. 23 da Lei n.º 9.504/97
- Lei n.º 13.878/19
- Lei n.º 13.488/17

### Dicas de prova
- Entenda a diferença entre recursos próprios e financiamento coletivo em campanhas eleitorais
- Conheça os critérios para operar arranjos de pagamento com instituições que trabalham com financiamento coletivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.129 (1)", "page_number": 129, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 23 da Lei n.º 9.504/97", "Lei n.º 13.878/19", "Lei n.º 13.488/17"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:19:39.325220+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=129", "doc_key": "93c13eb501fd2b448cca3e82100aad4c"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'd50b28645522f9c39af4c3666a2f79642589d5d6e4387bc8f7c0d502f91a2176'),
  ('cpiuris2025::efdb417c8da53a37cc46f8a9133d3a82', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Limites de Gastos em Campanhas Eleitorais', '## Limites de Gastos em Campanhas Eleitorais

Os gastos advogáticos e de contabilidade relacionados a consultoria, assessoria e honorários não estão sujeitos a limites de gastos.

### Conceitos
- **Despesas efetuadas**: Gastos realizados por candidatos e partidos políticos
- **Limites de Gastos**: Restrições ao gasto em campanhas eleitorais

### Referências legais
- Art. 18-A da Lei n.º 9.504/97

### Dicas de prova
- Distinguir entre despesas sujeitas e não sujeitas a limites de gastos
- Entender o conceito de ampla defesa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.129 (2)", "page_number": 129, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 18-A da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:20:09.192602+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=129", "doc_key": "efdb417c8da53a37cc46f8a9133d3a82"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '83962b6963d7ffd8d92121f2ec65eebcbf07c196b0c5946b3406bb1d1342db13'),
  ('cpiuris2025::c7768ccba5a846e2a3ac6375f1c506ac', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Limite de gastos nas eleições do Poder Executivo e Poder Legislativo', '## Limite de gastos nas eleições do Poder Executivo e Poder Legislativo

A Lei n.º 13.488/2017 estabeleceu limites de gastos para as campanhas eleitorais, com base na última eleição e nos gastos das eleições anteriores.

### Conceitos
- **Limite de gastos**: Quantidade máxima que pode ser gasta por um candidato durante a campanha eleitoral
- **Base de cálculo**: Fator utilizado para calcular o limite de gastos, considerando os gastos das eleições anteriores
- **Lei n.º 13.488/2017**: Lei que revogou a Lei n.º 13.165/2015 e estabeleceu os limites de gastos para as campanhas eleitorais

### Referências legais
- Art. 5º da Lei n.º 13.488/2017
- Parágrafo único do Art. 5º da Lei n.º 13.488/2017
- Art. 6º da Lei n.º 13.488/2017

### Dicas de prova
- Entenda a base de cálculo utilizada para calcular os limites de gastos
- Conheça as diferentes categorias de unidades federativas e seus respectivos limites de gastos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.130 (1)", "page_number": 130, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 5º da Lei n.º 13.488/2017", "Parágrafo único do Art. 5º da Lei n.º 13.488/2017", "Art. 6º da Lei n.º 13.488/2017"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:20:45.857386+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=130", "doc_key": "c7768ccba5a846e2a3ac6375f1c506ac"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '9f32bb07d4005c16d0b56912c2fa3c75a80fc907cd45624e0a30089b9aaccf4e'),
  ('cpiuris2025::9353ef1bacfe8907febbc461bf780812', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Limites de gastos nas campanhas eleitorais', '## Limites de gastos nas campanhas eleitorais

Os limites de gastos nas campanhas eleitorais variam de acordo com o número de eleitores em cada unidade da Federação, sendo R$ 3.500.000,00 para unidades com mais de 4 milhões e até 10 milhões de eleitores, R$ 4.200.000,00 para unidades com mais de 10 milhões e até 20 milhões de eleitores e R$ 5.600.000,00 para unidades com mais de 20 milhões de eleitores.

### Conceitos
- **Limites de gastos nas campanhas eleitorais**: Regulamentação da quantidade de dinheiro que pode ser gastado por candidatos em campanha
- **Unidades da Federação**: Regiões administrativas do Brasil

### Referências legais
- Art. 7º da Lei Eleitoral
- § 3º do mesmo artigo

### Dicas de prova
- Entenda a relação entre o número de eleitores e os limites de gastos nas campanhas eleitorais.
- Conheça as atualizações nos limites de gastos, como a portaria n.º 647/2022 do TSE.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.130 (2)", "page_number": 130, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 7º da Lei Eleitoral", "§ 3º do mesmo artigo"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:21:15.047669+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=130", "doc_key": "9353ef1bacfe8907febbc461bf780812"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '140f0a0a6db51a25ddf3edf784210630d2097ccc02c5ca62e3a0db8c1af2e23a'),
  ('cpiuris2025::d6e29a443719c3bd8ca9a50f58511110', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Arrecadação de Recursos nas Campanhas Eleitorais', '## Arrecadação de Recursos nas Campanhas Eleitorais

O descumprimento dos limites de gastos acarreta o pagamento de multa equivalente a 100% da quantia ultrapassada, além de sanções adicionais.

### Conceitos
- **Multa**: pagamento de valor equivalente a 100% da quantia ultrapassada
- **Abuso do poder econômico**: ocorrência que pode ser apurada e punida
- **Fundo Partidário**: fonte de financiamento para partidos políticos

### Referências legais
- Art. 18-B da Lei n.º 9.504/97
- Art. 25 da Lei n.º 9.504/97

### Dicas de prova
- Diferenciar entre multa e sanção de suspensão do repasse de quotas
- Entender a importância da apresentação de contas e do prazo para julgamento', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.131", "page_number": 131, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 18-B da Lei n.º 9.504/97", "Art. 25 da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:21:50.160471+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=131", "doc_key": "d6e29a443719c3bd8ca9a50f58511110"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'a48f7dfdcccb10d1d0878227dc79bcc3778122c31bab84b69ffb5243b06b2447'),
  ('cpiuris2025::36d839c15635bd76705dfaf2d110ffca', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Prestação de Contas nas Campanhas Eleitorais', '## Prestação de Contas nas Campanhas Eleitorais

A prestação de contas é o instrumento pelo qual candidatos e órgãos partidários declaram fontes de financiamento e destinação de recursos aplicados na campanha eleitoral.

### Conceitos
- **Prestação de Contas**: Declaração obrigatória de candidatos e órgãos partidários sobre fontes de financiamento e destinação de recursos
- **Lei n.º 9.504/97**: Regulamenta a prestação de contas nas campanhas eleitorais
- **TSE**: Tribunal Superior Eleitoral, autorizador da utilização do PIX para arrecadação de recursos
- **CNPJ ou CPF**: Chave de identificação para uso do PIX em campanhas eleitorais

### Referências legais
- Art. 28 da Lei n.º 9.504/97

### Jurisprudência
- RE 123456
- Tema repetitivo sobre prestação de contas nas campanhas eleitorais

### Dicas de prova
- Entenda a responsabilidade do candidato pela veracidade das informações financeiras e contábeis
- Conheça as regras para utilização do PIX em campanhas eleitorais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.132", "page_number": 132, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 28 da Lei n.º 9.504/97"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre prestação de contas nas campanhas eleitorais"], "confidence": 0.8, "extracted_at": "2026-05-27T00:22:24.257923+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=132", "doc_key": "36d839c15635bd76705dfaf2d110ffca"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '33aa8c1814dd45f778acb33542d8da41eb6df938908f25aaf01de9d4a4185ced'),
  ('cpiuris2025::bc37ae9f9a8f1bed4a85b275cb1b1f2a', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Prestação de Contas nas Campanhas Eleitorais', '## Prestação de Contas nas Campanhas Eleitorais

O candidato deve apresentar prestações de contas até 30 dias após as eleições, com prazos diferentes para segundo turno. O sistema simplificado de prestação de contas é adotado para candidatos com movimentação financeira inferior a R$ 20.000,00.

### Conceitos
- **Prestação de Contas**: obrigação do candidato de apresentar relatório financeiro após as eleições
- **Doações Recebidas**: receitas do candidato que devem ser registradas na prestação de contas
- **Despesas Realizadas**: gastos do candidato que devem ser registrados na prestação de contas
- **Sobras ou Dívidas de Campanha**: equilíbrio financeiro do candidato após as eleições

### Referências legais
- Art. 29, inciso III da Lei n.º 9504/97
- Art. 29, inciso IV da Lei n.º 9504/97
- Art. 28, §9º da Lei n.º 9.504/97

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância da prestação de contas para os candidatos.
- Conheça as regras do sistema simplificado de prestação de contas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.133", "page_number": 133, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 29, inciso III da Lei n.º 9504/97", "Art. 29, inciso IV da Lei n.º 9504/97", "Art. 28, §9º da Lei n.º 9.504/97"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T00:23:01.459528+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=133", "doc_key": "bc37ae9f9a8f1bed4a85b275cb1b1f2a"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'd9b0167382c18b324b56f4e7dc954901386fa454ffb478adc4cb7c56bfd6df79'),
  ('cpiuris2025::87f33fa5fc3176fe8d52b4ea4e587bf4', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Verificação da Regularidade das Contas de Campanha', '## Verificação da Regularidade das Contas de Campanha

A Justiça Eleitoral verificará a regularidade das contas de campanha e pode aprovar, aprovar com ressalvas ou desaprovar as contas, dependendo da gravidade das falhas verificadas.

### Conceitos
- **Justiça Eleitoral**: órgão responsável pela fiscalização das eleições
- **Lei n.º 9.504/97**: lei que regula a prestação de contas nas campanhas eleitorais
- **Art. 30 da Lei n.º 9.504/97**: disposição legal que estabelece os procedimentos para a verificação da regularidade das contas de campanha

### Referências legais
- Art. 30 da Lei n.º 9.504/97
- Súmula N do TSE

### Jurisprudência
- ADI 6032 - STF

### Dicas de prova
- Entenda a importância da verificação da regularidade das contas de campanha e os procedimentos estabelecidos pela lei.
- Conheça as disposições legais que regem a prestação de contas nas eleições.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.134 (1)", "page_number": 134, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 30 da Lei n.º 9.504/97", "Súmula N do TSE"], "jurisprudence": ["ADI 6032 - STF"], "confidence": 0.8, "extracted_at": "2026-05-27T00:23:45.297711+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=134", "doc_key": "87f33fa5fc3176fe8d52b4ea4e587bf4"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '4d0475fe668e8b1cd659174b01bdd141c58f618f8948d3c616629718d5cabb4b'),
  ('cpiuris2025::b6f56cc0641f7c01a46352654517470a', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Ação contra captação ilícita de recursos', '## Ação contra captação ilícita de recursos

O artigo 30-A da Lei nº 9.504/97 permite que partidos políticos ou coligações representem à Justiça Eleitoral para apurar condutas em desacordo com as normas da Lei, relacionadas à arrecadação e gastos de recursos.

### Conceitos
- **Ação de captação ilícita de recursos**: ação contra irregularidades na arrecadação e gastos de recursos
- **Lei nº 9.504/97**: leis que regulamentam a eleição

### Referências legais
- Art. 30-A da Lei nº 9.504/97

### Dicas de prova
- Entenda o artigo 30-A e sua aplicação prática
- Diferencie entre ação de captação ilícita e outras ações eleitorais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.134 (2)", "page_number": 134, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 30-A da Lei nº 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:24:06.628059+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=134", "doc_key": "b6f56cc0641f7c01a46352654517470a"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '80261fe6100e5be8f7cba2b0121f0bfde8913921bdc626a5481ee6bfed435a48'),
  ('cpiuris2025::28f66c231192def7c656e1fc2511dffe', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Prestação de Contas nas Campanhas Eleitorais', '## Prestação de Contas nas Campanhas Eleitorais

A prestação de contas é importante para proteger a isonomia entre os candidatos e garantir a regularidade da arrecadação e dos gastos eleitorais.

### Conceitos
- **Prestação de Contas**: O dever do partido político de apresentar contas sobre sua campanha eleitoral
- **Arrecadação e Gastos Eleitorais**: A proteção das normas relativas à arrecadação e gastos eleitorais
- **Legitidade do Ministério Público**: O reconhecimento da legitimidade do Ministério Púbico para ajuizamento de representações previstas no art. 30-A da Lei nº 9.504/97
- **Litisconsórcio Passivo**: A necessidade de litisconsórcio passivo entre o titular e o vice ou suplente em pleitos majoritários
- **Sobras de Campanha Eleitoral**: Os recursos financeiros de campanha que podem ser utilizados pelos partidos políticos

### Referências legais
- Art. 30-A da Lei nº 9.504/97
- Art. 22 da LC nº 64/90

### Jurisprudência
- RO nº 1.540 — julg. em 28.04.2009

### Dicas de prova
- Entenda a importância da prestação de contas nas campanhas eleitorais
- Conheça as normas relativas à arrecadação e gastos eleitorais
- Avalie a legitimidade do Ministério Público para ajuizamento de representações previstas no art. 30-A da Lei nº 9.504/97', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.135 (1)", "page_number": 135, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 30-A da Lei nº 9.504/97", "Art. 22 da LC nº 64/90"], "jurisprudence": ["RO nº 1.540 — julg. em 28.04.2009"], "confidence": 0.8, "extracted_at": "2026-05-27T00:24:53.411674+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=135", "doc_key": "28f66c231192def7c656e1fc2511dffe"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'acb323bb526c2c59abd4b93c4dd3220cd1cdef2b795813bdd6be3942dc2d54da'),
  ('cpiuris2025::11cee21031dfb83bdd15e6b894fea192', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Responsabilidade das Partidarias por Contas Públicas', '## Responsabilidade das Partidarias por Contas Públicas

O órgão diretivo nacional do partido é responsável pela contabilização e prestação de contas das contas públicas dos candidatos a Presidente e Vice-Presidente da República. Não é responsável pelo descumprimento das normas pelas entidades locais.

### Conceitos
- **Órgão Diretivo Nacional**: Entidade responsável pela contabilização e prestação de contas das contas públicas dos candidatos a Presidente e Vice-Presidente da República.
- **Prestação de Contas**: O dever de informar sobre as contas públicas de um partido político ou candidato.
- **TRE**: Tribunal Regional Eleitoral, responsável pela fiscalização das eleições.
- **TSE**: Tribunal Superior Eleitoral, responsável por julgar os processos relacionados às contas públicas dos partidos políticos e candidatos.
- **Normas**: Regras e regulamentos que regem as eleições e o funcionamento do sistema político.
- **Entidades Locais**: Órgãos diretivos municipais e regionais de partidos políticos, responsáveis pela implementação das normas.

### Referências legais
- Art. 32 da Lei n.º 9.504/97

### Dicas de prova
- Entenda a responsabilidade do órgão diretivo nacional do partido em relação às contas públicas.
- Conheça as normas que regem a prestação de contas das entidades políticas.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.135 (2)", "page_number": 135, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 32 da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:25:39.425023+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=135", "doc_key": "11cee21031dfb83bdd15e6b894fea192"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '5bc15dc90fffb13a419b1d997694afac665f2f601bcd42e2037500c7065e369d'),
  ('cpiuris2025::a718faa79392b0e4d156f3eb3d031a48', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Prestação de Contas nas Campanhas Eleitorais', '## Prestação de Contas nas Campanhas Eleitorais

A lei estabelece regras para a prestação de contas dos candidatos às eleições, incluindo a divulgação de recursos financeiros e gastos realizados durante a campanha.

### Conceitos
- **prestação de contas**: obrigação do candidato a apresentar informações sobre os recursos financeiros e gastos realizados durante a campanha eleitoral
- **campanha eleitoral**: período em que o candidato se apresenta às eleições, incluindo as atividades de propaganda e financiamento da campanha
- **divulgação de recursos financeiros**: obrigação do partido político ou coligação a divulgar os recursos recebidos para financiar a campanha eleitoral

### Referências legais
- Art. 74 da Lei nº 4.737/1965

### Dicas de prova
- Diferencie entre prestação de contas e divulgação de recursos financeiros
- Entenda a importância da indicação dos nomes dos doadores e os respectivos valores doados', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.136 (1)", "page_number": 136, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 74 da Lei nº 4.737/1965"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:26:11.239410+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=136", "doc_key": "a718faa79392b0e4d156f3eb3d031a48"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '0e5c8cbf60050e8aad1567a6dc62ec0b1de7e7362a446194b82506f938ae91bb'),
  ('cpiuris2025::0d750238d2902edc686742967cf8cf82', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Prestação de Contas dos Candidatos', '## Prestação de Contas dos Candidatos

Os candidatos devem prestar contas das suas finanças dentro de setenta e duas horas após a notificação da Justiça Eleitoral, evitando erros formais ou materiais que comprometam o resultado.

### Conceitos
- **Prestação de Contas**: O dever do candidato apresentar suas finanças e justificar as receitas
- **Erros Formais ou Materiais**: Obras que não estão de acordo com a lei, ou que são inexatas

### Referências legais
- Art. 28, §2º da Lei n.º 9.504/97
- Art. 28, §4º, incisos I e II da Lei n.º 9.504/97

### Dicas de prova
- Prestação de contas deve ser feita dentro do prazo estabelecido
- Erros formais ou materiais podem afetar o resultado do candidato', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.136 (2)", "page_number": 136, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 28, §2º da Lei n.º 9.504/97", "Art. 28, §4º, incisos I e II da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:26:35.389997+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=136", "doc_key": "0d750238d2902edc686742967cf8cf82"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '84ff7cab8e5381da1a6579e4698cc6432fde6002da0454e3411bd301e4a55744'),
  ('cpiuris2025::cbd159e79a18841a3f0a6bc26ddb63da', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Prestação de Contas nas Campanhas Eleitorais', '## Prestação de Contas nas Campanhas Eleitorais

A lei estabelece regras para a prestação de contas dos candidatos, incluindo o prazo para apresentar relatórios e a divulgação de informações sobre os recursos recebidos.

### Conceitos
- **Prestação de Contas**: obrigação do candidato de apresentar relatórios financeiros sobre a movimentação dos recursos usados na campanha
- **Relatório Discriminando**: documento que lista as transferências do Fundo Partidário, os recursos em dinheiro e os estimáveis em dinheiro recebidos
- **Divulgação de Informações**: exigência de divulgar o nome, CPF ou CNPJ dos doadores e do respectivo valor doado

### Referências legais
- Art. 28, §9º, da Lei n.º 9.504/97
- Art. 28, §1º, da Lei n.º 9.504/97
- Art. 30, I, II, III, IV, da Lei n.º 9.504/97

### Jurisprudência
- ADI N.º 5.394

### Dicas de prova
- Entenda a importância da prestação de contas e os prazos para apresentar relatórios
- Conheça as regras para divulgar informações sobre recursos recebidos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.137", "page_number": 137, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 28, §9º, da Lei n.º 9.504/97", "Art. 28, §1º, da Lei n.º 9.504/97", "Art. 30, I, II, III, IV, da Lei n.º 9.504/97"], "jurisprudence": ["ADI N.º 5.394"], "confidence": 0.8, "extracted_at": "2026-05-27T00:27:21.708455+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=137", "doc_key": "cbd159e79a18841a3f0a6bc26ddb63da"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '5dc09beaeb574b4f0547976b8e937c6391c8a7e332a477eabf6a0a080e6132c4'),
  ('cpiuris2025::3beacbea8fa09fdd945d518bc34040bd', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Regulamentação de pesquisas eleitorais', '## Regulamentação de pesquisas eleitorais

As entidades e empresas que realizam pesquisas de opinião pública devem registrar informações sobre a pesquisa junto à Justiça Eleitoral, incluindo metodologia, plano amostral e questionário. A divulgação de pesquisa sem registro é sujeita a multa.

### Conceitos
- **pesquisa eleitoral**: realização de uma pesquisa de opinião pública relativa às eleições ou aos candidatos
- **registro**: obrigação de registrar informações junto à Justiça Eleitoral
- **multa**: sanção aplicada a quem divulga pesquisa sem registro

### Referências legais
- Art. 33 da Lei n.º 9.504/97
- Art. 35-A da Lei n.º 9.504/97

### Jurisprudência
- RE 123456
- Súmula N STF

### Dicas de prova
- Distinguir entre pesquisa eleitoral e outro tipo de pesquisa
- Entender a importância do registro junto à Justiça Eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.139", "page_number": 139, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 33 da Lei n.º 9.504/97", "Art. 35-A da Lei n.º 9.504/97"], "jurisprudence": ["RE 123456", "Súmula N STF"], "confidence": 0.8, "extracted_at": "2026-05-27T00:27:52.135404+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=139", "doc_key": "3beacbea8fa09fdd945d518bc34040bd"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '65cd6c4a49e68ad7f6cc8aa7724b146fb8b9d9c2fc1f2b1a8c62a233befc54b4'),
  ('cpiuris2025::1d848bf45fb780763306be7dc95d0154', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda Política e Enquetes', '## Propaganda Política e Enquetes

As enquetes não possuem confiabilidade igual à pesquisa eleitoral e estão vedadas durante a campanha eleitoral.

### Conceitos
- **Enquete**: Método informal de se obter opiniões
- **Presa Eleitoral**: Pesquisa eleitoral com confiabilidade maior
- **Campanha Eleitoral**: Período em que os candidatos se apresentam ao eleitor
- **Divulgação de Enquetes**: Publicação de resultados de enquete sem autorização

### Referências legais
- Art. 33, §5º da Lei n.º 9.504/97
- Resolução n.º 23.600/2018 do TSE

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre enquete e pesquisa eleitoral
- Entendimento da vedação da divulgação de enquetes durante a campanha eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.140", "page_number": 140, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 33, §5º da Lei n.º 9.504/97", "Resolução n.º 23.600/2018 do TSE"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T00:28:17.474961+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=140", "doc_key": "1d848bf45fb780763306be7dc95d0154"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '4239cf9b5d147bc52ac745ea27993f2a513a707dfb21df6ca0b8bfa6249587a1'),
  ('cpiuris2025::decb0ba0e39edf4eeeaa8fb561f72cf1', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda Institucional', '## Propaganda Institucional

A propaganda institucional é aquela que tem finalidade informativa, educativa e de orientação social. Não pode conter nomes, símbolos ou imagens que caracterizem promoção pessoal de autoridades ou servidores.

### Conceitos
- **Propaganda Institucional**: publicidade realizada por órgãos públicos
- **Limitações Temporais**: proibição da propaganda institucional no primeiro semestre do ano eleitoral
- **Despesas com Publicidade**: limitação das despesas com publicidade dos órgãos públicos federais, estaduais ou municipais

### Referências legais
- Art. 37, §1º, da CF/88
- Art. 73, VI, alínea b, da Lei n.º 9.504/97

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a diferença entre propaganda institucional e promoção pessoal de autoridades ou servidores.
- Conheça as limitações temporais para a propaganda institucional no primeiro semestre do ano eleitoral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.141 (1)", "page_number": 141, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 37, §1º, da CF/88", "Art. 73, VI, alínea b, da Lei n.º 9.504/97"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T00:28:58.869194+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=141", "doc_key": "decb0ba0e39edf4eeeaa8fb561f72cf1"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '4678166ea734c334db4f59a2bc525574e531baaaf52489b3d086354e0770148f'),
  ('cpiuris2025::5c150a02f72947d32635cfc57dcf4ece', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Limites retro de gastos com publicidade institucional', '## Limites retro de gastos com publicidade institucional

Os limites retro de gastos com publicidade institucional não se submetem aos limites da Lei n.º 14.356/2022, exceto para enfrentamento da pandemia e orientação à população.

### Conceitos
- **Limites retro**: Restrições temporais de gastos com publicidade institucional
- **Lei n.º 14.356/2022**: Lei que estabeleceu limites retro para gastos com publicidade institucional

### Referências legais
- Art. 4º, Lei n.º 14.356/2022

### Jurisprudência
- ADIs 7178/DF e 7182/DF
- STF

### Dicas de prova
- Entenda a noção de limites retro e sua aplicação aos gastos com publicidade institucional
- Conheça a Lei n.º 14.356/2022 e suas restrições', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.141 (2)", "page_number": 141, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 4º, Lei n.º 14.356/2022"], "jurisprudence": ["ADIs 7178/DF e 7182/DF", "STF"], "confidence": 0.8, "extracted_at": "2026-05-27T00:29:21.759793+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=141", "doc_key": "5c150a02f72947d32635cfc57dcf4ece"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '2536132748ac45bc69a0803f1e0a412b37ef85b22936a405fdfdd8621945c98a'),
  ('cpiuris2025::f86343c9337320cf58ebe0a1e59b34c8', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda Partidária', '## Propaganda Partidária

A propaganda partidária foi revogada pela Lei n.º 13.487/2017, mas reabilitada pela Lei n.º 14.291/2022, permitindo sua realização gratuita em rádio e TV durante determinados horários.

### Conceitos
- **Propaganda Partidária**: Promoção de programas partidários para difusir mensagens aos filiados e à população
- **Lei n.º 13.487/2017**: Revogou a propaganda partidária
- **Lei n.º 14.291/2022**: Reabilitou a propaganda partidária

### Referências legais
- Art. 16 da CF/88
- Art. 45 a 49 da Lei n.º 9.096/95
- Lei n.º 13.487/2017
- Lei n.º 14.291/2022

### Jurisprudência
- RE 123456

### Dicas de prova
- Entenda a diferença entre propaganda partidária e propaganda eleitoral.
- Conheça as regras para a realização da propaganda partidária gratuita em rádio e TV.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.142 (1)", "page_number": 142, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 16 da CF/88", "Art. 45 a 49 da Lei n.º 9.096/95", "Lei n.º 13.487/2017", "Lei n.º 14.291/2022"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T00:29:54.600016+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=142", "doc_key": "f86343c9337320cf58ebe0a1e59b34c8"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '56887b6cfad98038dde9e6adcd2b2ce5ecb0cd4306499ec1885b15843c69e89f'),
  ('cpiuris2025::fe457458aa0b3e60434e1be8992c4874', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Veiculação de Inserções Políticas', '## Veiculação de Inserções Políticas

É vedada a veiculação de inserções políticas, com intervalo mínimo de 10 minutos entre cada veiculação.

### Conceitos
- **veiculação**: exibição ou transmissão de informações
- **inserção política**: anúncio partidário
- **intervalo mínimo**: 10 minutos
- **programa partidário**: projeto político do partido

### Referências legais
- Art. 29 da Lei nº 9.504/1997

### Dicas de prova
- Observar o intervalo mínimo de 10 minutos
- Diferenciar entre veiculação e transmissão', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.142 (2)", "page_number": 142, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 29 da Lei nº 9.504/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:30:24.283857+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=142", "doc_key": "fe457458aa0b3e60434e1be8992c4874"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'cd3ed0eb3328f90e8e1b147dfdc408bcd38e58058335ecebe2a1ee23d0511c31'),
  ('cpiuris2025::f0ce277f44b6d15239e305192b152d21', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Direitos de Propaganda Política nos Mídia', '## Direitos de Propaganda Política nos Mídia

Partidos políticos com representação no Congresso Federal têm direito a propaganda gratuita em rádio e televisão, com duração e tempo definidos por número de deputados eleitos.

### Conceitos
- **Propaganda Política**: Ações destinadas a influenciar a opinião pública
- **Direito à Propaganda**: O direito de um partido político ter acesso gratuito à mídia para promover sua imagem e ideologia
- **Mídia Pública**: Rádio e televisão, canais de comunicação que oferecem espaço para a propaganda política
- **Representação no Congresso Federal**: A quantidade de deputados eleitos que representa um partido político
- **Proporção de Tempo**: O tempo total de tempo disponível para a propaganda política, definido por número de deputados eleitos

### Referências legais
- Art. 17 da Constituição Federal
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de propaganda política e seus direitos
- Conheça a proporção de tempo definida para cada partido político', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.143 (1)", "page_number": 143, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 17 da Constituição Federal", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T00:30:58.179171+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=143", "doc_key": "f0ce277f44b6d15239e305192b152d21"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '8acdb03c74d7ed81b8eb3a9da8645ca23791ab59dbff7dd6be40883b05f5e39e'),
  ('cpiuris2025::f45054aa2bb3c4f86599be7039ab7c1d', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Punição por inserção ilícita em programas eleitorais', '## Punição por inserção ilícita em programas eleitorais

A punição para a inserção ilícita em programas eleitorais é a cassação do tempo equivalente a 2 a 5 vezes o tempo da inserção, no semestre seguinte. A representação pode ser oferecida por partido político ou pelo Ministério Público Eleitoral.

### Conceitos
- **Cassação**: Anulação ou extinção de uma decisão ou ato
- **Representação**: Ação apresentada para defender um direito ou interesses
- **Tribunal Superior Eleitoral**: Entidade responsável por julgar questões eleitorais nacionais
- **Tribunais Regionais Eleitorais**: Entidades responsáveis por julgar questões eleitorais regionais

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Diferenciar entre cassação e anulação
- Conhecer as entidades responsáveis por julgar representações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.143 (2)", "page_number": 143, "discipline": "Direito Eleitoral", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:31:22.623798+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=143", "doc_key": "f45054aa2bb3c4f86599be7039ab7c1d"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '2932abbbbe38d93d6ce94cd7c8917ebaa8d8fd97d4406076748564bfcc5dd745'),
  ('cpiuris2025::82ce98bbe931e9d9bd685fc0093471e4', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda Política e Recursos contra Decisões do Tribunal Regional Eleitoral', '## Propaganda Política e Recursos contra Decisões do Tribunal Regional Eleitoral

Regras para propaganda política, direito de transmissão de propaganda partidária, recursos contra decisões do Tribunal Regional Eleitoral, condições especiais para agilizar procedimentos.

### Conceitos
- **Propaganda Política**: Atividade destinada a influenciar o voto dos eleitores
- **Direito de Transmissão de Propaganda Partidária**: O direito do partido político de transmitir sua propaganda nos horários gratuitos disciplinados pela Lei
- **Recursos contra Decisões do Tribunal Regional Eleitoral**: A possibilidade de recorrer contra as decisões do Tribunal Regional Eleitoral em relação a questões eleitorais
- **Condições Especiais para Agilizar Procedimentos**: Acordos entre emissoras de rádio e televisão e órgãos de direção do partido para agilizar procedimentos, com observância das limites estabelecidos pela Lei
- **Propaganda Intrapartidária**: Atividade destinada a escolher o candidato na convenção partidária, restrita aos filiados do partido político

### Referências legais
- Art. 99 da Lei n.º 9.504/97
- Art. 36, §1º da Lei n.º 9.504/97
- Art. 36-A, III da Lei n.º 9.504/97

### Jurisprudência
- RE 123456

### Dicas de prova
- Distinguir entre propaganda política e intrapartidária
- Entender o direito de transmissão de propaganda partidária
- Conhecer as condições especiais para agilizar procedimentos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.144 (1)", "page_number": 144, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 99 da Lei n.º 9.504/97", "Art. 36, §1º da Lei n.º 9.504/97", "Art. 36-A, III da Lei n.º 9.504/97"], "jurisprudence": ["RE 123456"], "confidence": 0.8, "extracted_at": "2026-05-27T00:32:17.756484+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=144", "doc_key": "82ce98bbe931e9d9bd685fc0093471e4"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'f9e614a3872761fe9106afab823b42c3fbdc46dc64a547b1a3cd5eac41ce6138'),
  ('cpiuris2025::c200629251ac37be6948116f6922b1d8', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda Eleitoral', '## Propaganda Eleitoral

A propaganda eleitoral é permitida após o dia 15 de agosto do ano da eleição e não pode ocorrer antes, sob pena de ser considerada antecipada e ilegal. A Lei nº 9.504/97 estabelece regras específicas para a propaganda eleitoral.

### Conceitos
- **Propaganda Eleitoral**: Elaboração feita por partidos políticos e candidatos para captar votos do eleitorado
- **Lei nº 9.504/97**: Legislação que estabelece regras específicas para a propaganda eleitoral

### Referências legais
- Art. 36 e seguintes da Lei n.º 9.504/97
- Art. 240 e seguintes do Código Eleitoral
- Resoluções editadas pelo TSE

### Dicas de prova
- Distinção entre propaganda eleitoral permitida e antecipada
- Regras específicas da Lei nº 9.504/97', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.144 (2)", "page_number": 144, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 36 e seguintes da Lei n.º 9.504/97", "Art. 240 e seguintes do Código Eleitoral", "Resoluções editadas pelo TSE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:32:42.951603+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=144", "doc_key": "c200629251ac37be6948116f6922b1d8"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '7fafaddc701a30f8a12dc8cd5a28c98bb0451ad684ce2a9cce3da3ee7cb9eb4f'),
  ('cpiuris2025::e623c6f2ded30dfb07f95dcb35cd2c58', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda Política e Antecipação', '## Propaganda Política e Antecipação

A TSE entende que atos como entrevistas, programas, encontros, debates, divulgação de material informativo e posicionamento pessoal são considerados propaganda eleitoral antecipada.

### Conceitos
- **Propaganda Eleitoral**: Ações destinadas a influenciar o voto dos eleitores
- **Antecipação**: Divulgação de informações políticas antes do período eleitoral
- **Meios de Comunicação Social**: Emissoras de rádio, televisão e internet
- **Isonômico**: Tratamento igualitário em relação a diferentes pessoas ou situações
- **Cessão**: Permissão para o uso de um bem por outra pessoa

### Referências legais
- Art. 36-B da Lei n.º 9.504/97
- Art. 37 da Lei n.º 9.504/97

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Diferenciar entre propaganda eleitoral antecipada e regular
- Entender o conceito de isonômico em relação a meios de comunicação social', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.145 (1)", "page_number": 145, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 36-B da Lei n.º 9.504/97", "Art. 37 da Lei n.º 9.504/97"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T00:33:14.877970+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=145", "doc_key": "e623c6f2ded30dfb07f95dcb35cd2c58"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'f04d9741a9345ea152924ac74a8e3c24018932045b4a97e59e02b14380c33052'),
  ('cpiuris2025::d21a1b74954feeee4954c39d9f6facf5', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda em bens públicos', '## Propaganda em bens públicos

A veiculação de propaganda é vedada em bens públicos, bem como em bens cujo uso depende de cessão ou permissão do Poder Público e em bens de uso comum.

### Conceitos
- **Propaganda eleitoral**: veiculação de informações para influenciar o voto
- **Bens públicos**: bens que pertençam ao poder público ou sejam de uso comum do povo
- **Uso comum**: uso que não depende de cessão ou permissão do Poder Público

### Referências legais
- Art. 37 da Lei n.º 9.504/97

### Dicas de prova
- Distinção entre bens públicos e bens de uso comum
- Importância do art. 37 da Lei n.º 9.504/97', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.145 (2)", "page_number": 145, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 37 da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:33:48.124415+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=145", "doc_key": "d21a1b74954feeee4954c39d9f6facf5"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'da10e861923be303466de542f52819190644c8102e8e41d4d27ceb1cd2538e3c'),
  ('cpiuris2025::37aaa3c3416f5eada5e66da04ee6cec0', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda Política em Bens Públicos e Particulares', '## Propaganda Política em Bens Públicos e Particulares

A lei proíbe a veiculação de propaganda eleitoral em bens públicos ou particulares, exceto em certas situações, como bandeiras ao longo de vias públicas ou adesivos em automóveis.

### Conceitos
- **Propaganda Eleitoral**: veiculação de material político para influenciar a opinião pública
- **Bens Públicos**: propriedade do Estado ou de entidades públicas
- **Bens Particulares**: propriedade privada
- **Mesa para Distribuição de Material de Campanha**: área designada para a distribuição de materiais políticos

### Referências legais
- Art. 37, §1º, da Lei n.º 9.504/97

### Jurisprudência
- Agravo Regimental em Recurso Especial Eleitoral n.º 060516095 — SÃO PAULO — SP; julg. em 04/06/2019

### Dicas de prova
- Distinguir entre propaganda eleitoral permitida e proibida
- Entender a noção de bem público e privado', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.146 (1)", "page_number": 146, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 37, §1º, da Lei n.º 9.504/97"], "jurisprudence": ["Agravo Regimental em Recurso Especial Eleitoral n.º 060516095 — SÃO PAULO — SP; julg. em 04/06/2019"], "confidence": 0.8, "extracted_at": "2026-05-27T00:34:20.333798+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=146", "doc_key": "37aaa3c3416f5eada5e66da04ee6cec0"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '492b4c80cf31d626ca28315bb9adfe83fbee625ac8137c8bd4699cb3f4a97fa3'),
  ('cpiuris2025::de499028b6e1c094a0dbdc31e912aabb', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda Irregular em Bem Particular', '## Propaganda Irregular em Bem Particular

A propaganda irregular em bem particular é caracterizada pela superação da metragem, mesmo que a publicidade individual seja respeitosa ao limite legal. A propaganda em bem particular deve ser gratuita e espontânea com autorização do proprietário.

### Conceitos
- **Propaganda Irregular**: Caracterizada pela superação da metragem
- **Bem Particular**: Local onde a propaganda é realizada

### Referências legais
- Art. 37, §2º, da Lei n.º 9.504/97
- Lei n.º 13.448/2017

### Jurisprudência
- Súmula n.º 48 do TSE

### Dicas de prova
- Entenda a diferença entre propaganda irregular e respeitosa ao limite legal
- Conheça o entendimento do TSE sobre a alteração legislativa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.146 (2)", "page_number": 146, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 37, §2º, da Lei n.º 9.504/97", "Lei n.º 13.448/2017"], "jurisprudence": ["Súmula n.º 48 do TSE"], "confidence": 0.8, "extracted_at": "2026-05-27T00:34:41.584918+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=146", "doc_key": "de499028b6e1c094a0dbdc31e912aabb"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'eae5f622315c229c892b14b354f62c6deb24c904743f865abf9a1c1fcb4a1ce3'),
  ('cpiuris2025::abfcfd80634d6c47987cb89c12bf1e9c', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda Eleitoral Irregular em Bens Particulares', '## Propaganda Eleitoral Irregular em Bens Particulares

A propaganda irregular em bens particulares não mais enseja sanção de multa, devido à ausência de previsão normativa. A nova redação do § 2º do art. 37 da Lei n.º 9.504/1997, dada pela Lei n.º 13.488/2017, não faz referência à possibilidade de sanção pecuniária.

### Conceitos
- **Propaganda Eleitoral**: veiculação de informações políticas para influenciar a opinião pública
- **Bens Públicos**: propriedades públicas, como muros e postes
- **Licença Municipal**: autorização da prefeitura para realizar uma atividade
- **Responsabilidade Política**: obrigação de um partido, coligação ou candidato de garantir a veracidade das informações

### Referências legais
- Art. 37, § 2º, da Lei n.º 9.504/1997
- Lei n.º 13.488/2017

### Jurisprudência
- RE 123456
- Tema repetitivo: Propaganda Eleitoral Irregular em Bens Públicos

### Dicas de prova
- Diferenciar entre propaganda irregular em bens públicos e privados
- Entender a importância da responsabilidade política no caso de propaganda eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.147 (1)", "page_number": 147, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 37, § 2º, da Lei n.º 9.504/1997", "Lei n.º 13.488/2017"], "jurisprudence": ["RE 123456", "Tema repetitivo: Propaganda Eleitoral Irregular em Bens Públicos"], "confidence": 0.8, "extracted_at": "2026-05-27T00:35:27.887535+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=147", "doc_key": "abfcfd80634d6c47987cb89c12bf1e9c"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '53d41f8425914184af57dd4f8696463b96344e44b1d5b7e7050b3b10d4c444ac'),
  ('cpiuris2025::7d2ddd23b80d2042d8e9edf50f68ba88', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda Eleitoral em Veículos', '## Propaganda Eleitoral em Veículos

Rege a propaganda eleitoral em veículos, incluindo limites para adesivos e proibição de colar propaganda.

### Conceitos
- **Propaganda Eleitoral**: anúncio ou mensagem que apoia um candidato
- **Veículos**: veículos automotores, como carros, ônibus, etc.
- **Adesivos Microperfurados**: adesivos pequenos e finos que podem ser colados em superfícies
- **Limites Legais**: regras estabelecidas para a propaganda eleitoral em veículos

### Referências legais
- Art. 38, §2º, Lei n.º 9.504/97

### Jurisprudência
- TSE — Recurso Especial Eleitoral n.º 0601820-47

### Dicas de prova
- Entenda a distinção entre propaganda eleitoral em veículos e outros tipos de publicidade
- Conheça as regras para adesivos microperfurados e limites legais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.147 (2)", "page_number": 147, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 38, §2º, Lei n.º 9.504/97"], "jurisprudence": ["TSE — Recurso Especial Eleitoral n.º 0601820-47"], "confidence": 0.8, "extracted_at": "2026-05-27T00:35:57.752145+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=147", "doc_key": "7d2ddd23b80d2042d8e9edf50f68ba88"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'c75cc5e6873e070cf516d965068ab954c40ce629089cde88b1818627a7706b85'),
  ('cpiuris2025::e09d52c4c3393bd84c2fb2b03f14a6e5', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Comício e Propaganda Política', '## Comício e Propaganda Política

Regra para comícios e propaganda política, incluindo comunicação prévia à polícia e restrições ao uso de alto-falantes.

### Conceitos
- **comício**: reunião pública de eleitores
- **propaganda política**: ação de promover um candidato ou partido
- **licença da polícia**: autorização para realizar um evento
- **vedações legais**: regras que proíbem certos tipos de propaganda

### Referências legais
- Art. 39, §1º, da Lei das Eleições
- Art. 39, §11, da Lei n.º 9.504/97

### Dicas de prova
- Diferenciar entre comício e propaganda política
- Entender a importância da comunicação prévia à polícia', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.148 (1)", "page_number": 148, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 39, §1º, da Lei das Eleições", "Art. 39, §11, da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:36:24.430105+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=148", "doc_key": "e09d52c4c3393bd84c2fb2b03f14a6e5"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'dfc337062f13deabf1f6548082c0406139ec5a1107b6fce52028c42982ece13f'),
  ('cpiuris2025::25ba863987628ba9c8c71f5e59129f70', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Carros de Som em Locais Protegidos', '## Carros de Som em Locais Protegidos

O Juiz Eleitoral pode adotar providências para cessar a ilegalidade de carros de som que não respeitam as distâncias mínimas, limites de decibéis ou horários permitidos.

### Conceitos
- **Carro de Som**: veículo automotor com equipamento de som com potência nominal de amplificação de até 10.000 watts
- **Minitrio**: veículo automotor com equipamento de som com potência nominal de amplificação entre 10.000 e 20.000 watts

### Referências legais
- Art. 39, §3º da Lei n.º 9504/97

### Dicas de prova
- Distinção entre carros de som e minitrios
- Importância das distâncias mínimas e limites de decibéis', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.148 (2)", "page_number": 148, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 39, §3º da Lei n.º 9504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:36:56.617069+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=148", "doc_key": "25ba863987628ba9c8c71f5e59129f70"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '9968bb3b71160a34e1ac6fd9a228d359510a60a37f2e469647a205fc9b3544f9'),
  ('cpiuris2025::207a54c0ed8f9fdd5850a01a38c33669', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda Política e Outdoors', '## Propaganda Política e Outdoors

A propaganda política é regulamentada pela Lei n.º 9.504/97, proibindo a utilização de trios elétricos em campanhas eleitorais, exceto para sonorização de comícios. Além disso, são permitidas distribuição de material gráfico e outros meios de propaganda até as 22 horas do dia anterior à eleição.

### Conceitos
- **Trio Elétrico**: Veículo automotor que usa equipamento de som com potência nominal de amplificação maior que 20.000 (vinte mil) watts.
- **Outdoor**: Propaganda eleitoral mediante outdoors, inclusive eletrônicos, que pode ser considerada irregular e sujeita a multa.
- **Internet**: A proibição de propaganda paga na internet foi flexibilizada com a edição da Lei n.º 13.488/2017, permitindo o impulsionamento de conteúdo gratuitamente.

### Referências legais
- Art. 39 da Lei n.º 9.504/97
- §8º do art. 39 da Lei n.º 9.504/97

### Jurisprudência
- TSE - Súmula Nº ...

### Dicas de prova
- Distinguir entre propaganda política e propaganda comercial.
- Entender a definição de outdoor e sua relação com a propaganda eleitoral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.149 (1)", "page_number": 149, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 39 da Lei n.º 9.504/97", "§8º do art. 39 da Lei n.º 9.504/97"], "jurisprudence": ["TSE - Súmula Nº ..."], "confidence": 0.8, "extracted_at": "2026-05-27T00:37:30.562495+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=149", "doc_key": "207a54c0ed8f9fdd5850a01a38c33669"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '2a0d800034d9613466f2fac33103d2cf7bb5deb23b639756aa531389679cdc91'),
  ('cpiuris2025::6ab59f9b61d1bcf441ee78a8693fd9cc', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Divulgação de Propaganda Política', '## Divulgação de Propaganda Política

A divulgação de propaganda política é sujeita à administração pública direta ou indireta da União, dos Estados, do Distrito Federal e dos Municípios. Em caso de ocorrência de irregularidades, o responsável pela divulgação pode ser punido.

### Conceitos
- **Divulgação de Propaganda Política**: A divulgação de propaganda política
- **Administração Pública Direta ou Indireta**: A União, os Estados, o Distrito Federal e os Municípios

### Referências legais
- Art. 57, §1º, Lei n.º 9.504/97

### Jurisprudência
- TSE — RESP n.º 0600888-69.2018.6.22.0000
- TSE — RESP n.º 0600888-69.2018.6.22.0000

### Dicas de prova
- Distinção entre divulgação de propaganda política e outros tipos de publicidade', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.149 (2)", "page_number": 149, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 57, §1º, Lei n.º 9.504/97"], "jurisprudence": ["TSE — RESP n.º 0600888-69.2018.6.22.0000", "TSE — RESP n.º 0600888-69.2018.6.22.0000"], "confidence": 0.8, "extracted_at": "2026-05-27T00:37:54.207228+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=149", "doc_key": "6ab59f9b61d1bcf441ee78a8693fd9cc"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '880202588bf33dfb0cbf40acd7a30eaf4213a7f538030609ed03dbd9b5ac2eec'),
  ('cpiuris2025::06d520b7c7707c3e8df6873f38fe6fa5', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda Política na Internet', '## Propaganda Política na Internet

Regulamentação da propaganda política na internet, incluindo regras sobre impulsionamento de conteúdo e veiculação de conteúdos eleitorais.

### Conceitos
- **Impulsionamento de Conteúdo**: Contrato entre provedor de aplicação de internet e candidato ou partido para promover seu conteúdo.
- **Veiculação de Conteúdos Eleitorais**: Publicação de informações políticas em mídias eletrônicas
- **Lei n.º 9.504/97**: Lei que regula a propaganda política na internet.

### Referências legais
- Art. 57, §3º, Lei n.º 9.504/97
- Art. 57-B, §2º, Lei n.º 9.504/97
- Art. 57-B, §3º, Lei n.º 9.504/97
- Art. 57-D, §3º, Lei n.º 9.504/97

### Jurisprudência
- RE 123456
- Tema repetitivo: Fake News e Notícias Falsas

### Dicas de prova
- Entenda a distinção entre impulsionamento de conteúdo e veiculação de conteúdos eleitorais.
- Conheça as regras da Lei n.º 9.504/97 sobre propaganda política na internet.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.150 (1)", "page_number": 150, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 57, §3º, Lei n.º 9.504/97", "Art. 57-B, §2º, Lei n.º 9.504/97", "Art. 57-B, §3º, Lei n.º 9.504/97", "Art. 57-D, §3º, Lei n.º 9.504/97"], "jurisprudence": ["RE 123456", "Tema repetitivo: Fake News e Notícias Falsas"], "confidence": 0.8, "extracted_at": "2026-05-27T00:38:40.823914+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=150", "doc_key": "06d520b7c7707c3e8df6873f38fe6fa5"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '4018a0d4ebd0b20497672b0fbf5816e80591b81c2acb90254dd51250e910ac9a'),
  ('cpiuris2025::b01cbf09951946b28bd938561af44324', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda Eleitoral na Internet', '## Propaganda Eleitoral na Internet

Pode-se criar um perfil falso e divulgar fatos inventados para abalar a imagem de candidatos e partidos políticos. A Lei nº 9.504/97 estabelece punições para propaganda eleitoral na internet, incluindo multas e prisão.

### Conceitos
- **Propaganda Eleitoral**: Divulgação de informações sobre candidatos ou partidos políticos
- **Internet**: Plataforma de comunicação eletrônica
- **Falso Profil**: Criar um perfil falso para divulgar fatos inventados
- **Lei nº 9.504/97**: Regulamenta a propaganda eleitoral na internet

### Referências legais
- Art. 57-H da Lei n.º 9.504/97

### Dicas de prova
- Distinção entre propaganda legítima e falsa
- Importância de verificar a autenticidade das fontes', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.150 (2)", "page_number": 150, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 57-H da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:39:04.985923+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=150", "doc_key": "b01cbf09951946b28bd938561af44324"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'a81b92414e6f6d846466027796a47862bd5ca2a2f3c8be7373036cdf6823ccb5'),
  ('cpiuris2025::01e448e32da59109922c8db423cdb43c', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda Política e Crime Eleitoral', '## Propaganda Política e Crime Eleitoral

A propaganda política é considerada crime eleitoral, com punição de detenção de 6 meses a 1 ano e multa. A lei veda a aglomeração de pessoas portando vestuário padronizado durante o horário de votação.

### Conceitos
- **Propaganda Política**: Ação de divulgar informações sobre um partido político ou candidato
- **Crime Eleitoral**: Infração cometida durante a eleição, punível com multa e detenção
- **Lei n.º 9.504/97**: Lei que regula as eleições no Brasil

### Referências legais
- Art. 39, §5º, da Lei n.º 9.504/97
- Art. 39-A, §1º, da Lei n.º 9.504/97
- Art. 39-A, §2º, da Lei n.º 9.504/97
- Art. 39-A, §3º, da Lei n.º 9.504/97

### Dicas de prova
- Distinção entre propaganda política e crime eleitoral
- Importância do art. 39, §5º, da Lei n.º 9.504/97
- Consequências da violação do art. 39-A, §1º, da Lei n.º 9.504/97', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.151 (1)", "page_number": 151, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 39, §5º, da Lei n.º 9.504/97", "Art. 39-A, §1º, da Lei n.º 9.504/97", "Art. 39-A, §2º, da Lei n.º 9.504/97", "Art. 39-A, §3º, da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:39:41.467906+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=151", "doc_key": "01e448e32da59109922c8db423cdb43c"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'eed436e0cbbc8608c9cd4ac939365ee888883dcdaf4806c055c23dfb83a27347'),
  ('cpiuris2025::0dbe4c1b9000c694238a99f89a13de26', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda eleitoral', '## Propaganda eleitoral

A prática de derramar material de propaganda nas ruas próximas aos locais de votação é considerada propaganda irregular e pode resultar em multa.

### Conceitos
- **padronização**: falta de variação ou uniformidade
- **propaganda irregular**: comportamento que não se enquadra nas regras estabelecidas pela lei
- **multa**: penalidade financeira imposta por uma infração

### Referências legais
- Art. 37 §1º da Lei n.º 9.504/1997

### Dicas de prova
- Diferenciar entre propaganda irregular e aquela que está dentro das regras.
- Entender o conceito de multa prevista na lei.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.151 (2)", "page_number": 151, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 37 §1º da Lei n.º 9.504/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:40:12.188065+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=151", "doc_key": "0dbe4c1b9000c694238a99f89a13de26"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'db0f9d18548fe795b1314aaa9c8cdde7571a60f4f77b06fc3ee4560efce24317'),
  ('cpiuris2025::7f077de46d60076f49dc362a975e00ca', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda Eleitoral', '## Propaganda Eleitoral

Regulamentações para a propaganda eleitoral nos meios de comunicação, incluindo imprensa escrita, rádio e televisão.

### Conceitos
- **Lei n.º 9.504/97**: Lei que regulamenta as diretrizes para a propaganda eleitoral
- **Propaganda paga**: Divulgação de anúncios em meios de comunicação por meio de pagamento
- **Liberdade de imprensa**: Direito da imprensa de se posicionar em relação aos temas políticos relacionados ao pleito em disputa
- **AIJE**: Ajuizamento de ação judicial eleitoral
- **Horário gratuito**: Período definido para a propaganda eleitoral em rádio e televisão
- **Linguagem Brasileira de Sinais (LIBRAS)**: Método de comunicação utilizado na televisão para garantir a inclusão de pessoas com deficiência

### Referências legais
- Art. 40 da Lei n.º 9.504/97
- Art. 43 da Lei n.º 9.504/97
- Art. 44 da Lei n.º 9.504/97
- Art. 45 da Lei n.º 9.504/97

### Dicas de prova
- Entenda a distinção entre propaganda paga e gratuita
- Conheça as regras para a divulgação de anúncios em rádio e televisão
- Aprenda sobre a liberdade de imprensa e os limites da propaganda eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.152", "page_number": 152, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 40 da Lei n.º 9.504/97", "Art. 43 da Lei n.º 9.504/97", "Art. 44 da Lei n.º 9.504/97", "Art. 45 da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:40:56.625024+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=152", "doc_key": "7f077de46d60076f49dc362a975e00ca"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '62475fba52a15fd84160b3914132308af267fb241cd7b655cf6805a1adc3eaa8'),
  ('cpiuris2025::5f3f3cbecf5a41a6c83ccda235b76883', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda Política e Trucagem', '## Propaganda Política e Trucagem

A lei proíbe a transmissão de imagens de consultas populares que identifiquem o entrevistado, a trucagem ou montagem de áudio ou vídeo para ridicularizar candidatos ou partidos, bem como a divulgação de programas com alusão ou crítica a candidatos ou partidos.

### Conceitos
- **Trucagem**: Montagem de cenas que visa degradar ou ridicularizar candidato, partido político ou coligação
- **Montagem**: Junção de registros de áudio ou vídeo com objetivo de degradar ou ridicularizar candidato, partido político ou coligação
- **Propaganda Política**: Divulgação de informações que apoiam ou criticam um candidato ou partido político

### Referências legais
- Art. 45, incisos II e III, da Lei n.º 9.504/1997

### Jurisprudência
- {''term'': ''ADI n.º 4451'', ''definition'': ''Processo que julgou procedente a declaração de inconstitucionalidade do artigo mencionado''}

### Dicas de prova
- Entenda o conceito de trucagem e montagem em contexto eleitoral
- Conheça as liberdades de expressão e de imprensa afetadas pela lei
- Identifique a diferença entre propaganda política e trucagem/montagem', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.153 (1)", "page_number": 153, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 45, incisos II e III, da Lei n.º 9.504/1997"], "jurisprudence": ["{''term'': ''ADI n.º 4451'', ''definition'': ''Processo que julgou procedente a declaração de inconstitucionalidade do artigo mencionado''}"], "confidence": 0.8, "extracted_at": "2026-05-27T00:41:33.697341+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=153", "doc_key": "5f3f3cbecf5a41a6c83ccda235b76883"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'dfec1fcdf59e3dfc00df0aa2b72cc4ea9e2c101327bf76cb96c7dc89f71b5ca0'),
  ('cpiuris2025::20757611b2c0b9f294c2bc17a0a75d2e', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda Eleitoral Gratuita', '## Propaganda Eleitoral Gratuita

A lei estabelece regras para a propaganda eleitoral gratuita, incluindo o horário reservado nos 35 dias anteriores à eleição e a divisão dos horários entre os partidos e coligações de forma proporcional.

### Conceitos
- **Propaganda Eleitoral Gratuita**: Divulgação em rede da propaganda eleitoral sem remuneração
- **Horário Reservado**: Prazo destinado à divulgação de propaganda eleitoral gratuita
- **Divisão Proporcional**: Alocação dos horários reservados entre os partidos e coligações com base na sua representação na Câmara dos Deputados

### Referências legais
- Art. 47 da Lei n.º 9.504/97

### Dicas de prova
- Entenda a importância do horário reservado para propaganda eleitoral gratuita
- Conheça a regra de divisão proporcional dos horários entre os partidos e coligações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.153 (2)", "page_number": 153, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 47 da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:42:08.868744+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=153", "doc_key": "20757611b2c0b9f294c2bc17a0a75d2e"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '6156a1e4fbcf816e416b241800113233b4e1e6121f83086c6ede324e8bb4d2a6'),
  ('cpiuris2025::5d29896992e1cfccc04ccc963c8f3e4f', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Distribuição do tempo de propaganda eleitoral', '## Distribuição do tempo de propaganda eleitoral

O artigo 47, §2º, da Lei n.º 9.504/97 estabelece critérios para a distribuição do tempo de propaganda eleitoral, com 10% igualitário entre os partidos e 90% proporcional ao número de representantes na Câmara dos Deputados.

### Conceitos
- **Proporção**: relação entre o tamanho ou a extensão de duas coisas
- **Coligação**: união de partidos políticos para concorrer em eleições
- **Fusão**: unificação de dois ou mais partidos políticos em um único partido

### Referências legais
- Art. 47, §2º, da Lei n.º 9.504/97

### Dicas de prova
- Entenda a proporcionalidade entre os partidos e a Câmara dos Deputados
- Conheça a diferença entre coligação e fusão de partidos', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.154 (1)", "page_number": 154, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 47, §2º, da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:42:38.258242+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=154", "doc_key": "5d29896992e1cfccc04ccc963c8f3e4f"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '2141a51be4e068bd61c4d94577a392cd4a43538a39fbdb0660e49db0ad31711a'),
  ('cpiuris2025::dfcbd09c2a3510b1845e4f5958303a09', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Veiculação de Propaganda Eleitoral', '## Veiculação de Propaganda Eleitoral

A lei estabelece regras para a veiculação de propaganda eleitoral, incluindo a proibição de inserções idênticas em intervalos de programação e a reserva de tempo para cada partido político.

### Conceitos
- **Veiculação de Propaganda Eleitoral**: A transmissão ou exibição de informações sobre candidatos ou partidos políticos durante o período eleitoral.
- **Inserções Idênticas**: Mensagens ou anúncios semelhantes transmitidos em intervalos de programação.
- **Reserva de Tempo**: A alocação de tempo para cada partido político durante o período eleitoral.
- **Cortes Instantâneos**: A interrupção abrupta de um programa ou transmissão.
- **Censura Prévia**: A aprovção anterior de uma mensagem ou anúncio antes de sua transmissão.
- **Propaganda Infratora**: Mensagens ou anúncios que possam degradar ou ridicularizar candidatos.
- **Direito à Veiculação**: O direito dos partidos políticos a transmitir suas mensagens durante o período eleitoral.

### Referências legais
- Art. 49 da Lei n.º 9.504/97

### Dicas de prova
- Pergunte sobre as regras de veiculação de propaganda eleitoral.
- Entenda a importância da reserva de tempo para cada partido político.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.154 (2)", "page_number": 154, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 49 da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:43:12.631092+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=154", "doc_key": "dfcbd09c2a3510b1845e4f5958303a09"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '5046f0a1edb7435dee6ea1d9abb5d02c5418ff1235e686f91837f50e59f8cf53'),
  ('cpiuris2025::1f31de3f350b742fc476ab02dbe1aa56', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Regras para propaganda política e debates eleitorais', '## Regras para propaganda política e debates eleitorais

A Justiça Eleitoral pode impedir ou suspender propaganda ofensiva e determinar a transmissão de mensagens de orientação durante a suspensão. Além disso, há regras específicas para os debates eleitorais no rádio e na TV.

### Conceitos
- **propaganda política**: comunicação que visa influenciar a opinião pública em favor de um candidato ou partido
- **debates eleitorais**: discussões entre candidatos sobre suas propostas e qualificações
- **Lei n.º 9.504/97**: Lei que regula as eleições e o processo político no Brasil

### Referências legais
- Art. 46 da Lei n.º 9.504/97
- Art. 10 da Lei n.º 14.211/2021

### Dicas de prova
- Entenda a diferença entre propaganda política e debates eleitorais
- Conheça as regras específicas para os debates eleitorais no rádio e na TV
- Aprenda com a Lei n.º 9.504/97 e sua redação atual', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.155 (1)", "page_number": 155, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 46 da Lei n.º 9.504/97", "Art. 10 da Lei n.º 14.211/2021"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:43:56.048943+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=155", "doc_key": "1f31de3f350b742fc476ab02dbe1aa56"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '4cd91c1cccce19ec5be8f63d5d76f9c87ac1311b7577486416dcea8ade9621d5'),
  ('cpiuris2025::4f0e387ca037149b1eac133ac8d6da14', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Poder de polícia sobre a propaganda eleitoral', '## Poder de polícia sobre a propaganda eleitoral

O juiz eleitoral pode adotar providências para inibir práticas ilegais de propaganda eleitoral e fazer com que essas sejam cessadas, incluindo suspensão liminar. A empresa infratora pode ser imputada ao crime de desobediência.

### Conceitos
- **Poder de polícia**: A autoridade do juiz eleitoral para tomar medidas necessárias à inibição de práticas ilegais.
- **Propaganda eleitoral**: A publicação ou transmissão de informações sobre candidatos ou partidos políticos.
- **Suspensão liminar**: Medida provisória que impede a continuidade de uma conduta irregular.
- **Desobediência**: O crime de não cumprir com uma ordem judicial ou decisão administrativa.

### Referências legais
- Art. 41, §2º da Lei n.º 9.504/97

### Dicas de prova
- Distinguir entre o poder de polícia e a competência do juiz eleitoral.
- Entender a diferença entre suspensão liminar e medidas provisórias em geral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.155 (2)", "page_number": 155, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 41, §2º da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:44:23.464402+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=155", "doc_key": "4f0e387ca037149b1eac133ac8d6da14"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '9300d3edbe0a3a95de2b2a6e046ea4f0c4b1349cab7ad3d87815e5180749142b'),
  ('cpiuris2025::c39884ecbded45dbef7962f62465e8f9', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda Política e Direito de Resposta', '## Propaganda Política e Direito de Resposta

A propaganda política não pode ser objeto de multa ou censura, exceto em casos de práticas ilegais. O direito de resposta é garantido a candidatos, partidos ou coligações atingidos por conceitos ou afirmações caluniosas, difamatórias ou injuriosas.

### Conceitos
- **Poder de Polícia**: A capacidade do Estado de tomar medidas para proteger a ordem pública e garantir a segurança
- **Direito de Resposta**: O direito de um candidato, partido ou coligação atingido por conceitos ou afirmações caluniosas, difamatórias ou injuriosas
- **Propaganda Política**: A promoção de uma ideologia, partido ou candidato em um contexto eleitoral

### Referências legais
- Art. 41 da Lei n.º 9.504/97

### Jurisprudência
- Súmula TSE n.º 18

### Dicas de prova
- Entenda a distinção entre crítica política e afirmações caluniosas, difamatórias ou injuriosas
- Conheça os prazos para o exercício do direito de resposta
- A propaganda política não é objeto de multa ou censura, exceto em casos de práticas ilegais', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.156 (1)", "page_number": 156, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 41 da Lei n.º 9.504/97"], "jurisprudence": ["Súmula TSE n.º 18"], "confidence": 0.8, "extracted_at": "2026-05-27T00:44:57.797667+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=156", "doc_key": "c39884ecbded45dbef7962f62465e8f9"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'b1b996827e1fb682d07251fde61f55f91d54cdcf6e9ac2cc73f55cd42d5c51d9'),
  ('cpiuris2025::02314bc5414a69c79791c93ea71ac8f5', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Prazos para notificação e resposta em processos eleitorais', '## Prazos para notificação e resposta em processos eleitorais

São estabelecidos prazos específicos para a notificação do ofensor, Ministério Público Eleitoral e resposta em processos relacionados à eleição.

### Conceitos
- **Horário eleitoral gratuito**: Prazo de 24 horas
- **Programação normal das emissoras de rádio e televisão**: Prazo de 48 horas
- **Órgão da imprensa escrita**: Prazo de 72 horas
- **Conteúdo na internet**: Prazo de 72 horas após a retirada

### Referências legais
- Art. X da Lei Y

### Dicas de prova
- Entenda os prazos específicos para cada caso
- Não confunda os prazos com as regras de notificação e resposta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.156 (2)", "page_number": 156, "discipline": "Direito Eleitoral", "legal_refs": ["Art. X da Lei Y"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:45:31.678165+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=156", "doc_key": "02314bc5414a69c79791c93ea71ac8f5"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '9f37204a9dbed0c0b597645589e526c301f4cc8186af2a334f1adf38472be3be'),
  ('cpiuris2025::8f5832f47cf688c3095a4741c773cd67', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Reclamação de ofensa veiculada em imprensa escrita ou programação de rádio/televisão', '## Reclamação de ofensa veiculada em imprensa escrita ou programação de rádio/televisão

O ofendido pode solicitar a divulgação de resposta à ofensa veiculada em órgão da imprensa escrita ou em programa de rádio/televisão, dentro de prazos estabelecidos.

### Conceitos
- **Ofensa veiculada**: veiculação de uma afirmação falsa ou prejudicial em um órgão da imprensa escrita ou programa de rádio/televisão
- **Reclamação**: ação processual que visa a divulgação de resposta à ofensa veiculada
- **Imprensa escrita**: órgão da imprensa que publica artigos, notícias e outros conteúdos em formato impresso
- **Programação de rádio/televisão**: programas de transmissão de rádio ou televisão que podem veicular informações e notícias

### Referências legais
- Art. 58, §3º, I, e, Lei n.º 9.504/97

### Dicas de prova
- Distinção entre ofensa veiculada em órgão da imprensa escrita e programação de rádio/televisão
- Entendimento do prazo para a divulgação da resposta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.157 (1)", "page_number": 157, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 58, §3º, I, e, Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:46:08.186203+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=157", "doc_key": "8f5832f47cf688c3095a4741c773cd67"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'b9234f120a7b8db4f386e8cc5d5dee8c0744cbf3bef8fefee360014a6d4b6dc3'),
  ('cpiuris2025::789f575bdbdfe5a319668e81176c386e', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Notificação de decisão sobre veiculação de resposta a ofensa', '## Notificação de decisão sobre veiculação de resposta a ofensa

O ofendido deve ser notificado imediatamente da decisão, que indica os períodos para a veiculação da resposta. A resposta deve ser entregue à emissora geradora até 36 horas após a ciência da decisão.

### Conceitos
- **Notificação**: aviso formal
- **Veiculação**: exibição em público
- **Resposta a ofensa**: reagindo às acusações

### Referências legais
- Art. 58, §3º, III do Código Eleitoral

### Dicas de prova
- Pergunte sobre os prazos para a veiculação da resposta.
- Entenda o conceito de notificação e veiculação.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.157 (2)", "page_number": 157, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 58, §3º, III do Código Eleitoral"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:46:28.271567+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=157", "doc_key": "789f575bdbdfe5a319668e81176c386e"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '2e954e30bf174284ada23238ad955a21faf13be9652e3f8c29f0d8ef8d7ed928'),
  ('cpiuris2025::c0b7fc47f00550353d62f4078f8fc1f3', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Direito de Resposta em Propaganda Eleitoral', '## Direito de Resposta em Propaganda Eleitoral

O artigo 58 da Lei nº 9.504/97 estabelece regras para o direito de resposta em propaganda eleitoral, incluindo a suspensão de igual tempo para terceiros que cometerem ofensa, a divulgação da resposta do ofendido e os custos de veiculação.

### Conceitos
- **Direito de Resposta**: O direito do candidato ou partido político para responder à propaganda eleitoral adversária
- **Propaganda Eleitoral Irregular**: A propaganda que não cumpra com as regras estabelecidas pela lei
- **Representação**: O processo pelo qual o Ministério Público Eleitoral, partido político ou coligação ajuizam uma ação contra a propaganda eleitoral irregular
- **Suspensão de Tempo**: A igualdade de tempo para terceiros que cometerem ofensa
- **Divulgação da Resposta**: A obrigação do responsável pela propaganda original divulgar a resposta do ofendido

### Referências legais
- Art. 58, §3º, III, f; Art. 58, §3º, IV, a; Art. 58, §4º; Art. 58-A da Lei n.º 9.504/97

### Dicas de prova
- Entenda o conceito de direito de resposta e sua importância na eleição
- Conheça as regras para a propaganda eleitoral irregular e como elas são apuradas
- Aprenda a diferença entre suspensão de tempo e divulgação da resposta', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.158 (1)", "page_number": 158, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 58, §3º, III, f; Art. 58, §3º, IV, a; Art. 58, §4º; Art. 58-A da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:47:19.574655+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=158", "doc_key": "c0b7fc47f00550353d62f4078f8fc1f3"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'fbcb7bc70393c7ea2fd4d4931813bfe9ebf176eed8709dcd508b13656b453001'),
  ('cpiuris2025::0fdb3c563dbaf9566fa711be11a2f46d', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Responsabilidade pelo Divulgar Propaganda Irregular', '## Responsabilidade pelo Divulgar Propaganda Irregular

Os legitimados passivos são aqueles responsáveis pela divulgação de propaganda eleitoral irregular, com ou sem prévio conhecimento do beneficiário.

### Conceitos
- **Legitimado Passivo**: Responsável pela divulgação de propaganda eleitoral irregular
- **Beneficiário**: Pessoa que recebe a propaganda irregular
- **Propaganda Irregular**: Divulgação de informações não autorizada

### Referências legais
- Art. 40-B, Lei n.º 9.504/1997

### Dicas de prova
- Distinção entre responsável e beneficiário
- Importância do prazo de 48 horas para retirada ou regularização', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.158 (2)", "page_number": 158, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 40-B, Lei n.º 9.504/1997"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:47:38.398207+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=158", "doc_key": "0fdb3c563dbaf9566fa711be11a2f46d"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '495b3040be8684b2953fae72fde9ee268e2f5088240d746d5821e01eb4b6fd1f'),
  ('cpiuris2025::a8def2d00e13cb6514f5ffa8068c451f', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda Política e Recurso Devolutivo', '## Propaganda Política e Recurso Devolutivo

A Justiça Eleitoral deve notificar o representado para apresentação de defesa em 48 horas após receber a representação. O recurso cabe apenas no efeito devolutivo, nos termos do art. 257 do Código Eleitoral, dentro de 24 horas da publicação da decisão.

### Conceitos
- **Propaganda Política**: Ação política que visa influenciar a opinião pública
- **Recurso Devolutivo**: Mecanismo jurídico que permite apelar uma decisão para revisá-la
- **Efeito Devolutivo**: Recurso que busca anular ou modificar a decisão recorrida
- **Código Eleitoral**: Lei que regula o processo eleitoral no Brasil

### Referências legais
- Art. 257 do Código Eleitoral

### Dicas de prova
- Pergunte sobre a importância da notificação ao representado
- Entenda a diferença entre efeito devolutivo e não devolutivo', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.159", "page_number": 159, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 257 do Código Eleitoral"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:48:03.335638+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=159", "doc_key": "a8def2d00e13cb6514f5ffa8068c451f"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'e705330f276ba233776e8589fda815fd620fc58ceefdc38f4eb01420d48dfeaf'),
  ('cpiuris2025::5ff4d544ee65fae16df2887b259ba3e8', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda Eleitoral e Direito de Resposta', '## Propaganda Eleitoral e Direito de Resposta

Questões sobre propaganda eleitoral e direito de resposta, incluindo regras sobre veiculação de propaganda, tempo de resposta e sanções.

### Conceitos
- **Propaganda Eleitoral**: Veiculação de informações políticas durante a campanha eleitoral
- **Direito de Resposta**: O direito do candidato ou partido ofendido a responder à propaganda adversária
- **Horário Eleitoral Grátis**: Período durante o qual as emissoras de rádio e televisão transmitem sem cobrança
- **Ofensa Veiculada**: Mensagem considerada ofensiva ou difamatória na propaganda eleitoral

### Referências legais
- Art. 29 da Lei nº 4.737/1965 (Eleitoral)

### Dicas de prova
- Diferenciar entre propaganda eleitoral e direito de resposta
- Entender a importância do horário eleitoral gratuito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.160 (1)", "page_number": 160, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 29 da Lei nº 4.737/1965 (Eleitoral)"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:48:44.520704+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=160", "doc_key": "5ff4d544ee65fae16df2887b259ba3e8"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '54c64dc88614d835bb2d0f873f2c9d2a12183445317205d3c3e75b9bd739cfe3'),
  ('cpiuris2025::c382cbd1ea8779e7ec5909ee3d80930a', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Horário Eleitoral', '## Horário Eleitoral

O horário eleitoral não pode incluir propaganda das candidaturas a eleições majoritárias ou vice-versa, exceto para menção ao nome e número de candidatos.

### Conceitos
- **Propaganda eleitoral**: Promoção de candidaturas durante o horário eleitoral
- **Eleições majoritárias**: Eleições em que um partido ou coligação tem vaga garantida
- **Eleições proporcionais**: Eleições em que os votos são contados por partido ou coligação

### Referências legais
- Art. 53-A, da Lei n.º 9.504/97

### Dicas de prova
- Distinção entre propaganda majoritária e minoritária
- Importância de respeitar o horário eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.160 (2)", "page_number": 160, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 53-A, da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:49:05.150590+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=160", "doc_key": "c382cbd1ea8779e7ec5909ee3d80930a"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '75f90399b1fe67a41b36a5ced89721965fd61ed862c043eb1a7be8c6cdfc7b26'),
  ('cpiuris2025::f13aa552d260110c2577605bb5f87864', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Propaganda Política e Direito de Resposta', '## Propaganda Política e Direito de Resposta

O artigo 37, §4º, da Lei n.º 9.504/97 não exige que o bem de uso comum seja de acesso gratuito à população, mas pode ser considerado bem de uso comum mesmo se o acesso estiver condicionado a pagamento. Além disso, o artigo 45, inciso I, da Lei n.º 9.504/97 veda a veiculação de propaganda que possa identificar o entrevistado ou haja manipulação de dados em pesquisa eleitoral.

### Conceitos
- **Propaganda Política**: A publicidade política feita por candidatos, partidos ou coligações
- **Direito de Resposta**: O direito do candidato, partido ou coligação atingido para responder a uma ofensa feita contra ele
- **Lei n.º 9.504/97**: A Lei Eleitoral Brasileira

### Referências legais
- Art. 37, §4º, da Lei n.º 9.504/97
- Art. 45, inciso I, da Lei n.º 9.504/97
- Art. 58, §3º, III, a, da Lei n.º 9.504/97

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda que o artigo 37, §4º, da Lei n.º 9.504/97 não exige acesso gratuito ao bem de uso comum.
- Conheça a regra do artigo 45, inciso I, da Lei n.º 9.504/97 sobre veiculação de propaganda em pesquisa eleitoral.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.161 (1)", "page_number": 161, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 37, §4º, da Lei n.º 9.504/97", "Art. 45, inciso I, da Lei n.º 9.504/97", "Art. 58, §3º, III, a, da Lei n.º 9.504/97"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T00:49:45.161631+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=161", "doc_key": "f13aa552d260110c2577605bb5f87864"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'adc64034c2041ae7416cf9021396e8522458bc3a3e96ff134b6bc3d4d0fead29'),
  ('cpiuris2025::e8b360d9b4ae91993560f8af893bcddd', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Prazos para exercício do direito de resposta à Justiça Eleitoral', '## Prazos para exercício do direito de resposta à Justiça Eleitoral

O ofendido pode pedir o exercício do direito de resposta à Justiça Eleitoral em prazos específicos, dependendo da veiculação da ofensa.

### Conceitos
- **Horário eleitoral gratuito**: Período durante o qual as emissoras de rádio e televisão transmitem informações sobre a eleição
- **Programação normal**: Transmissões regulares das emissoras de rádio e televisão, sem interrupções ou especialidades
- **Imprensa escrita**: Publicações impressas, como jornais e revistas
- **Internet**: Rede global de computadores conectados à internet

### Referências legais
- Art. 58, §1º, da Lei n.º 9.504/97
- Art. 58, §3º, II, alínea c, da Lei n.º 9.504/97

### Dicas de prova
- Entenda a diferença entre horário eleitoral gratuito e programação normal
- Conheça as regras para o exercício do direito de resposta à Justiça Eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.161 (2)", "page_number": 161, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 58, §1º, da Lei n.º 9.504/97", "Art. 58, §3º, II, alínea c, da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:50:24.989459+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=161", "doc_key": "e8b360d9b4ae91993560f8af893bcddd"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'a1de5daf749f21db84a30d92990840db257e95cccf247689d31ce865aa1d449c'),
  ('cpiuris2025::fe2f4fd09164be5f7906ce0a962d757f', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Prazo para exercer o direito de resposta à Justiça Eleitoral', '## Prazo para exercer o direito de resposta à Justiça Eleitoral

O ofendido pode pedir o exercício do direito de resposta em até 24 horas após a veiculação da ofensa, durante o horário eleitoral gratuito.

### Conceitos
- **Prazo**: Período determinado para agir
- **Direito de resposta**: O direito do ofendido de se manifestar em relação a uma ofensa

### Referências legais
- Art. 58, §1º, I, da Lei n.º 9.504/97

### Dicas de prova
- Entenda o conceito de horário eleitoral gratuito e como afeta o prazo para exercer o direito de resposta
- Diferencie entre os prazos para exercer o direito de resposta em diferentes situações', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.162", "page_number": 162, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 58, §1º, I, da Lei n.º 9.504/97"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:50:45.313411+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=162", "doc_key": "fe2f4fd09164be5f7906ce0a962d757f"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'f214684d6ac691158238999536ed610af1b96ab93e5234d8558aa17b0a2c4983'),
  ('cpiuris2025::62b72eb28f71a9e99510339ff95dae64', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Organização das Seções Eleitorais e Mesas Receptoras dos Votos', '## Organização das Seções Eleitorais e Mesas Receptoras dos Votos

Descreve a divisão da Justiça Eleitoral em zonas eleitorais, seções eleitorais e mesas receptoras de votos, bem como as regras para sua instalação e funcionamento.

### Conceitos
- **Zona Eleitoral**: Espaço territorial sob jurisdição de um Juiz Eleitoral
- **Seção Eleitoral**: Local onde os eleitores comparecem para votar
- **Mesa Receptora de Votos**: Equipe de mesários nomeados pelo Juiz Eleitoral

### Referências legais
- Art. 135, §2º da Lei n.º 4.737/65
- Art. 135, §3º do CE
- Art. 135, §4º do CE
- Art. 135, §6º-A da Lei n.º 4.737/65
- Art. 135, §8º do CE
- Art. 120 do CE

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda a importância das zonas eleitorais e seções eleitorais na organização da Justiça Eleitoral.
- Conheça as regras para a instalação de mesas receptoras de votos e seus membros.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.164", "page_number": 164, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 135, §2º da Lei n.º 4.737/65", "Art. 135, §3º do CE", "Art. 135, §4º do CE", "Art. 135, §6º-A da Lei n.º 4.737/65", "Art. 135, §8º do CE", "Art. 120 do CE"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T00:51:20.952169+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=164", "doc_key": "62b72eb28f71a9e99510339ff95dae64"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'e361e8ee122dcc28b6bf8101796ba05ae428d6f3a4ae68fca0f6c3456d62c4f0'),
  ('cpiuris2025::7c0701091d444ca79368a2f48f8b5afc', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Mesa Receptora e Composição', '## Mesa Receptora e Composição

A Mesa Receptora é composta por um presidente, dois mesários e dois secretários, além de um suplente. Não podem ser nomeados membros da mesa receptora certos eleitores, autoridades ou funcionários em cargos de confiança.

### Conceitos
- **Mesa Receptora**: órgão responsável pela organização e condução das eleições
- **Presidente da Mesa Receptora**: líder da mesa receptora
- **Mesário**: membro da mesa receptora responsável por uma área específica
- **Secretário**: membro da mesa receptora responsável por uma área específica
- **Suplente**: membro da mesa receptora que substitui um membro em caso de ausência
- **Eleitor Inativo**: eleitor que não pode votar devido a certas condições

### Referências legais
- Art. 120, §2º, do Código Eleitoral
- Art. 63 da Lei n.º 9.504/97
- Art. 121 do CE

### Dicas de prova
- Entenda a composição da Mesa Receptora e quais são as restrições para o seu composicionamento
- Conheça as regras para a nomeação dos membros da mesa receptora', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.165", "page_number": 165, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 120, §2º, do Código Eleitoral", "Art. 63 da Lei n.º 9.504/97", "Art. 121 do CE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:52:07.503556+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=165", "doc_key": "7c0701091d444ca79368a2f48f8b5afc"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '792747cd93b1b006a79b5139dd4d82b9bed5364b0864ffba37ed81d602ebeaf2'),
  ('cpiuris2025::e99939d97aa76660dac0abcf2c531405', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Ordem da votação nas urnas eletrônicas', '## Ordem da votação nas urnas eletrônicas

A urna eletrônica exibe os painéis na ordem específica definida pela lei, com prioridade para certos grupos de eleitores, e a votação ocorre após a entrega das senhas e títulos aos eleitores presentes.

### Conceitos
- **urna eletrônica**: máquina eletrônica usada para realizar as eleições
- **painéis de votação**: exibição na urna eletrônica com a lista dos candidatos
- **prioridade no voto**: assegurada a prioridade para certos grupos de eleitores, como juízes, auxiliares de serviço e pessoas com deficiência
- **chamada zerézima**: documento que comprova que não há voto depositado previamente na urna

### Referências legais
- Art. 59, §3º do CE
- Art. 143, §1º da Lei n.º 4.737/65
- Art. 153 da Lei n.º 4.737/65

### Dicas de prova
- Entenda a ordem da votação nas urnas eletrônicas e a prioridade concedida a certos grupos de eleitores.
- Conheça o conceito de chamada zerézima e sua importância na garantia do voto justo.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.166", "page_number": 166, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 59, §3º do CE", "Art. 143, §1º da Lei n.º 4.737/65", "Art. 153 da Lei n.º 4.737/65"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:52:43.722231+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=166", "doc_key": "e99939d97aa76660dac0abcf2c531405"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '48760960cf1c6e298f7c437ff653361618f92ba57feb7c9a88b3d9a1d2853d61'),
  ('cpiuris2025::0d5d2bd01b297f5983f9f085f6eb353c', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Identificação do Eleitor e Voto em Trânsito', '## Identificação do Eleitor e Voto em Trânsito

O eleitor pode ser identificado por meio de título eleitoral, documento público de identificação com foto ou outros documentos específicos. Além disso, os eleitores em trânsito têm direito a votar em urnas especiais nas capitais dos Estados e nos Municípios com mais de 100 mil eleitores.

### Conceitos
- **Título Eleitoral**: documento que identifica o eleitor
- **Documento Público de Identificação**: documento emitido por órgão federal ou estadual
- **Carteira de Identificação Civil**: documento emitido pelo órgão responsável pela identidade
- **Certidão de Nascimento ou Casamento**: documento emitido pelo cartório de registro civil
- **Certificado de Quitação do Serviço Militar**: documento que comprova a quitação do serviço militar
- **Passaporte**: documento de identidade emitido pelo governo
- **Voto em Trânsito**: direito ao voto para eleitores em trânsito

### Referências legais
- Art. 2º da Lei 12.037/2009
- Art. 91-A, parágrafo único, da Lei n.º 9.504/97

### Jurisprudência
- MP 905/2019

### Dicas de prova
- Distinção entre documentos de identificação civil e militares
- Regras para habilitação do eleitor em trânsito', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.167 (1)", "page_number": 167, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 2º da Lei 12.037/2009", "Art. 91-A, parágrafo único, da Lei n.º 9.504/97"], "jurisprudence": ["MP 905/2019"], "confidence": 0.8, "extracted_at": "2026-05-27T00:53:23.137447+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=167", "doc_key": "0d5d2bd01b297f5983f9f085f6eb353c"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'a0f12c067d37bdc7675b9df58d1d36c924fb2d2b8b2e2923ccc9b500144757c5'),
  ('cpiuris2025::fd35a9ae6665ab177d204d9dc2c1a26e', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Voto em Trânsito', '## Voto em Trânsito

Eleitores que se encontram em trânsito dentro da unidade da Federação de seu domicílio podem votar nas eleições para vários cargos, exceto Prefeito e Vereador. Eleitores no exterior podem votar apenas na eleição para Presidente da República.

### Conceitos
- **Eleitor**: cidadão brasileiro com direito ao voto
- **Domicílio eleitoral**: local onde o eleitor está inscrito no cartório eleitoral
- **Trânsito**: movimento de veículo ou pessoa em uma via pública

### Referências legais
- Art. 7º da Lei nº 4.737/1965
- ...

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Distinção entre voto em trânsito e voto no exterior
- Importância de verificar o cargo para o qual se está votando', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.167 (2)", "page_number": 167, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 7º da Lei nº 4.737/1965", "..."], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T00:53:56.257930+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=167", "doc_key": "fd35a9ae6665ab177d204d9dc2c1a26e"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '3fc99eeb9eca023befc6e9bb0484c8c2f8321f64a57af9ac612a3bcb7f22a434'),
  ('cpiuris2025::2f32cee0e79347435be188f961b473de', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Votação por Cédulas e Impressão do Voto', '## Votação por Cédulas e Impressão do Voto

Discute-se a impressão do voto nas eleições, com discussões sobre violação do sigilo e liberdade do voto.

### Conceitos
- **Segredo do Voto**: Garantia constitucional que assegura a privacidade do voto
- **Retrocesso de Direitos**: Princípio que impede o retrocesso de direitos conquistados para dar lugar a modelos superados
- **Voto Impresso**: Sistema que imprime o voto nas eleições, com discussões sobre sua constitucionalidade
- **Urnas Eletrônicas**: Máquinas que registram os votos eletronicamente e depositam em local lacrado
- **Proporcionalidade e Razoabilidade**: Princípios que exigem que as medidas tomadas sejam proporcionais e razoáveis para o objetivo pretendido
- **Custos**: Altos custos impostos pela implantação do sistema de votação eletrônica

### Referências legais
- Art. 59-A da Lei n.º 9.504/97
- Súmula N da STF
- ADI n.º 5889

### Jurisprudência
- RE 123456
- Tema repetitivo sobre a inconstitucionalidade do voto impresso

### Dicas de prova
- Entenda o princípio da proibição do retrocesso de direitos
- Conheça as implicações da impressão do voto nas eleições
- Análise a proporcionalidade e razoabilidade da medida', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.168", "page_number": 168, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 59-A da Lei n.º 9.504/97", "Súmula N da STF", "ADI n.º 5889"], "jurisprudence": ["RE 123456", "Tema repetitivo sobre a inconstitucionalidade do voto impresso"], "confidence": 0.8, "extracted_at": "2026-05-27T00:54:40.675062+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=168", "doc_key": "2f32cee0e79347435be188f961b473de"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'a3171865abc264e513dae07a1de54e0f795616ebd4e5b86ea18d67b44cb645d6'),
  ('cpiuris2025::0c93e3051f56f00312ce7eca599a6e0f', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Nulidades na Votação', '## Nulidades na Votação

A aplicação da lei eleitoral exige que o juiz atenda aos fins a que ela se dirige, abstendo-se de pronunciar nulidades sem demonstração de prejuízo. A declaração de nulidade não pode ser requerida pela parte que lhe deu causa nem a ela aproveitar.

### Conceitos
- **Votação nula**: votação realizada fora das regras estabelecidas
- **Votação anulável**: votação que pode ser anulada por motivo superveniente ou de ordem constitucional
- **Pas de nullité sans grief**: princípio que proíbe a declaração de nulidade sem demonstração de prejuízo
- **Declaração de nulidade**: anulação do voto ou eleição por motivo legítimo

### Referências legais
- Art. 220 do Código Eleitoral
- Art. 221 do Código Eleitoral
- Art. 223 da Lei n.º 4.737

### Jurisprudência
- RE 123456
- ...

### Dicas de prova
- Entenda o conceito de ''pas de nullité sans grief'' e sua aplicação no Direito Eleitoral
- Conheça as regras para a declaração de nulidade de votação
- Análise do artigo 220 e 221 do Código Eleitoral', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.169", "page_number": 169, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 220 do Código Eleitoral", "Art. 221 do Código Eleitoral", "Art. 223 da Lei n.º 4.737"], "jurisprudence": ["RE 123456", "..."], "confidence": 0.8, "extracted_at": "2026-05-27T00:55:16.331183+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=169", "doc_key": "0c93e3051f56f00312ce7eca599a6e0f"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'c0607de1f9cbcdc700fa35ed494fdbb8f078f326163ec066efcfca22f20030dd'),
  ('cpiuris2025::8f95f41a301708cb11e017e6dbc2905e', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Eleição Suplementar', '## Eleição Suplementar

A eleição suplementar é realizada após a decisão da Justiça Eleitoral, independentemente do número de votos anulados, quando o candidato eleito em pleito majoritário for desclassificado por indeferimento do registro de sua candidatura.

### Conceitos
- **Eleição Suplementar**: Realização de nova eleição após decisão da Justiça Eleitoral
- **Votação Anulada**: Votos anulados em pleito original
- **Desclassificação**: Indeferimento do registro de candidatura em virtude de cassação do diploma ou mandato
- **Eleições Indiretas**: Eleições realizadas a menos de 6 meses do final do mandato
- **Eleições Diretas**: Eleições realizadas em demais casos

### Referências legais
- Art. 224, §3º, do Código Eleitoral

### Jurisprudência
- ADI n.º 5525 - STF
- RE n.º 1096.029 - TSE

### Dicas de prova
- Entenda a diferença entre eleições indiretas e diretas.
- Conheça as hipóteses de novas eleições em caso de vacância decorrente da extinção do mandato de cargos majoritários por causas eleitorais.', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.170", "page_number": 170, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 224, §3º, do Código Eleitoral"], "jurisprudence": ["ADI n.º 5525 - STF", "RE n.º 1096.029 - TSE"], "confidence": 0.8, "extracted_at": "2026-05-27T00:56:03.714052+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=170", "doc_key": "8f95f41a301708cb11e017e6dbc2905e"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', '965f0d7aa127b9ced4235a0b47b0b64ae098dcc9d53a005f3c0db71667339dab'),
  ('cpiuris2025::4ee3db9b7306870a3faace13b27b3c97', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Justificativa de não comparecimento à eleição', '## Justificativa de não comparecimento à eleição

O eleitor que não vota e não se justifica perante o juiz eleitoral até 30 dias após a realização da eleição, incorre em multa. Além disso, não pode realizar certas atividades sem prova de ter votado na última eleição.

### Conceitos
- **Obrigatório**: Dever obrigatório para os eleitores que têm mais de 18 e menos de 70 anos e são alfabetizados.
- **Multa**: Pena imposta pelo juiz eleitoral por não votar e não se justificar perante ele até 30 dias após a realização da eleição.
- **Prova de voto**: Documentação necessária para comprovar que o eleitor votou na última eleição.

### Referências legais
- Art. 7º do CE

### Dicas de prova
- Distinção entre as atividades proibidas sem prova de voto
- Importância da justificativa para evitar multa', '{"corpus": "cp_iuris_2025", "source_file": "/Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf", "source_ref": "IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf · p.171 (1)", "page_number": 171, "discipline": "Direito Eleitoral", "legal_refs": ["Art. 7º do CE"], "jurisprudence": [], "confidence": 0.8, "extracted_at": "2026-05-27T00:56:33.799920+00:00", "url": "file:///Users/luizcarlos/Downloads/IURIS - Direito Eleitoral - Vol. 13 - 2025.pdf#page=171", "doc_key": "4ee3db9b7306870a3faace13b27b3c97"}'::jsonb, '{"materia": "Direito Eleitoral"}'::jsonb, 'cp_iuris_2025', 'e0980cff02268d9c197411eb18a41977a5f7be79cb401aeb5cb381f4601b0ca1'),
  ('cpiuris2025::4c096e0af9f5eeb077153e99b4d85cdc', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Contratação de Cabos Eleitorais Durante a Campanha', '## Contratação de Cabos Eleitorais Durante a Campanha

A contratação de cabos eleitorais não gera vínculo empregatício com os candidatos ou partidos contratantes, e há uma limite para o número de cabos eleitorais nas campanhas eleitorais.

### Conceitos
- **Vínculo Empregatício**: Não é gerado pela contratação de pessoal para prestação de serviços
- **Cabos Eleitorais**: Pessoas contratadas durante a campanha eleitoral para manifestarem apoio explícito aos candidatos ou partidos políticos
- **Contratação de Pessoal**: Não gera vínculo empregatício com os candidatos ou partidos contratantes
- **Limite de Cabos Eleitorais**: Não excederá a 1% do eleitorado por candidato em municípios com até 30 mil eleitores

### Referências legais
- Art. 100 da Lei n.º 9.504/97
- Art. 100-A da Lei n.º 9.504/97

### Dicas de prova
- Entenda a diferença entre vínculo empregatício e contratação de pessoal
