  ('cpiuris2025::6267746797c700063d0df4496712edd2', 'doutrina', 'cp_iuris', 'Direito Eleitoral — Limites das Contratações de Cabos Eleitorais', '## Limites das Contratações de Cabos Eleitorais

Os limites das contratações de cabos eleitorais são estabelecidos para cada cargo, variando de acordo com o estado ou distrito federal, e são excluídos certas categorias de pessoas.

### Conceitos
- **Contratação de Cabo Eleitoral**: A contratação de cabos eleitorais para apoiar a campanha de um candidato
- **Limites de Contratação**: Os limites estabelecidos para a contratação de cabos eleitorais, variando de acordo com o cargo e o estado ou distrito federal
- **Exclusão de Categorias**: As categorias de pessoas que não podem ser contratadas como cabos eleitorais, incluindo militância não remunerada, pessoal administrativo e fiscais

### Referências legais
- Art. 100-A, §6º do CE
- Súmula N da STF

